#[derive(Clone, Debug)]
struct Grant {
    label: String,
    did: Option<String>,
    ro: bool,
    exp: u64,
    /// 历史消息可见时间窗（毫秒；None=全部历史）——如 6h=只可见最近 6 小时
    /// 发生的消息，更早的在网关层过滤（session 视图 + 全 UI 的 session/page
    /// 响应改写），owner 可随时调整，读路径每请求生效。
    window_ms: Option<u64>,
    /// **逐人能力勾选**（§3.14.1 «默认取任务声明，owner 逐项收紧»）。
    ///
    /// 形状：四个固定能力 id 的布尔值 `{ "session.read": bool, "session.input": bool,
    /// "agent.view": bool, "scope.switch": bool }`（人话标签背后的机器 id）。
    /// `None` = **继承任务级 caps**（`Share.caps`）——老记录没有该字段，加载为 None，
    /// 绝不报错（向后兼容纪律同 group_id）。缺项同样回落任务级声明（逐项收紧）。
    caps: Option<serde_json::Value>,
    /// **逐人可见范围覆盖**（可选，§3.20 S→O 投影 `{space,sessions,windowMs}`）。
    /// `None` = 继承任务级 `Share.state_visibility`——老记录没有该字段，加载为 None，
    /// 绝不报错（同 caps/groupId 纪律）。生效时**只能收紧不能放大**（`effective_visibility`）。
    visibility: Option<serde_json::Value>,
}

// ═══════════════════════════════════════════════════════════════════════════
// 设备级 P/A 策略（2026-10-27，task-32 P1；设计稿：eval/vnet/device-permission-model-20261027.md）
//
// 已定裁决（Lead 2026-10-27）：
//   ① 同账号非源设备默认 = 任务声明 ∩ 设备策略，不再走 owner 通配；
//   ② source PC（创建分享的设备 = adminDevice）保留 owner 通配 + 配置权，运行时单独审计；
//   ③ 协作者多设备默认继承账号策略；新设备高风险 A 默认关；设备覆盖只能收紧；
//   ④ 入口设备（ticket/claim）是策略主体；`x-myco-client` 验签设备是署名主体；
//      两者不一致时 A 写操作严格拒绝并审计（P 仍按入口设备策略）；
//   ⑤ 署名：同账号 `【设备·<设备名><DID尾4>】`，其他账号 `【MYCO·<昵称><DID尾4>】`，
//      无设备/旧客户端保持旧头；
//   ⑥ 高风险 A：model.select / settings.write / terminal.exec / files.read / files.write
//      默认关；任务声明 ∩ 设备策略双门；source_admin 例外；bearer 不给。
//
// 兼容纪律：全部字段**可选**——老 dsh-shares.json 缺键即默认（policyVersion=0=legacy），
// 缺 `devicePolicies` 时行为与改造前逐字节一致；`DSH_SHARE_DEVICE_POLICY=legacy` 可整链回滚。
// ═══════════════════════════════════════════════════════════════════════════

/// 设备级策略（Share.devicePolicies 的元素；落盘 camelCase）。
#[derive(Clone, Debug, Default, PartialEq)]
struct DevicePolicy {
    account: String,
    device: String,
    label: String,
    role: String,
    caps: Option<serde_json::Value>,
    visibility: Option<serde_json::Value>,
    ro: Option<bool>,
    exp: u64,
    disabled: bool,
    updated_at: u64,
    updated_by: String,
    source: String,
}

impl DevicePolicy {
    fn to_json(&self) -> serde_json::Value {
        json!({
            "account": self.account, "device": self.device, "label": self.label,
            "role": self.role, "caps": self.caps, "visibility": self.visibility,
            "ro": self.ro, "exp": self.exp, "disabled": self.disabled,
            "updatedAt": self.updated_at, "updatedBy": self.updated_by, "source": self.source,
        })
    }

    fn from_json(v: &serde_json::Value) -> Option<Self> {
        let device = v.get("device").and_then(|x| x.as_str())?.trim().to_string();
        if device.is_empty() {
            return None;
        }
        Some(Self {
            account: v
                .get("account")
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .trim()
                .to_string(),
            device,
            label: v
                .get("label")
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .trim()
                .to_string(),
            role: v
                .get("role")
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .trim()
                .to_string(),
            caps: v.get("caps").filter(|x| x.is_object()).cloned(),
            visibility: v
                .get("visibility")
                .filter(|x| x.is_object())
                .map(visibility_normalize),
            ro: v.get("ro").and_then(|x| x.as_bool()),
            exp: v.get("exp").and_then(|x| x.as_u64()).unwrap_or(0),
            disabled: v.get("disabled").and_then(|x| x.as_bool()).unwrap_or(false),
            updated_at: v.get("updatedAt").and_then(|x| x.as_u64()).unwrap_or(0),
            updated_by: v
                .get("updatedBy")
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .to_string(),
            source: v
                .get("source")
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .to_string(),
        })
    }

    #[cfg_attr(not(test), allow(dead_code))]
    fn role_is_admin(&self) -> bool {
        self.role == ROLE_SOURCE_ADMIN
    }
}

