pub(crate) const VIEWER_HTTP_DEFAULT_PORT: u16 = 24011;

fn viewer_http_port_from(raw: Option<&str>) -> u16 {
    raw.and_then(|v| v.trim().parse::<u16>().ok())
        .filter(|p| *p > 0)
        .unwrap_or(VIEWER_HTTP_DEFAULT_PORT)
}

