// ══ dsh-web-proxy 控制面推送（D 组，2026-11-09）══════════════════════════
//
// 终态架构：P/A 判定引擎已迁 dsh-web-proxy（对拍 15 向量/28 用例逐位一致）。
// myco 是策略的家（授权数据源），控制面把【原始授权数据】(authz 格式) 推给插件，
// 插件用自己的引擎计算并执行。签名 HMAC-SHA256（密钥插件首启生成，myco 纯读者）。

/// 显式 canonical JSON（递归按 key 排序）——不赌 serde_json 的 feature 配置。
fn canonical_json(v: &serde_json::Value) -> String {
    match v {
        serde_json::Value::Object(m) => {
            let mut keys: Vec<&String> = m.keys().collect();
            keys.sort();
            let inner: Vec<String> = keys
                .iter()
                .map(|k| format!("{}:{}", serde_json::json!(k), canonical_json(&m[k.as_str()])))
                .collect();
            format!("{{{}}}", inner.join(","))
        }
        serde_json::Value::Array(a) => {
            let inner: Vec<String> = a.iter().map(canonical_json).collect();
            format!("[{}]", inner.join(","))
        }
        _ => v.to_string(),
    }
}

/// 推一条真实授权（authz 格式）到 dsh-web-proxy 控制面。`share_id`+`grant_did` 定位。
#[cfg(feature = "gui")]
pub(crate) async fn web_proxy_push_authz(share_id: &str, grant_did: &str) -> Result<u16, String> {
    use hmac::{Hmac, Mac};
    use sha2::Sha256;
    type HmacSha256 = Hmac<Sha256>;

    let share = shares()
        .shares
        .lock()
        .unwrap()
        .iter()
        .find(|s| s.id == share_id)
        .cloned()
        .ok_or("分享不存在")?;
    let grant = share
        .grants
        .iter()
        .find(|g| g.did.as_deref() == Some(grant_did))
        .cloned()
        .ok_or("该设备的 grant 行不存在")?;

    // 读插件状态文件（controlPort）与密钥
    let home = std::env::var("USERPROFILE").unwrap_or_else(|_| "C:\\Users\\you".into());
    let listener: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(format!(r"{home}\.dsh\web-listener.json"))
            .map_err(|e| format!("web-listener.json 读取失败（插件未起？）: {e}"))?,
    )
    .map_err(|e| format!("web-listener.json 解析失败: {e}"))?;
    let data_port = listener.get("port").and_then(|p| p.as_u64()).unwrap_or(17878);
    // 契约默认：controlPort = 数据口-1（17878→17877）。文件暂缺该字段时回退
    // （2026-11-09 真环境首推发现插件写文件滞后；17877 实听即用）。
    let control_port = listener
        .get("controlPort")
        .and_then(|p| p.as_u64())
        .unwrap_or(data_port.saturating_sub(1)) as u16;
    let key_b64 = std::fs::read_to_string(format!(r"{home}\.dsh\web-proxy-control.key"))
        .map_err(|e| format!("控制密钥读取失败: {e}"))?;
    let key = base64_url_decode(key_b64.trim());

    // viewerLabel（2026-11-09 署名下放插件）：谁在此设备打字→`【设备·笔记本·6Cqf】：`
    // 的 label 只有 myco 知道（设备名册/账号归属/委任状），算好随 policy 下发；
    // 插件在 viewer 口转发 prompt 时盖头（owner 口不签）。不推=不签（向后兼容）。
    // 注意：不走 signature_label_with_assert 的 Legacy 分支（该分享 policy 是旧模式时
    // 它会退化成「设备·<grant label>」无尾号 —— 2026-11-09 联调实测）；这里直接按
    // 完整词形拼：同账号 `设备·名·尾4`，跨账号 `MYCO·昵称·尾4`（与 proxy_http 一致）。
    let viewer_label = {
        let dev = grant.did.as_deref().unwrap_or("").trim();
        let tail = did_tail4(dev);
        let my = myco_core::identity::account_did().unwrap_or_default();
        let owner_account = share_owner_account(&share, &my);
        let resolved = resolve_account_did(dev);
        // 同账号判定（2026-11-09 联调真案）：resolve_account_did 依赖 authorized-dids
        // 的 owner_root_did，手工授权行该字段常空 → 自家笔记本被误判跨账号（label 出
        // MYCO 而非 设备）。补两条可信依据：①resolve 结果比账号；②**账号 JSON 里登记了
        // 该设备 DID**（accounts_load 的设备清单=本账号设备，是 identity 的权威数据）。
        let registered_own_device = {
            let needle = dev;
            !needle.is_empty()
                && myco_core::identity::accounts_load()
                    .iter()
                    .any(|a| a.to_string().contains(needle))
        };
        // ③本机设备名册认识它（display_name 有真名、且不是 tail 兜底）——名册只登记
        // 自家账号设备，好友设备查不到名（display_name 会退化为尾号）。
        let name = device_display_name(dev);
        let known_by_registry = !name.is_empty() && name != tail && name != "设备";
        let same_account = (!resolved.is_empty()
            && myco_core::identity::account_did_eq(&resolved, &owner_account))
            || registered_own_device
            || known_by_registry;
        let name = device_display_name(dev);
        if dev.is_empty() || tail.is_empty() {
            String::new()
        } else if same_account {
            if name.is_empty() || name == tail {
                format!("设备·{tail}")
            } else {
                format!("设备·{name}·{tail}")
            }
        } else {
            let nick = crate::share_auth::shared().author_name_for(&resolved);
            let nick = nick.trim().strip_prefix('…').unwrap_or(nick.trim());
            if nick.is_empty() || nick == tail {
                format!("MYCO·{tail}")
            } else {
                format!("MYCO·{}·{tail}", sanitize_client_name(nick))
            }
        }
    };
    let now = now_ms();
    let mut body = serde_json::json!({
        "viewerDid": grant_did,
        "authz": {
            "taskCaps": share.caps,
            "taskVis": share.state_visibility,
            "grant": {
                "label": grant.label, "did": grant.did, "ro": grant.ro,
                "exp": grant.exp, "windowMs": grant.window_ms,
                "caps": grant.caps, "visibility": grant.visibility,
            },
            "admin": grant_is_owner(&grant),
            "viewerLabel": viewer_label,
        },
        "openPort": true,
        "nonce": format!("myco-{now}-{}", &grant_did[grant_did.len().saturating_sub(6)..]),
        "ts": now,
    });
    let canonical = canonical_json(&body);
    let sig = {
        let mut mac = HmacSha256::new_from_slice(&key).map_err(|e| format!("密钥无效: {e}"))?;
        mac.update(canonical.as_bytes());
        let out = mac.finalize().into_bytes();
        // 契约：sig = base64url 无 padding（与密钥文件编码同族；hex 已实测被拒 bad-sig）
        base64_url_nopad(&out)
    };
    if let serde_json::Value::Object(ref mut m) = body {
        m.insert("sig".into(), serde_json::json!(sig));
    }
    eprintln!(
        "[web-proxy-push] authz → 127.0.0.1:{control_port} viewer={grant_did}（canonical {}B）",
        canonical.len()
    );
    let resp = reqwest::Client::new()
        .post(format!("http://127.0.0.1:{control_port}/policy"))
        .json(&body)
        .timeout(std::time::Duration::from_secs(8))
        .send()
        .await
        .map_err(|e| format!("POST /policy 失败: {e}"))?;
    let status = resp.status().as_u16();
    let text = resp.text().await.unwrap_or_default();
    eprintln!("[web-proxy-push] 响应 {status}: {}", text.chars().take(200).collect::<String>());
    if !(200..300).contains(&status) {
        return Err(format!("插件拒绝({status}): {}", text.chars().take(200).collect::<String>()));
    }
    // 响应里的 port（viewer 专属口）透传给调用方
    let port = serde_json::from_str::<serde_json::Value>(&text)
        .ok()
        .and_then(|v| v.get("port").and_then(|p| p.as_u64()).map(|p| p as u16))
        .unwrap_or(0);
    Ok(port)
}

/// base64url 编码无 padding（sig 用；与密钥文件编码同族）。
fn base64_url_nopad(data: &[u8]) -> String {
    const TBL: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut out = String::new();
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
        out.push(TBL[(n >> 18) as usize & 63] as char);
        out.push(TBL[(n >> 12) as usize & 63] as char);
        if chunk.len() > 1 {
            out.push(TBL[(n >> 6) as usize & 63] as char);
        }
        if chunk.len() > 2 {
            out.push(TBL[n as usize & 63] as char);
        }
    }
    out
}

/// base64url 解码（密钥文件是 base64url 一行；标准字母表 + -_ 替换）。
fn base64_url_decode(s: &str) -> Vec<u8> {
    let std = s.replace('-', "+").replace('_', "/");
    // 补 padding
    let pad = (4 - std.len() % 4) % 4;
    let std = format!("{std}{}", "=".repeat(pad));
    // 不引 base64 crate：手写解码（密钥 32B，量小）
    let mut out = Vec::new();
    let mut buf = 0u32;
    let mut bits = 0u32;
    for c in std.bytes().filter(|c| !(*c as char == '=')) {
        let v = match c {
            b'A'..=b'Z' => (c - b'A') as u32,
            b'a'..=b'z' => (c - b'a' + 26) as u32,
            b'0'..=b'9' => (c - b'0' + 52) as u32,
            b'+' => 62,
            b'/' => 63,
            _ => continue,
        };
        buf = (buf << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((buf >> bits) as u8);
        }
    }
    out
}

/// `POST /api/webproxy/pushAuthz` — body {shareId, grantDid}。返回 {ok, viewerPort}。
#[cfg(feature = "gui")]
async fn handle_webproxy_push_authz(Json(body): Json<serde_json::Value>) -> Response {
    let share_id = body.get("shareId").and_then(|v| v.as_str()).unwrap_or("");
    let grant_did = body.get("grantDid").and_then(|v| v.as_str()).unwrap_or("");
    if share_id.is_empty() || grant_did.is_empty() {
        return Json(json!({"ok": false, "error": "缺 shareId 或 grantDid"})).into_response();
    }
    match web_proxy_push_authz(share_id, grant_did).await {
        Ok(port) => {
            Json(json!({
                "ok": true,
                "viewerPort": port,
            }))
            .into_response()
        }
        Err(e) => Json(json!({"ok": false, "error": e})).into_response(),
    }
}

/// `GET /api/vnet/stun` —— NAT 类型（mapping×filtering）+ 公网出口地址。
///
/// 缓存 60s：STUN 探测要多轮 UDP 往返，看板/CLI 高频轮询不该每次打网络。
#[cfg(feature = "gui")]
async fn handle_vnet_stun() -> Response {
    static CACHE: std::sync::LazyLock<std::sync::Mutex<Option<(u64, serde_json::Value)>>> =
        std::sync::LazyLock::new(|| std::sync::Mutex::new(None));
    let now = now_ms();
    if let Some((at, v)) = CACHE.lock().unwrap().as_ref().cloned() {
        if now.saturating_sub(at) < 60_000 {
            return Json(v).into_response();
        }
    }
    let profile = tokio::time::timeout(
        std::time::Duration::from_secs(15),
        crate::vnet::stun::detect_nat_profile(),
    )
    .await;
    let v = match profile {
        Ok(Ok(info)) => {
            // 公网出口多源兜底：单个 STUN 可能被网络策略拦（真机 cloudflare 返回空）。
            let public = tokio::task::spawn_blocking(|| {
                for srv in [
                    "stun.chat.bilibili.com:3478",
                    "stun.l.google.com:19302",
                    "stun.cloudflare.com:3478",
                ] {
                    if let Ok(a) = crate::vnet::stun::query_stun(srv, 0) {
                        return Some(a);
                    }
                }
                None
            })
            .await
            .ok()
            .flatten();
            json!({
                "ok": true,
                "schema": 1,
                "publicAddr": public.map(|a| a.to_string()),
                "mapping": format!("{:?}", info.mapping),
                "filtering": format!("{:?}", info.filtering),
                "difficulty": format!("{:?}", info.difficulty()),
                "strategy": info.strategy(),
                "ipv6": info.ipv6_addr.map(|a| a.to_string()),
            })
        }
        Ok(Err(e)) => json!({ "ok": false, "schema": 1, "error": format!("NAT 探测失败：{e}") }),
        Err(_) => json!({ "ok": false, "schema": 1, "error": "NAT 探测超时（15s）" }),
    };
    if v.get("ok").and_then(|b| b.as_bool()).unwrap_or(false) {
        *CACHE.lock().unwrap() = Some((now, v.clone()));
    }
    Json(v).into_response()
}

/// `GET /api/vnet/allowPorts` —— 当前生效的端口白名单（默认表 ∪ env ∪ 用户授权）。
#[cfg(feature = "gui")]
async fn handle_vnet_allow_ports() -> Response {
    let defaults = crate::p2p_tunnel::TUNNEL_DEFAULT_PORTS.to_vec();
    let user = crate::p2p_tunnel::vnet_user_ports();
    let effective = crate::p2p_tunnel::tunnel_allowed_ports_snapshot();
    Json(json!({ "ok": true, "defaults": defaults, "user": user, "effective": effective }))
        .into_response()
}

/// `POST /api/vnet/allowPorts {add:[...], remove:[...]}` —— 增/删用户授权端口（持久化，立即生效）。
///
/// 用途（2026-10-22）：默认白名单只覆盖 22/3389/5555/9000/9100/13911；用户要转发
/// 任意端口（如 8080 HTTP、WebRTC 信令口）时，先在本机授权一次即可。安全边界：
/// 只能从**本机管理面**（127.0.0.1:3102，不经隧道/公网）调用；隧道握手仍走设备签名+归属闸。
#[cfg(feature = "gui")]
async fn handle_vnet_set_allow_ports(Json(body): Json<serde_json::Value>) -> Response {
    let mut cur = crate::p2p_tunnel::vnet_user_ports();
    let mut added = Vec::new();
    let mut removed = Vec::new();
    if let Some(arr) = body.get("add").and_then(|v| v.as_array()) {
        for x in arr {
            if let Some(p64) = x.as_u64() {
                let port = p64 as u16;
                if port > 0 && !cur.contains(&port) {
                    cur.push(port);
                    added.push(port);
                }
            }
        }
    }
    if let Some(arr) = body.get("remove").and_then(|v| v.as_array()) {
        for x in arr {
            if let Some(p64) = x.as_u64() {
                let port = p64 as u16;
                if cur.contains(&port) {
                    cur.retain(|q| *q != port);
                    removed.push(port);
                }
            }
        }
    }
    if let Err(e) = crate::p2p_tunnel::vnet_set_user_ports(cur.clone()) {
        return Json(json!({ "ok": false, "error": e })).into_response();
    }
    let effective = crate::p2p_tunnel::tunnel_allowed_ports_snapshot();
    audit(
        "vnet-allow-ports",
        &[
            ("added", &format!("{:?}", added)),
            ("removed", &format!("{:?}", removed)),
        ],
    );
    Json(json!({ "ok": true, "added": added, "removed": removed, "user": cur, "effective": effective })).into_response()
}

/// vnet 持久化转发表（`%APPDATA%\youling\vnet-forwards.json`）。
fn vnet_forwards_path() -> std::path::PathBuf {
    myco_core::config::config_dir().join("vnet-forwards.json")
}

pub(crate) fn vnet_load_kept() -> Vec<serde_json::Value> {
    std::fs::read_to_string(vnet_forwards_path())
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default()
}

#[cfg(feature = "gui")]
fn vnet_save_kept(list: &[serde_json::Value]) {
    let p = vnet_forwards_path();
    // 原子写（tmp+fsync+rename）：kept 文件里存着用户约定的 localPort，写一半被
    // 杀/断电 → 文件残缺 → 重启后固定口"失忆"（2026-10-23 漂移事故同类根因）。
    crate::p2p_tunnel::write_file_atomic(
        &p,
        &serde_json::to_string_pretty(list).unwrap_or_default(),
    );
}

/// kept 文件的读-改-写互斥（keep / rdp / 清理面并发时不得互相覆盖条目——
/// 丢一条 = 重启后那条固定口没人重建）。
static VNET_KEPT_WRITE: std::sync::Mutex<()> = std::sync::Mutex::new(());

/// 持久化一条转发的**存储层**（`/api/vnet/keep` 与 `/api/vnet/rdp` 共用）。
///
/// 语义与旧 `handle_vnet_keep` 完全一致（2026-10-22 抽出，避免远程桌面另写一份）：
/// - `prefer_local` → 写进程内首选口 + 记录里的 `localPort`（keeper 重建时沿用）；
/// - **已在册的条目只在带了 localPort 时才改**（不覆盖用户原有 label/端口）；
/// - 新条目才写 label。
/// CLI 变体桩：vnet 转发栈（p2p_tunnel）随 GUI 编译——headless 无隧道可建，
/// 落盘记录同样跳过（无恢复者）。调用方（vnet_env / keep / rdp 面）在 CLI 下
/// 得到 no-op 而非编译错。
#[cfg(not(feature = "gui"))]
pub(crate) fn vnet_keep_upsert(
    _device: &str,
    _port: u16,
    _prefer_local: Option<u16>,
    _label: Option<&str>,
) {
}

#[cfg(feature = "gui")]
pub(crate) fn vnet_keep_upsert(
    device: &str,
    port: u16,
    prefer_local: Option<u16>,
    label: Option<&str>,
) {
    if let Some(lp) = prefer_local {
        crate::p2p_tunnel::set_preferred_local(device, port, Some(lp));
    }
    let _w = VNET_KEPT_WRITE.lock().unwrap_or_else(|e| e.into_inner());
    let mut list = vnet_load_kept();
    let existing = list.iter().position(|v| {
        v.get("device").and_then(|d| d.as_str()) == Some(device)
            && v.get("port").and_then(|p| p.as_u64()) == Some(port as u64)
    });
    match existing {
        Some(i) => {
            if let Some(lp) = prefer_local {
                list[i]["localPort"] = json!(lp);
                vnet_save_kept(&list);
            }
        }
        None => {
            let mut rec = json!({ "device": device, "port": port,
                                  "label": label.unwrap_or("") });
            if let Some(lp) = prefer_local {
                rec["localPort"] = json!(lp);
            }
            list.push(rec);
            vnet_save_kept(&list);
        }
    }
}

/// `POST /api/vnet/keep {device, port}` —— 持久化一条转发（重启/断线后自动重建）。
#[cfg(feature = "gui")]
async fn handle_vnet_keep(Json(body): Json<serde_json::Value>) -> Response {
    let device = body
        .get("device")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let port = body.get("port").and_then(|v| v.as_u64()).unwrap_or(0) as u16;
    if device.is_empty() || port == 0 {
        return Json(json!({ "ok": false, "error": "缺 device 或 port" })).into_response();
    }
    if !crate::p2p_tunnel::tunnel_port_allowed(port) {
        return Json(json!({ "ok": false, "error": format!("端口 {port} 不在 vnet 白名单") }))
            .into_response();
    }
    // 2026-10-22 固定本地口：给远程桌面/SSH 这类"配置里的地址不能变"的用途。
    // localPort 写进 kept 记录，keeper 重建时按它重新 bind（占用才回落并告警）。
    let prefer_local = body
        .get("localPort")
        .and_then(|v| v.as_u64())
        .map(|v| v as u16);
    vnet_keep_upsert(
        &device,
        port,
        prefer_local,
        body.get("label").and_then(|v| v.as_str()),
    );
    // 立即开一次（传输层已保证：带固定口时要么绑上它，要么 Err——不回落随机口）
    match crate::vnet_forward::route_open(&device, port, prefer_local).await {
        Ok(local) => {
            // 租约登记（vnet 层统一状态机；口冲突=明确失败不静默换口）
            let lease_key = crate::vnet_lease::LeaseKey {
                consumer_device: crate::vnet_lease::self_consumer_device(),
                kind: "forward".into(),
                device: device.clone(),
                port,
                share_id: String::new(),
            };
            if let Err(e) = crate::vnet_lease::lease_open(&lease_key, local) {
                crate::vnet_lease::lease_upstream_fail(&lease_key, &e);
            }
            if let Some(lp) = prefer_local {
                if local != lp {
                    audit(
                        "vnet-keep-fail",
                        &[
                            ("device", &device),
                            ("port", &port.to_string()),
                            ("want", &lp.to_string()),
                            ("got", &local.to_string()),
                            ("reason", "fixed-local-mismatch"),
                        ],
                    );
                    return Json(json!({
                        "ok": false,
                        "kept": true,
                        "error": format!("固定本地口 {lp} 未能建立（实际 {local}）；不会静默改用其它端口"),
                        "localPort": local,
                        "requestedLocalPort": lp,
                    }))
                    .into_response();
                }
            }
            audit(
                "vnet-keep",
                &[
                    ("device", &device),
                    ("port", &port.to_string()),
                    ("local", &local.to_string()),
                ],
            );
            Json(json!({
                "ok": true,
                "kept": true,
                "localPort": local,
                "requestedLocalPort": prefer_local
            }))
            .into_response()
        }
        Err(e) => {
            // 固定口被占等失败必须留痕（现场只看到"keep ok 但口不对"就是审计缺失的锅）
            audit(
                "vnet-keep-fail",
                &[
                    ("device", &device),
                    ("port", &port.to_string()),
                    (
                        "want",
                        &prefer_local.map(|p| p.to_string()).unwrap_or_default(),
                    ),
                    ("reason", "open-failed"),
                ],
            );
            Json(json!({ "ok": false, "kept": true, "error": e, "requestedLocalPort": prefer_local }))
                .into_response()
        }
    }
}

/// `POST /api/vnet/unkeep {device, port}` —— 移除持久化转发（不关当前隧道）。
#[cfg(feature = "gui")]
async fn handle_vnet_unkeep(Json(body): Json<serde_json::Value>) -> Response {
    let device = body
        .get("device")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let port = body.get("port").and_then(|v| v.as_u64()).unwrap_or(0) as u16;
    let removed = {
        let _w = VNET_KEPT_WRITE.lock().unwrap_or_else(|e| e.into_inner());
        let mut list = vnet_load_kept();
        let before = list.len();
        list.retain(|v| {
            !(v.get("device").and_then(|d| d.as_str()) == Some(device.as_str())
                && v.get("port").and_then(|p| p.as_u64()) == Some(port as u64))
        });
        if list.len() != before {
            vnet_save_kept(&list);
        }
        before - list.len()
    };
    Json(json!({ "ok": true, "removed": removed })).into_response()
}

/// `POST /api/vnet/close {device, port}` —— 关闭端口隧道（释放本地端口）。
#[cfg(feature = "gui")]
async fn handle_vnet_close(Json(body): Json<serde_json::Value>) -> Response {
    let device = body
        .get("device")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let port = body.get("port").and_then(|v| v.as_u64()).unwrap_or(0) as u16;
    if device.is_empty() || port == 0 {
        return Json(json!({ "ok": false, "error": "缺 device 或 port" })).into_response();
    }
    // 统一入口：vnet 条目和 legacy 条目都关（各自幂等），返回值表示"关之前有没有"。
    let existed = crate::vnet_forward::route_local_port(&device, port).is_some();
    crate::vnet_forward::route_close(&device, port);
    let closed = existed;
    audit(
        "vnet-close",
        &[
            ("device", &device),
            ("port", &port.to_string()),
            ("closed", &closed.to_string()),
        ],
    );
    Json(json!({ "ok": true, "closed": closed, "device": device, "port": port })).into_response()
}

/// `POST /api/vnet/leg-drop {device}` —— 在**持有活跃腿的 GUI 进程内**强杀目标设备的活跃腿。
/// 保留逻辑会话与端口记忆，供真实断腿/RESUME 测试；不要另起 CLI 进程杀（它看不到 ACTIVE_LEGS）。
#[cfg(feature = "gui")]
async fn handle_vnet_leg_drop(Json(body): Json<serde_json::Value>) -> Response {
    let device = body
        .get("device")
        .or_else(|| body.get("did"))
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    if device.is_empty() {
        return Json(json!({ "ok": false, "error": "缺 device" })).into_response();
    }
    let aborted = crate::p2p_tunnel::debug_leg_drop(&device);
    Json(json!({
        "ok": true,
        "device": device,
        "activeLegsAborted": aborted,
        "activeLegsCloseSignaled": aborted,
        "warning": if aborted == 0 { "no_active_leg_matched" } else { "" },
    }))
    .into_response()
}

/// `GET /api/vnet/forwards` —— 列出当前活跃的端口隧道。
///
/// 2026-11-11 事故 §2：额外给出 `backoffs[]`（离线设备重建退避），让"某个 DID 的
/// 端口在反复重建"这件事从接口上一眼可辨，不必再去数日志行。
#[cfg(feature = "gui")]
async fn handle_vnet_forwards() -> Response {
    let now = chrono::Utc::now().timestamp_millis().max(0) as u64;
    let mut list: Vec<serde_json::Value> = crate::p2p_tunnel::tunnel_list_snapshot()
        .into_iter()
        .map(|(dev, port, local)| json!({ "device": dev, "port": port, "localPort": local, "transport": "legacy" }))
        .collect();
    // vnet 条目也要露出来——否则"新传输层回归"从接口上根本看不见走了哪条腿。
    for (local, dev, port) in crate::vnet_forward::list_vnet_forwards() {
        // 同一个 (device, port) 上 vnet 与 legacy 一般不会并存；万一并存以 vnet 为准
        list.retain(|v| {
            !(v.get("device").and_then(|d| d.as_str()) == Some(dev.as_str())
                && v.get("port").and_then(|p| p.as_u64()) == Some(port as u64))
        });
        let (backoff_ms, next_retry_at_ms, _) = crate::vnet_lease::rebuild_backoff_info(&dev, port, now);
        list.push(json!({
            "device": dev,
            "port": port,
            "localPort": local,
            "transport": "vnet",
            "backoffMs": backoff_ms,
            "nextRetryAtMs": next_retry_at_ms,
        }));
    }
    // 退避中的条目（可能当前没有活隧道，所以单列而不是只挂在上面）
    let backoffs: Vec<serde_json::Value> = crate::vnet_lease::rebuild_backoff_views(now)
        .into_iter()
        .map(|(device, port, backoff_ms, next_retry_at_ms, last_fail_ms, consecutive, reason)| {
            json!({
                "device": device,
                "port": port,
                "backoffMs": backoff_ms,
                "nextRetryAtMs": next_retry_at_ms,
                "lastFailMs": last_fail_ms,
                "consecutiveFailures": consecutive,
                "reason": reason,
            })
        })
        .collect();
    Json(json!({ "ok": true, "forwards": list, "backoffs": backoffs })).into_response()
}

/// `GET /api/vnet/leases` —— vnet 端点租约表（L4；task-vnet-endpoint-lease §4）。
///
/// 只读快照：键五元组 + localPort + state/health + listener/recentConnections。
/// 证据入口：`eval/vnet/r-lease-lifecycle.py`。
///
/// 2026-11-11 事故 §2：新增 `backoffMs` / `nextRetryAtMs` / `backoffLevel` /
/// `consecutiveFailures` —— 离线设备的指数退避（1s→5s→30s→2min→10min）必须能从
/// 接口看见，否则"为什么这条租约不重建了"又只能靠数日志猜。
#[cfg(feature = "gui")]
async fn handle_vnet_leases() -> Response {
    let now = chrono::Utc::now().timestamp_millis().max(0) as u64;
    let leases: Vec<serde_json::Value> = crate::vnet_lease::leases_snapshot()
        .into_iter()
        .map(|l| {
            let (backoff_ms, next_retry_at_ms, consecutive) =
                crate::vnet_lease::rebuild_backoff_info(&l.key.device, l.key.port, now);
            json!({
                "consumerDevice": l.key.consumer_device,
                "kind": l.key.kind,
                "device": l.key.device,
                "port": l.key.port,
                "shareId": l.key.share_id,
                "localPort": l.local_port,
                "state": l.state.as_str(),
                "health": l.health.as_str(),
                "listenerPresent": l.listener_present,
                "recentConnections": l.recent_connections,
                "lastSuccessMs": l.last_success_ms,
                "lastFailMs": l.last_fail_ms,
                "failReason": l.fail_reason,
                "releaseReason": l.release_reason,
                "backoffMs": backoff_ms,
                "nextRetryAtMs": next_retry_at_ms,
                "backoffLevel": consecutive,
                "consecutiveFailures": consecutive,
            })
        })
        .collect();
    Json(json!({ "ok": true, "leases": leases })).into_response()
}

/// `GET /api/vnet/netstate` —— L1-L4 网络状态快照（跨重启复用的探测底座）。
#[cfg(feature = "gui")]
async fn handle_vnet_netstate() -> Response {
    Json(crate::vnet_lease::netstate_snapshot()).into_response()
}

// ═══════════════════════════════════════════════════════════════════════
// `/api/vnet/status` —— AOP Phase 3 统一状态面（2026-10-24，只读）
//
// 用户需求「给外部提供 127.0.0.1:xxx 的状态」：手机/笔记本/外部工具要一眼看到
// PC 上有哪些转发口在听、各自的目标/延迟/模式。数据源全部**现成只读**：
//   · 活跃隧道：`tunnel_list_snapshot`（进程内 TUNNELS）
//   · 持久化转发（含 label/固定口）：自家 `vnet_load_kept()`（vnet-forwards.json）
//   · 网络指纹/S 层：`local_ipv6_snapshot` + `route_hit_stats` + vnet-contexts.json
//     （S 层自己落盘的文件，直接读——同源同值不另造）
//   · 隧道健康：`tunnel_mode`/`tunnel_in_use`/`tunnel_fail_streak`/`tunnel_reverse_live`
//     + contexts 文件里 per-device 的 rtt_ms/preferred_mode/成败计数
// 纪律：只读（不动任何状态、不发探测网络请求——公网 v4 探测在 /api/vnet/diag）；
// 拿不到的字段就不出（宁缺毋假）。
// ═══════════════════════════════════════════════════════════════════════

/// 网络指纹（**纯函数**）：IPv6 全局地址取前 3 组（与 p2p_tunnel::
/// network_id_from_addrs 同口径；它未导出，这里按同一规则实现并用单测钉住样例，
/// 防两处漂移——后续把那侧升 pub(crate) 后应删掉这份）。
fn vnet_status_net_id(v6_addrs: &[String]) -> String {
    let global = v6_addrs.iter().filter(|a| {
        !a.starts_with("fe80") && !a.starts_with("fd") && !a.starts_with("::1") && !a.is_empty()
    });
    for a in global {
        let parts: Vec<&str> = a.split(':').collect();
        if parts.len() >= 3 {
            return parts[..3].join(":");
        }
    }
    "unknown".to_string()
}

/// 命中率（**纯函数**）：cache / (cache + race + fail)，全 0 → None（不编数字）。
fn vnet_status_hit_rate(cache: u64, race: u64, fail: u64) -> Option<f64> {
    let total = cache + race + fail;
    if total == 0 {
        return None;
    }
    Some(cache as f64 / total as f64)
}

/// S 层档案（`vnet-contexts.json`）只读快照：contexts 按 last_active 新→旧。
fn vnet_status_contexts() -> Vec<serde_json::Value> {
    let Ok(s) = std::fs::read_to_string(myco_core::config::config_dir().join("vnet-contexts.json"))
    else {
        return Vec::new();
    };
    let Ok(v) = serde_json::from_str::<serde_json::Value>(&s) else {
        return Vec::new();
    };
    let mut out: Vec<serde_json::Value> = v
        .get("contexts")
        .and_then(|c| c.as_array())
        .cloned()
        .unwrap_or_default();
    out.sort_by_key(|c| c.get("last_active").and_then(|x| x.as_u64()).unwrap_or(0));
    out.reverse();
    out
}

/// kept + 活跃隧道合并（**纯函数**，单测直击）：kept 条目在前（带 label/固定口），
/// 进程内活跃但未 keep 的动态隧道补在后；同一 (device, port) 只留一条。
fn vnet_status_merge_forwards(
    kept: &[serde_json::Value],
    live: &[(String, u16, u16)],
) -> Vec<(String, u16, u16, bool)> {
    let mut out: Vec<(String, u16, u16, bool)> = Vec::new();
    let mut seen: Vec<(String, u16)> = Vec::new();
    for k in kept {
        let Some(dev) = k.get("device").and_then(|d| d.as_str()) else {
            continue;
        };
        let Some(port) = k.get("port").and_then(|p| p.as_u64()).map(|p| p as u16) else {
            continue;
        };
        if dev.trim().is_empty() || port == 0 {
            continue;
        }
        let local = k
            .get("localPort")
            .and_then(|p| p.as_u64())
            .map(|p| p as u16)
            .unwrap_or(0);
        seen.push((dev.to_string(), port));
        out.push((dev.to_string(), port, local, true));
    }
    for (dev, port, local) in live {
        if seen.iter().any(|(d, p)| d == dev && *p == *port) {
            continue;
        }
        out.push((dev.clone(), *port, *local, false));
    }
    out
}

/// 设备显示名：好友备注名 > 授权设备名 > did 尾 4（只读、best-effort）。
#[cfg(feature = "gui")]
fn vnet_status_device_name(did: &str) -> String {
    if let Some(n) = crate::chat_service::friend_display_name(did) {
        if !n.trim().is_empty() {
            return n;
        }
    }
    let t: String = did.chars().rev().take(4).collect();
    if t.is_empty() {
        "未知设备".to_string()
    } else {
        format!("…{}", t.chars().rev().collect::<String>())
    }
}

/// `GET /api/vnet/status` —— 统一状态面（网络指纹 + S 层统计 + 转发口全表 + 隧道健康）。
/// 只读；`/api/vnet/forwards` 保留不动，本端点是其超集。
#[cfg(feature = "gui")]
async fn handle_vnet_status() -> Response {
    let v6 = crate::p2p_tunnel::local_ipv6_snapshot();
    let ctxs = vnet_status_contexts();
    let net_id = {
        let id = vnet_status_net_id(&v6);
        if id == "unknown" {
            // 无全局 v6（如纯 v4 网络）：退用 S 层最近活跃上下文的指纹（落盘时算好的）
            ctxs.first()
                .and_then(|c| c.get("network_id").and_then(|x| x.as_str()))
                .unwrap_or("unknown")
                .to_string()
        } else {
            id
        }
    };
    let has_public_ip6 = v6
        .iter()
        .any(|a| !a.starts_with("fe80") && !a.starts_with("fd") && *a != "::1");
    // S 层统计：路由命中（进程内原子量）+ 活跃上下文的累计连接数
    let (cache_hits, race_hits, cache_fails) = crate::p2p_tunnel::route_hit_stats();
    let active = ctxs.first().cloned().unwrap_or(json!({}));
    let peer_routes = active.get("peer_routes").cloned().unwrap_or(json!({}));
    let route_of = |dev: &str| peer_routes.get(dev).cloned();
    // 转发口全表：kept（label/固定口）∪ 活跃隧道（动态，含 vnet 新传输层）
    let kept = vnet_load_kept();
    let mut live = crate::p2p_tunnel::tunnel_list_snapshot();
    // vnet 活跃转发也要进这张表——否则 vnet 模式下状态面看着"没有隧道"
    crate::vnet_forward::merge_into_live_snapshot(&mut live);
    let forwards: Vec<serde_json::Value> = vnet_status_merge_forwards(&kept, &live)
        .into_iter()
        .map(|(dev, port, kept_local, is_kept)| {
            let listening_local = crate::vnet_forward::route_local_port(&dev, port);
            let r = route_of(&dev);
            // vnet 隧道的实际数据路径（P2P IPv6 / P2P UDP / Relay）。
            // "直连还是中继"只能从传输层拿，靠"能连上"是分不出来的（中继一样能连）。
            let path_info = crate::vnet_forward::vnet_path_info(&dev, port);
            json!({
                "localPort": listening_local.unwrap_or(kept_local),
                "listening": listening_local.is_some(),
                "alive": crate::vnet_forward::route_in_use(&dev, port, 60_000),
                "kept": is_kept,
                "target_device": dev,
                "target_device_name": vnet_status_device_name(&dev),
                "target_port": port,
                "transport": if crate::vnet_forward::vnet_local_port(&dev, port).is_some() { "vnet" } else { "legacy" },
                "path": path_info.as_ref().map(|(p, _)| p.clone()),
                "p2pPeer": path_info.as_ref().map(|(_, a)| a.clone()).filter(|a| a != "-"),
                "direct": path_info
                    .as_ref()
                    .map(|(p, _)| p.to_ascii_uppercase().contains("P2P"))
                    .unwrap_or(false),
                "label": kept.iter()
                    .find(|k| k.get("device").and_then(|d| d.as_str()) == Some(dev.as_str())
                        && k.get("port").and_then(|p| p.as_u64()) == Some(port as u64))
                    .and_then(|k| k.get("label").and_then(|l| l.as_str()))
                    .filter(|l| !l.trim().is_empty())
                    .unwrap_or(""),
                "mode": crate::p2p_tunnel::tunnel_mode(&dev, port),
                "rtt_ms": r.as_ref().and_then(|x| x.get("rtt_ms")).and_then(|x| x.as_u64()),
                "fail_streak": crate::p2p_tunnel::tunnel_fail_streak(&dev, port),
            })
        })
        .collect();
    // 隧道健康：按设备聚合（活跃上下文里的 per-device 路由统计 + 当前实况）
    let mut tunnel_devices: Vec<String> = Vec::new();
    for (dev, _, _) in &live {
        if !tunnel_devices.iter().any(|d| d == dev) {
            tunnel_devices.push(dev.clone());
        }
    }
    let tunnels: Vec<serde_json::Value> = tunnel_devices
        .iter()
        .map(|dev| {
            let r = route_of(dev);
            json!({
                "device": dev,
                "device_name": vnet_status_device_name(dev),
                "connected": true,
                "mode": crate::p2p_tunnel::tunnel_mode(dev, 0)
                    .or_else(|| r.as_ref().and_then(|x| x.get("preferred_mode")).and_then(|x| x.as_str()))
                    .unwrap_or("unknown"),
                "rtt_ms": r.as_ref().and_then(|x| x.get("rtt_ms")).and_then(|x| x.as_u64()),
                "success_count": r.as_ref().and_then(|x| x.get("success_count")).and_then(|x| x.as_u64()),
                "fail_count": r.as_ref().and_then(|x| x.get("fail_count")).and_then(|x| x.as_u64()),
                "reverse_live": crate::p2p_tunnel::tunnel_reverse_live(dev),
            })
        })
        .collect();
    Json(json!({
        "ok": true,
        "network": {
            "id": net_id,
            "interfaces": v6.iter().map(|a| json!({ "kind": "ipv6", "addr": a })).collect::<Vec<_>>(),
            "hasPublicIp6": has_public_ip6,
        },
        "s_layer": {
            "active_context": active.get("network_id").cloned().unwrap_or(json!("unknown")),
            "contexts_count": ctxs.len(),
            "cache_hits": cache_hits,
            "race_hits": race_hits,
            "cache_fails": cache_fails,
            "hit_rate": vnet_status_hit_rate(cache_hits, race_hits, cache_fails),
            "total_connects": active.get("total_connects").and_then(|x| x.as_u64()),
            "successful_connects": active.get("successful_connects").and_then(|x| x.as_u64()),
        },
        "forwards": forwards,
        "tunnels": tunnels,
        // 2026-11-06 目标⑥：设备级直连/中继可见性（设备列表一眼看出 direct/relay）
        "devices": vnet_status_devices(),
    }))
    .into_response()
}

/// 双向直连聚合的纯判定：state + direct。
fn vnet_direct_state(outbound_p2p: u64, inbound_p2p: bool) -> (&'static str, bool) {
    let outbound = outbound_p2p > 0;
    let direct = outbound || inbound_p2p;
    let state = if outbound && inbound_p2p {
        "direct"
    } else if direct {
        "direct(one-way)"
    } else {
        "relay"
    };
    (state, direct)
}

/// 入站 P2P 只能提升路径可见性，不得把已有出站 P2P 覆盖成 Relay。
fn vnet_inbound_last_path(current: &str) -> String {
    if current.to_ascii_uppercase().contains("P2P") {
        current.to_string()
    } else {
        "P2P (inbound)".to_string()
    }
}

/// 入站地址映射必须唯一：同一 /64 下两台设备都匹配时返回 None，不能猜。
fn inbound_device_for_entry(entry: &str, prefixes: &[(String, String)]) -> Option<String> {
    if entry.starts_with("did:") {
        return Some(entry.to_string());
    }
    let mut matches = prefixes
        .iter()
        .filter(|(_, prefix)| {
            if prefix.is_empty() {
                return false;
            }
            if prefix.contains(':') {
                // IPv6 按已知 /64 前缀匹配。
                entry.contains(prefix.as_str())
            } else {
                // IPv4 必须按 IP 整段匹配，避免 .5 误吃 .50。
                entry.split(':').next().map(|ip| ip == prefix).unwrap_or(false)
            }
        })
        .map(|(device, _)| device);
    let first = matches.next()?.clone();
    if matches.next().is_some() {
        None
    } else {
        Some(first)
    }
}

/// 目标⑥的实现：按 vnet **双向**通道聚合每台设备的直连/中继状态。
/// 口径（AOP_KG patch，2026-11-06）：任一方向存在 P2P 通道即 direct——
///   · 出站：本端→设备的 forward 有任一 P2P（不再要求全部）
///   · 入站：设备→本端的 P2P 通道（vnet server status 的 inbound_p2p 字段，
///     vnet 未补时优雅降级为空 → 行为等同仅出站判定）
/// state 分 direct（双向）/ direct(one-way)（单向）/ relay。
fn vnet_status_devices() -> serde_json::Value {
    let mut seen: std::collections::BTreeMap<String, serde_json::Value> = std::collections::BTreeMap::new();
    // ① 出站：本端作为客户端的 forward
    for (_local, dev, port) in crate::vnet_forward::list_vnet_forwards() {
        let path = crate::vnet_forward::vnet_path_info(&dev, port)
            .map(|(p, _)| p)
            .unwrap_or_else(|| "unknown".into());
        let e = seen.entry(dev.clone()).or_insert_with(|| json!({
            "device": dev,
            "fw": 0,
            "p2p": 0,
            "inbound_p2p": false,
        }));
        e["fw"] = json!(e["fw"].as_u64().unwrap_or(0) + 1);
        if path.to_ascii_uppercase().contains("P2P") {
            e["p2p"] = json!(e["p2p"].as_u64().unwrap_or(0) + 1);
        }
        e["last_path"] = json!(path);
    }
    // ② 入站：本端作为服务端收到的对端 P2P 通道（vnet 补 inbound_p2p 字段后生效）
    for dev in list_inbound_p2p_devices() {
        let e = seen.entry(dev.clone()).or_insert_with(|| json!({
            "device": dev,
            "fw": 0,
            "p2p": 0,
            "inbound_p2p": false,
        }));
        e["inbound_p2p"] = json!(true);
        let cur = e["last_path"].as_str().unwrap_or("").to_string();
        e["last_path"] = json!(vnet_inbound_last_path(&cur));
    }
    let mut out: Vec<serde_json::Value> = Vec::new();
    for (_, mut e) in seen {
        let p2p = e["p2p"].as_u64().unwrap_or(0);
        let inbound_direct = e["inbound_p2p"].as_bool().unwrap_or(false);
        let (state, direct) = vnet_direct_state(p2p, inbound_direct);
        let m = e.as_object_mut().unwrap();
        m.remove("fw");
        m.remove("p2p");
        m.remove("inbound_p2p");
        e["direct"] = json!(direct);
        e["state"] = json!(state);
        e["device_name"] = json!(vnet_status_device_name(e["device"].as_str().unwrap_or("")));
        out.push(e);
    }
    json!(out)
}

/// 入站 P2P 通道的对端设备列表：遍历本机 vnet server status 文件读 `inbound_p2p=`
/// 字段。vnet 给的是**地址**（IP:port，30s 活跃窗，2026-11-06 67EDFD26 起），
/// 地址→设备匹配用我侧已知的每设备 p2p_peer 地址前缀（v6 取 /64 前四段、
/// v4 完整匹配）——即本端到该设备的出站 client status 里见过的地址。
/// vnet 未来若出 set_peer_did 注入 API 可换精确 DID（did: 前缀直收）。
fn list_inbound_p2p_devices() -> Vec<String> {
    // 每设备已知地址前缀（出站 client status 的 p2p_peer）
    let mut dev_prefix: Vec<(String, String)> = Vec::new();
    for (_local, dev, port) in crate::vnet_forward::list_vnet_forwards() {
        if let Some((_, addr)) = crate::vnet_forward::vnet_path_info(&dev, port) {
            if addr == "-" || addr.is_empty() {
                continue;
            }
            let prefix = if addr.starts_with('[') {
                addr.trim_start_matches('[')
                    .split(']')
                    .next()
                    .unwrap_or("")
                    .split(':')
                    .take(4)
                    .collect::<Vec<_>>()
                    .join(":")
            } else {
                addr.split(':').next().unwrap_or("").to_string()
            };
            if !prefix.is_empty() && !dev_prefix.iter().any(|(d, _)| *d == dev) {
                dev_prefix.push((dev, prefix));
            }
        }
    }
    let mut out = Vec::new();
    for f in crate::vnet::list_status_files() {
        let Ok(body) = std::fs::read_to_string(&f) else { continue };
        if !body.starts_with("role=server") {
            continue;
        }
        for line in body.lines() {
            if let Some(v) = line.strip_prefix("inbound_p2p=") {
                for entry in v.split(',').map(|s| s.trim()).filter(|s| !s.is_empty()) {
                    if let Some(dev) = inbound_device_for_entry(entry, &dev_prefix) {
                        if !out.iter().any(|d| *d == dev) {
                            out.push(dev);
                        }
                    }
                }
            }
        }
    }
    out
}

/// `GET /api/vnet/ports` —— 返回 vnet 白名单端口（客户端可发现能力）。
#[cfg(feature = "gui")]
async fn handle_vnet_ports() -> Response {
    let ports = crate::p2p_tunnel::tunnel_allowed_ports_snapshot();
    Json(json!({ "ok": true, "ports": ports })).into_response()
}

// ═══════════════════════════════════════════════════════════════════════
// 远程桌面「一键打开」（2026-10-22 · vnet 固定口 → 临时 .rdp → mstsc）
//
// 用户视角：任务卡/落地页上点一下「打开远程桌面」，直接连上对面那台 PC 的桌面。
// 地址永远是 `127.0.0.1:<固定口>`（默认 23389），不管隧道是这次新建的还是早已存在。
//
// 分三层，各自可单测：
//   ① 参数闸 `rdp_validate`：device 必须**已知 DID**（本机 or authorized-dids 名册）、
//      port 只认 3389（SSH 22 之类不做 RDP）、localPort 不许占本机保留口；
//   ② 隧道 `ensure`：先 `keep`（固定口持久化，断线/重启由 keeper 重建），再复用/新建；
//      若本机该口已有服务（例：正在跑的另一个 myco 实例）就**直接用它**（`preexisting`）
//      —— 地址真的通，就不该因为"这条隧道不是本进程开的"而拒绝；
//   ③ 落地 `write_rdp_file` + `launch_mstsc`：**参数数组**起 `mstsc.exe`，只传文件路径，
//      不拼 shell 字符串（`user` 只进文件、且先净化，杜绝 .rdp 行注入）。
//
// 安全边界：路由只挂在**本机管理面**（`start_local_api` 只 bind 127.0.0.1，与
// `/api/vnet/*` 同一模型；公网网关 `:13911` 不注册这两条）。就算被本机某个页面打，
// 最坏结果是"本机弹一个远程桌面窗口"——没有对外开的监听、没有任意命令执行。
// ═══════════════════════════════════════════════════════════════════════

/// RDP 目标端口：白名单只有 3389（22 是 SSH，别的端口不做 RDP）。
#[cfg(feature = "gui")]
const RDP_PORT: u16 = 3389;
/// 默认固定本地口（与 `eval/vnet/manual.md` 映射表同口径）。
#[cfg(feature = "gui")]
const RDP_DEFAULT_LOCAL: u16 = 23389;
/// 本机管理面保留口：固定口不许占用（会把自己的管理面/网关顶掉）。
#[cfg(feature = "gui")]
const RDP_RESERVED_LOCALS: &[u16] = &[3102, 9100, 13911];

/// `127.0.0.1:<port>`（唯一允许写进 .rdp/页面的地址形态）。
#[cfg(feature = "gui")]
fn rdp_addr(local_port: u16) -> String {
    format!("127.0.0.1:{local_port}")
}

/// 设备 DID 是否**已知**：本机设备，或已授权设备名册（`authorized-dids.json`）里的成员。
///
/// 为什么不用 presence 兜底：刚配对/刚启动的对端可能还没上报 presence，但名册已经有一行；
/// 反之名册没有的 DID 不该被这个接口拿来探路。
#[cfg(feature = "gui")]
fn rdp_device_known(device: &str) -> bool {
    let d = device.trim();
    if !d.starts_with("did:") || d.len() < 12 {
        return false;
    }
    if let Ok((mine, _)) = myco_core::identity::device_identity() {
        if !mine.is_empty() && myco_core::identity::did_equiv(&mine, d) {
            return true;
        }
    }
    // 2026-10-22 真案：笔记本上「打开远程桌面」被拒——PC 是同账号设备，但不在
    // share_auth 的"分享名册"里（那个表只记"别人分享给我的"）。
    // 判定应该用**本机已知设备全集**：① 已持久化转发目标 ② presence 名册里的任一设备。
    if vnet_load_kept().iter().any(|rec| {
        rec.get("device")
            .and_then(|v| v.as_str())
            .map(|x| myco_core::identity::did_equiv(x, d))
            .unwrap_or(false)
    }) {
        return true;
    }
    // 当前活隧道里的目标设备也算已知（restore 起来但 kept 尚未落盘的窗口）
    if crate::p2p_tunnel::tunnel_list_snapshot()
        .iter()
        .any(|t| myco_core::identity::did_equiv(&t.0, d))
    {
        return true;
    }
    crate::share_auth::shared()
        .list()
        .iter()
        .any(|row| myco_core::identity::did_equiv(&row.did, d))
}

/// `device` 缺省时的兜底：kept 里第一条 3389 记录的 device → 再兜底本机设备 DID。
///
/// 落地页/卡片可以只写 `?fixed=23389`；本机已有的 RDP 映射（`vnet-forwards.json`）
/// 就是最可信的答案。两者都没有才回空（由调用方报"缺 device"）。
#[cfg(feature = "gui")]
fn rdp_default_device() -> String {
    for rec in vnet_load_kept() {
        if rec.get("port").and_then(|p| p.as_u64()) == Some(RDP_PORT as u64) {
            if let Some(d) = rec.get("device").and_then(|v| v.as_str()) {
                if !d.trim().is_empty() {
                    return d.trim().to_string();
                }
            }
        }
    }
    myco_core::identity::device_identity()
        .map(|(d, _)| d)
        .unwrap_or_default()
}

/// 参数闸（纯函数，单测直击）：只放行"已知设备 + 3389 + 合法固定口"。
///
/// 顺序有意为之：**端口/固定口先判**（纯参数问题，与身份无关，报错最直接），
/// 设备白名单最后（要读身份/名册，最贵）。
#[cfg(feature = "gui")]
fn rdp_validate(device: &str, port: u16, local_port: u16) -> Result<(), String> {
    if port != RDP_PORT {
        return Err(format!(
            "RDP 只支持目标端口 {RDP_PORT}（收到 {port}；22 是 SSH，不走远程桌面）"
        ));
    }
    if !crate::p2p_tunnel::tunnel_port_allowed(port) {
        return Err(format!("端口 {port} 不在 vnet 白名单"));
    }
    if local_port < 1024 {
        return Err(format!("localPort {local_port} 太小（<1024 是系统保留段）"));
    }
    if RDP_RESERVED_LOCALS.contains(&local_port) {
        return Err(format!(
            "localPort {local_port} 是 myco 本机保留口（管理面/网关/p2p）"
        ));
    }
    if device.trim().is_empty() {
        return Err("缺 device（目标设备 DID）".into());
    }
    if !rdp_device_known(device) {
        return Err(format!(
            "device 不是已知 DID（本机设备或已授权设备名册里没有）：{device}"
        ));
    }
    Ok(())
}

/// `.rdp` 文件正文（CRLF；mstsc 只认这一套键）。
///
/// `user` 必须已经过 [`rdp_sanitize_user`]：这里只做"写行"，不做净化——
/// 一旦允许换行就能注入 `alternate shell:s:...` 这种危险键。
#[cfg(feature = "gui")]
fn rdp_file_text(user: &str, address: &str) -> String {
    format!("full address:s:{address}\r\nusername:s:{user}\r\nprompt for credentials:i:1\r\n")
}

/// 用户名净化：**在第一个控制字符处截断**（防 .rdp 行注入，残渣不拼进用户名），限长 64。
#[cfg(feature = "gui")]
fn rdp_sanitize_user(user: &str) -> String {
    user.chars()
        .take_while(|c| !c.is_control())
        .take(64)
        .collect::<String>()
        .trim()
        .to_string()
}

/// `.rdp` 落盘字节：纯 ASCII 直接写；含非 ASCII（中文用户名）写 **UTF-16LE + BOM**
/// ——mstsc 对无 BOM 的 UTF-8 中文用户名会读成乱码/空。
#[cfg(feature = "gui")]
fn rdp_file_bytes(text: &str) -> Vec<u8> {
    if text.is_ascii() {
        return text.as_bytes().to_vec();
    }
    let mut out = vec![0xFF, 0xFE];
    for u in text.encode_utf16() {
        out.extend_from_slice(&u.to_le_bytes());
    }
    out
}

/// 临时 `.rdp` 路径：`%TEMP%\myco-rdp-<port>.rdp`。
#[cfg(feature = "gui")]
fn rdp_file_path(port: u16) -> std::path::PathBuf {
    std::env::temp_dir().join(format!("myco-rdp-{port}.rdp"))
}

/// 写临时 `.rdp` 文件，返回落盘路径。
/// （pub(crate)：`vnet_env.rs` 的 rdp 客户端启动复用同一份落盘/编码逻辑。）
#[cfg(feature = "gui")]
pub(crate) fn write_rdp_file(
    port: u16,
    user: &str,
    address: &str,
) -> Result<std::path::PathBuf, String> {
    let path = rdp_file_path(port);
    let text = rdp_file_text(&rdp_sanitize_user(user), address);
    std::fs::write(&path, rdp_file_bytes(&text))
        .map_err(|e| format!("写 {} 失败: {e}", path.display()))?;
    Ok(path)
}

/// 用**参数数组**启动 `mstsc.exe <文件>`（不经 shell，杜绝命令行拼接）。
#[cfg(all(feature = "gui", windows))]
pub(crate) fn launch_mstsc(path: &std::path::Path) -> Result<(), String> {
    std::process::Command::new("mstsc.exe")
        .arg(path)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .map(|_| ())
        .map_err(|e| format!("启动 mstsc.exe 失败: {e}"))
}

/// 非 Windows：远程桌面启动器不存在——**只给文件**，由调用方自己开。
#[cfg(all(feature = "gui", not(windows)))]
pub(crate) fn launch_mstsc(_path: &std::path::Path) -> Result<(), String> {
    Err("远程桌面（mstsc）只在 Windows 可用；.rdp 文件已生成，可自行打开".into())
}

/// 联调/CI 开关：`MYCO_RDP_NO_LAUNCH=1` 时只生成文件、不弹 mstsc 窗口。
#[cfg(feature = "gui")]
pub(crate) fn rdp_launch_suppressed() -> bool {
    std::env::var("MYCO_RDP_NO_LAUNCH")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
}

/// 联调/CI 开关：`MYCO_ENV_NO_LAUNCH=1` 时 env/open（dsh/http）只返回干净 URL，
/// **不拉系统浏览器**。
///
/// 2026-10-25 独立复验反馈："实现方会拉起系统浏览器"——验证/回归每打一次
/// env/open 就弹一个 Edge 标签页，既扰民又污染测量。与 `MYCO_RDP_NO_LAUNCH`
/// 同款语义（默认行为不变，仅显式开关时抑制）。
#[cfg(feature = "gui")]
pub(crate) fn env_browser_launch_suppressed() -> bool {
    std::env::var("MYCO_ENV_NO_LAUNCH")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
}

/// 远程桌面**现状**（卡片/页面共用）：不建隧道、不写文件，只回答四个问题。
/// `configured` = kept 转发表里有这条 (device,3389)（决定卡片渲不渲染）；
/// `mapped` = 这个固定口现在真的在监听（进程内隧道命中，或口上有服务）。
#[cfg(feature = "gui")]
pub fn rdp_status_impl(device: &str, port: u16, local_port: u16) -> serde_json::Value {
    let d = if device.trim().is_empty() {
        rdp_default_device()
    } else {
        device.trim().to_string()
    };
    let existing = crate::vnet_forward::route_local_port(&d, port);
    let configured = vnet_load_kept().iter().any(|rec| {
        rec.get("port").and_then(|p| p.as_u64()) == Some(port as u64)
            && rec.get("device").and_then(|x| x.as_str()) == Some(d.as_str())
    });
    let actual = existing.unwrap_or(local_port);
    json!({
        "ok": true,
        "device": d,
        "port": port,
        "configured": configured,
        "localPort": actual,
        "requestedLocalPort": local_port,
        "address": rdp_addr(actual),
        "mapped": existing.map(|p| p == local_port).unwrap_or_else(|| port_open_fast(local_port)),
        "known": rdp_device_known(&d),
    })
}

/// 「一键打开」的**实现**（HTTP 与 Tauri 命令共用一条路径，避免两套行为漂移）。
///
/// 顺序：参数闸 → **自连检测**（目标是本机＝我是服务端，不启 mstsc）→ keep 固定口（持久化）
/// → 复用/新建隧道 → 临时 `.rdp` → `mstsc`。
#[cfg(feature = "gui")]
pub async fn rdp_open_impl(
    device_in: String,
    port: u16,
    local_port: u16,
    user: String,
    no_launch: bool,
) -> Result<serde_json::Value, String> {
    let device = if device_in.trim().is_empty() {
        rdp_default_device()
    } else {
        device_in.trim().to_string()
    };
    rdp_validate(&device, port, local_port)?;
    // 2026-10-22 用户纠正：「打开远程会话」必须在**客户端那台机器**上执行（笔记本/手机），
    // PC 是被连的服务端——在 PC 上起 mstsc 等于自己连自己，没有意义。
    // 这里做自连检测：目标就是本机时，不启动 mstsc，返回可复制地址 + 明确提示。
    if crate::p2p_tunnel::self_did_for_loopback_filter()
        .map(|mine| myco_core::identity::did_equiv(mine.as_str(), device.as_str()))
        .unwrap_or(false)
    {
        let addr = rdp_addr(local_port);
        eprintln!("[vnet-rdp] 目标是本机（{device}）→ 不自启 mstsc，提示到客户端设备打开：{addr}");
        return Ok(json!({
            "ok": false,
            "reason": "self-target",
            "message": "这是本机（远程桌面的服务端）。请在这台机器的客户端设备（笔记本 / 手机）上打开本卡片，点[打开远程桌面] 即可；或复制地址手动连接。",
            "address": addr,
            "device": device,
            "port": port,
            "localPort": local_port,
        }));
    }
    // ① keep：固定口写进 vnet-forwards.json（myco 重启/断线后 keeper 按它重建）。
    vnet_keep_upsert(&device, port, Some(local_port), Some("远程桌面"));
    // ② 隧道：已有且**就在约定口** → 复用；否则 tunnel_open 会先 abort 旧监听再按
    // 固定口重绑（2026-10-23：原实现只要"有隧道"就直接复用 → keep 改了 localPort
    // 后仍返回旧随机口，mstsc 拿到 127.0.0.1:57811，而用户配置的是 23389 → 0x204）。
    let had = crate::vnet_forward::route_local_port(&device, port);
    let (actual, tunnel) = match crate::vnet_forward::route_open(&device, port, Some(local_port)).await {
        Ok(p) => (
            p,
            match had {
                Some(h) if h == p => "reused",
                Some(_) => "rebound", // 漂移纠正：旧口 → 约定固定口
                None => "opened",
            },
        ),
        Err(e) => {
            // 2026-10-22 真案（危险）：请求 laptop:3389（笔记本离线）时本进程建链失败，
            // 但 localPort 上恰好有"PC 自己 3389"的固定口在监听 → 旧兜底直接复用它并
            // launched:true，等于把远程桌面连回本机自己。**端口相同 ≠ 目标相同**，一律失败。
            // 若确实是「另一个 myco 实例」占着同一个映射，请先停掉那个实例再试。
            // 租约：建链失败=上游故障 → degraded（口不释放，keeper 退避重建）。
            let lease_key = crate::vnet_lease::LeaseKey {
                consumer_device: crate::vnet_lease::self_consumer_device(),
                kind: "rdp".into(),
                device: device.clone(),
                port,
                share_id: String::new(),
            };
            crate::vnet_lease::lease_upstream_fail(&lease_key, &e);
            return Err(format!(
                "隧道未建立：{e}（127.0.0.1:{local_port} 上即使有监听也不会被复用——可能属于另一个目标或另一个 myco 实例）"
            ));
        }
    };
    // 固定口契约：actual 必须等于请求的 localPort（绑定失败已在 tunnel_open 内 Err）。
    if actual != local_port {
        return Err(format!(
            "固定本地口 {local_port} 未能建立（实际 {actual}）；不会静默改用其它端口"
        ));
    }
    // 租约登记（rdp 卡；kind=rdp，share_id 为空——rdp 面无分享 id）
    let lease_key = crate::vnet_lease::LeaseKey {
        consumer_device: crate::vnet_lease::self_consumer_device(),
        kind: "rdp".into(),
        device: device.clone(),
        port,
        share_id: String::new(),
    };
    if let Err(e) = crate::vnet_lease::lease_open(&lease_key, actual) {
        crate::vnet_lease::lease_upstream_fail(&lease_key, &e);
    }
    // 地址永远用实际的（防御性），并回带 requestedLocalPort 让上层能提示。
    let address = rdp_addr(actual);
    // ③ 落地：临时 .rdp + mstsc（参数数组）。
    let rdp_file = write_rdp_file(port, &user, &address)?;
    let (launched, launch_err) = if no_launch {
        (false, None)
    } else {
        match launch_mstsc(&rdp_file) {
            Ok(()) => (true, None),
            Err(e) => (false, Some(e)),
        }
    };
    audit(
        "vnet-rdp",
        &[
            ("device", &device),
            ("port", &port.to_string()),
            ("local", &actual.to_string()),
            ("tunnel", tunnel),
            ("launched", &launched.to_string()),
        ],
    );
    Ok(json!({
        "ok": true,
        "address": address,
        "rdpFile": rdp_file.display().to_string(),
        "device": device,
        "port": port,
        "localPort": actual,
        "requestedLocalPort": local_port,
        "tunnel": tunnel,
        "user": rdp_sanitize_user(&user),
        "launched": launched,
        "launchError": launch_err,
    }))
}

/// `POST /api/vnet/rdp {device?, port?, localPort?, user?, noLaunch?}`
/// → `{ok, address, rdpFile, localPort, tunnel}`。
///
/// 错误一律 `200 + {ok:false,error}`（与 `/api/vnet/*` 其他端点一致：页面只需判 `ok`）。
#[cfg(feature = "gui")]
async fn handle_vnet_rdp(Json(body): Json<serde_json::Value>) -> Response {
    let device = body
        .get("device")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let port = body
        .get("port")
        .and_then(|v| v.as_u64())
        .map(|v| v as u16)
        .unwrap_or(RDP_PORT);
    let local_port = body
        .get("localPort")
        .and_then(|v| v.as_u64())
        .map(|v| v as u16)
        .unwrap_or(RDP_DEFAULT_LOCAL);
    let user = body
        .get("user")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let no_launch = body
        .get("noLaunch")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
        || rdp_launch_suppressed();
    match rdp_open_impl(device.clone(), port, local_port, user, no_launch).await {
        Ok(v) => Json(v).into_response(),
        Err(e) => Json(json!({
            "ok": false,
            "error": e,
            "device": device,
            "port": port,
            "localPort": local_port,
        }))
        .into_response(),
    }
}

/// Tauri 命令：PC 任务卡里的「打开远程桌面」（与 HTTP 面同一实现）。
///
/// 为什么走 invoke 不走 `fetch(:3102)`：UI 是 `tauri://` 源，打本机管理面是跨源；
/// 而 myco 的 IPC 面本来就是给 UI 用的正门（第63轮 env 合并后的既定纪律）。
#[cfg(feature = "gui")]
#[tauri::command]
pub async fn vnet_rdp_open(
    device: Option<String>,
    port: Option<u16>,
    local_port: Option<u16>,
    user: Option<String>,
) -> Result<serde_json::Value, String> {
    rdp_open_impl(
        device.unwrap_or_default(),
        port.unwrap_or(RDP_PORT),
        local_port.unwrap_or(RDP_DEFAULT_LOCAL),
        user.unwrap_or_default(),
        rdp_launch_suppressed(),
    )
    .await
}

/// Tauri 命令：卡片状态（地址/是否已配置/是否在监听），不触发任何副作用。
#[cfg(feature = "gui")]
#[tauri::command]
pub fn vnet_rdp_status(
    device: Option<String>,
    port: Option<u16>,
    local_port: Option<u16>,
) -> serde_json::Value {
    rdp_status_impl(
        &device.unwrap_or_default(),
        port.unwrap_or(RDP_PORT),
        local_port.unwrap_or(RDP_DEFAULT_LOCAL),
    )
}

/// 落地页 HTML：地址 + 状态点 + `[打开远程桌面]` `[复制地址]`。
