/// owner 标记任务完成
async fn handle_complete(Json(body): Json<serde_json::Value>) -> Response {
    let share_id = body
        .get("shareId")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let sh = shares();
    {
        let mut list = sh.shares.lock().unwrap();
        let Some(share) = list.iter_mut().find(|s| s.id == share_id) else {
            return Json(json!({"ok": false, "error": "分享不存在"})).into_response();
        };
        match transition(&share.state, EV_COMPLETE, &TransitionCtx::default()) {
            Some((new_state, effects)) => {
                share.state = new_state;
                for eff in &effects {
                    if let Effect::EmitClaimEvent {
                        event_type,
                        actor,
                        detail,
                    } = eff
                    {
                        emit_claim_event(event_type, &share_id, actor.as_deref(), detail.clone());
                    }
                }
            }
            None => {
                return Json(
                    json!({"ok": false, "error": format!("状态 {} 不接受 complete", share.state)}),
                )
                .into_response()
            }
        }
    }
    #[cfg(feature = "gui")]
    close_share_task(&share_id);
    save_registry(&sh);
    update_share_presence().await;
    Json(json!({"ok": true, "state": ST_CLOSED})).into_response()
}

/// 公共入口绝不信任调用方自报的 viewer 身份。可信设备域 listener（VNETP 前导 /
/// peer-listener 连接身份）在此层之外重新注入；因此普通直连不能靠两个 HTTP 头
/// 绕过 mt/ticket/DID grant。
async fn strip_public_viewer_identity(
    mut req: axum::extract::Request,
    next: axum::middleware::Next,
) -> Response {
    req.headers_mut().remove("x-myco-viewer-did");
    req.headers_mut().remove("x-myco-viewer-share");
    next.run(req).await
}

/// 公网网关路由（无状态；独立端口，frp/nginx/WebRTC 隧道的后端）。
/// 2026-10-10：加 `/p2p/msg` 路由——反向隧道全落网关端口（wantReverse=gw），
/// 取票（share-entry-request）需打 P2P 数据面 :9100 /p2p/msg；网关也挂
/// 该路由后手机反向-only 场景经一条隧道即可取票+加载 SPA。
pub fn public_router() -> Router<()> {
    let r = Router::new()
        .route("/", any(handle_root_fallback))
        // clean URL（task-23）的 `/gw/<id>/auth/did` 在 handle_proxy 内截流
        //（matchit 不允许 `/gw/:id/...` 与 `/gw/*path` 并存——路由表冲突）
        .route("/gw/*path", any(handle_proxy_timed))
        .route("/p2p/msg", post(handle_gw_p2p_msg))
        // 2026-10-20：**与 share 解耦的静态资产面**。SPA 的 bundle/插件引用原本是
        // `./assets/index-*.js` 这种相对路径 → 解析成 `/gw/<shareId>/app/assets/...`，
        // 每个新分享 URL 都不同 ⇒ 浏览器缓存永远命中不了（同一设备打开第二张分享卡
        // 仍要重下 4MB br bundle + 插件）。把 HTML 里的资源引用改写成这个稳定前缀后，
        // 同一设备只要打开过任意分享，后续分享的资产全部走浏览器缓存。
        .route("/myco-assets/*path", any(handle_myco_assets))
        // 2026-10-22 myco 自更新通道（稳定路径，**不依赖 share id**）：
        // 手机 PWA 检查更新时开隧道到本机网关，直接拉 latest.json / APK。
        // 这让「后续更新 myco」全自动（下载→系统安装确认框）。
        .route("/myco-update/latest.json", get(handle_myco_update_manifest))
        .route(
            "/myco-update/myco-phone.apk",
            get(handle_myco_update_apk_route),
        )
        .route("/*path", any(handle_root_fallback));
    // 2026-10-19 用户实测「刷会话列表卡 3-5s（手机/笔记本）」：网关转发时**剥离了
    // accept-encoding**（避免上游预压缩的双重开销），于是 SPA bundle（client.js 实测
    // 9.1 MB）与会话清单（session/list 实测 15.7 MB）都**原样**走隧道 → 手机/笔记本经
    // 中继慢 3-5s。这里在网关出站统一 gzip（仅文本类型，二进制/已压缩自动跳过）：
    // 文本类响应压到 ~1/4，隧道带宽立刻不再是瓶颈。MCP/本地 :3102 面不受影响。
    // 压缩级别用 **Fastest**：client.js 实测 9.1MB，默认级别压缩要 ~600ms CPU（把 PC 端
    // tList 从 745ms 推到 1.3s —— 带宽省了、本机反而慢了）。Fastest 仍能把文本压到 ~1/3，
    // 但 CPU 是毫秒级；手机/笔记本过隧道省下的传输时间才是大头。
    r.layer(
        tower_http::compression::CompressionLayer::new()
            .gzip(true)
            .br(true)
            .quality(tower_http::compression::CompressionLevel::Fastest),
    )
}

/// 网关上的 /p2p/msg：转发到 P2P 服务器的 handle_msg（同一鉴权/同一 wire 形状）。
/// 网关本身无 P2pState（P2P 是独立 :9100 服务器），这里用本地 HTTP 转发到
/// 127.0.0.1:9100（同机、零延迟——跟 share 网关到 ENV 的转发同模式）。
async fn handle_gw_p2p_msg(headers: HeaderMap, body: axum::body::Bytes) -> Response {
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(10))
        .build()
        .unwrap_or_default();
    let mut req = client
        .post("http://127.0.0.1:9100/p2p/msg")
        .body(body.to_vec());
    for (k, v) in headers.iter() {
        if k.as_str().eq_ignore_ascii_case("host")
            || k.as_str().eq_ignore_ascii_case("content-length")
        {
            continue;
        }
        if let Ok(vv) = v.to_str() {
            req = req.header(k.as_str(), vv);
        }
    }
    match req.send().await {
        Ok(resp) => {
            let status = resp.status().as_u16();
            let body = resp.bytes().await.unwrap_or_default();
            (
                axum::http::StatusCode::from_u16(status)
                    .unwrap_or(axum::http::StatusCode::BAD_GATEWAY),
                [("content-type", "application/json")],
                body,
            )
                .into_response()
        }
        Err(e) => (
            axum::http::StatusCode::BAD_GATEWAY,
            format!("{{\"ok\":false,\"error\":\"p2p-server unreachable: {e}\"}}"),
        )
            .into_response(),
    }
}

/// 进程级共享的上游 HTTP 客户端（assets 反代用）：**每请求新建 client 在高并发下
/// 会耗尽资源**（80 个 SPA 资源并发 → 80 个连接池），跨设备页面因此 502（2026-11-09）。
/// 共享单 client + 内置连接池即可；no_gzip/no_brotli 保证 body 保持压缩字节。
fn asset_http_client() -> Option<reqwest::Client> {
    static SHARED: std::sync::OnceLock<Option<reqwest::Client>> = std::sync::OnceLock::new();
    SHARED
        .get_or_init(|| {
            reqwest::Client::builder()
                .no_proxy()
                .no_gzip()
                .no_brotli()
                .no_deflate()
                .timeout(std::time::Duration::from_secs(60))
                .build()
                .ok()
        })
        .clone()
}

/// `/myco-assets/*` —— 与分享解耦的静态资产反代（2026-10-20，R7 设备端提速）。
///
/// 这些字节是 DSH 自己的前端产物（bundle/插件/图标），**不含任何分享者数据**；
/// 但走这个面需要本机 DSH 的 browser-session cookie（由网关自签注入）。
/// 输出挂 `cache-control: immutable`（URL 带内容 hash），让浏览器跨分享复用。
async fn handle_myco_assets(
    axum::extract::Path(rest): axum::extract::Path<String>,
    uri: axum::http::Uri,
    headers: HeaderMap,
) -> Response {
    let accept_encoding = headers
        .get(header::ACCEPT_ENCODING)
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string());
    let q = uri.query().map(|q| format!("?{q}")).unwrap_or_default();
    let rest = rest.trim_start_matches('/');
    if rest.is_empty() || rest.contains("..") {
        return (StatusCode::NOT_FOUND, "bad asset path").into_response();
    }
    // 2026-10-20（第二次修正）：`plugins/??pkg,...` 的复合包**可以**直出——之前 404 的真因是
    // 少了 `&rev=` 参数（实测：不带 rev → 404，带 rev → 200 4.2MB br）。现在直反代到上游
    // 根路径 `/plugins/??...` 并挂 immutable：URL 稳定 → 浏览器**跨分享命中缓存**。
    let port = native_port();
    if !port_open_fast(port) {
        return (StatusCode::SERVICE_UNAVAILABLE, "dsh not running").into_response();
    }
    let cookie = mint_dsh_cookie();
    // 2026-11-09 真浏览器事故（笔记本「Failed to load plugins / import failed」）：
    // reqwest 开了 gzip/brotli feature → **默认自动解压** body，但本函数按「原样搬运」
    // 语义透传 content-encoding 头 → 浏览器拿到「明文 body + br 头」→
    // `net::ERR_INVALID_CHUNKED_ENCODING` → 插件 bundle 全部 import 失败。
    // （python urllib 不自动解压所以我的脚本测试是绿的——教训：压缩类改动必须真浏览器验。）
    // 修：关掉自动解压，body 保持压缩字节 + 头原样透传，端到端语义一致（性能保留）。
    // 2026-11-09 并发修复：原实现**每请求新建 reqwest Client**（80 个 assets 并发 =
    // 80 个 client + 连接池）→ 经隧道的跨设备页面（并发高）出现 502；改为进程级共享。
    let client = match asset_http_client() {
        Some(c) => c,
        None => return (StatusCode::BAD_GATEWAY, "client build fail").into_response(),
    };
    // 注意：网关把 `/gw/<id>/app/` 前缀当自己的命名空间，**上游根路径 = strip 掉 app 之后**
    // （DSH 的资产在根 `/assets/...`、API 在 `/api/...`；实测 `/app/assets/...` 是 404）。
    let url = format!("http://{}/{rest}{q}", native_authority());
    // 2026-11-09 性能真案（用户实测 remote 静态资源 100KB/s、TTI 17s）：原实现
    // reqwest 不带 accept-encoding → 上游回 identity 原始字节（vendor.js 970KB 硬传）。
    // 大文件走隧道是固定带宽的硬消耗——**压缩是最大杠杆**（DSH 前端 br 压缩约 4×）。
    // 转发浏览器声明的 accept-encoding，并把上游的 content-encoding 原样透传
    // （我们自己不解压：body 是变长字节，只做搬运）。
    let mut req = if let Some(ae) = accept_encoding {
        client.get(&url).header(header::ACCEPT_ENCODING, ae)
    } else {
        client.get(&url).header(header::ACCEPT_ENCODING, "gzip, br")
    };
    if let Some(c) = cookie {
        req = req.header("cookie", c);
    }
    req = req.header("origin", format!("http://{}", native_authority()));
    match req.send().await {
        Ok(r) if r.status().is_success() => {
            let status = r.status().as_u16();
            let ctype = r
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|v| v.to_str().ok())
                .map(|s| s.to_string());
            // content-encoding 必须与 body 一起透传（压缩后字节直接给浏览器解）
            let cenc = r
                .headers()
                .get(header::CONTENT_ENCODING)
                .and_then(|v| v.to_str().ok())
                .map(|s| s.to_string());
            match r.bytes().await {
                Ok(bytes) => {
                    // HTTP 层坏包探针（PC 侧出口）：这是 PC 13911 网关从插件/DSH
                    // 读到、即将交给 vnet server upstream TCP 的资产字节。
                    // 与笔记本侧 [HASH-ORIGIN-IN] 对表定界。
                    if bytes.len() > 100_000 {
                        use sha2::Digest;
                        let h = sha2::Sha256::digest(&bytes);
                        eprintln!(
                            "[HASH-ASSET-OUT] len={} sha={}",
                            bytes.len(),
                            hex16(&h)
                        );
                    }
                    let mut b = Response::builder().status(status);
                    if let Some(ct) = ctype {
                        if let Ok(hv) = HeaderValue::from_str(&ct) {
                            b = b.header(header::CONTENT_TYPE, hv);
                        }
                    }
                    if let Some(ce) = cenc {
                        if let Ok(hv) = HeaderValue::from_str(&ce) {
                            b = b.header(header::CONTENT_ENCODING, hv);
                        }
                    }
                    b = b.header(
                        header::CACHE_CONTROL,
                        HeaderValue::from_static("public, max-age=31536000, immutable"),
                    );
                    b = b.header(header::VARY, HeaderValue::from_static("accept-encoding"));
                    b.body(Body::from(bytes)).unwrap().into_response()
                }
                Err(_) => (StatusCode::BAD_GATEWAY, "asset body failed").into_response(),
            }
        }
        Ok(r) => (
            StatusCode::from_u16(r.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY),
            "asset upstream non-2xx",
        )
            .into_response(),
        Err(e) => (StatusCode::BAD_GATEWAY, format!("asset upstream: {e}")).into_response(),
    }
}

/// 把 DSH 入口 HTML 里的**相对资源引用**改写成 `/myco-assets/...`（跨分享可缓存）。
///
/// 只动"资源引用"四类，且只在属性值以 `./assets/` `assets/` `./plugins/` `plugins/`
/// `./manifest` `./favicon` 开头时替换；`./` 这种导航链接、API 路径一概不碰。
/// 纯字符串替换（不解析 HTML）——注入前在入口文档上执行，失败也不影响功能（最差=旧行为）。
fn decouple_asset_urls(html: &str) -> String {
    let mut out = String::with_capacity(html.len() + 256);
    for (i, part) in html.split('"').enumerate() {
        if i > 0 {
            out.push('"');
        }
        out.push_str(&rewrite_one_asset_ref(part));
    }
    out
}

/// 单个属性值（位于两个引号之间）的改写；不是资源引用 → 原样返回。
fn rewrite_one_asset_ref(v: &str) -> String {
    let trimmed = v.trim();
    if trimmed.starts_with("./") {
        let rest = &trimmed[2..];
        if is_asset_prefix(rest) {
            return format!("/myco-assets/{rest}");
        }
        return v.to_string();
    }
    if is_asset_prefix(trimmed) {
        return format!("/myco-assets/{trimmed}");
    }
    v.to_string()
}

/// 分享视图的**插件瘦身**（2026-10-20，"怎么瘦身"的可实施版）。
///
/// 入口 HTML 会把 ~75 个客户端插件打成 3 个复合包（`plugins/??pkg1,pkg2,...`），
/// 实测复合包 #1 = **4.2MB br**（解压后 10MB+ JS）——是分享页 SPA boot 的大头，而
/// 分享页根本用不到设置/终端/文件/插件管理这些重型 UI。
///
/// 开关：`MYCO_SHARE_PLUGIN_DROP`（逗号分隔的**包名子串**）。
///   · 未设置/空 → 一个字节都不改（默认回归红线）。
///   · 命中某子串的包会被从复合 URL 里摘掉；某个复合包被摘空 → 该 <script> 整个不输出。
/// 例：`MYCO_SHARE_PLUGIN_DROP=client-ui-settings,terminal,sidebar-files,client-hmr`
fn share_plugin_drop_patterns() -> Vec<String> {
    std::env::var("MYCO_SHARE_PLUGIN_DROP")
        .ok()
        .map(|v| {
            v.split(',')
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

/// 纯函数：按丢弃名单改写入口 HTML 里的 `plugins/??...` 复合引用。
///
/// 命中名单的包会被摘掉；某个复合包被摘空 → 该 `<script>` 的 src 换成
/// `data:text/javascript,`（空模块，等价 no-op，避免浏览器把空 src 当页面请求）。
/// 名单为空 → 逐字节原样。
fn trim_share_plugins(html: &str, drop: &[String]) -> String {
    if drop.is_empty() {
        return html.to_string();
    }
    let mut out = String::with_capacity(html.len());
    let mut rest = html;
    while let Some(pos) = rest.find("plugins/??") {
        out.push_str(&rest[..pos]);
        let after = &rest[pos + "plugins/??".len()..];
        let Some(end) = after.find('"') else {
            out.push_str("plugins/??");
            out.push_str(after);
            return out;
        };
        let list = &after[..end];
        let (pkgs_part, rev_suffix) = match list.find('&') {
            Some(i) => (&list[..i], &list[i..]),
            None => (list, ""),
        };
        let kept: Vec<&str> = pkgs_part
            .split(',')
            .filter(|p| !p.is_empty() && !drop.iter().any(|d| p.contains(d.as_str())))
            .collect();
        if kept.is_empty() {
            out.push_str("data:text/javascript,");
        } else {
            out.push_str("plugins/??");
            out.push_str(&kept.join(","));
            out.push_str(rev_suffix);
        }
        rest = &after[end..];
    }
    out.push_str(rest);
    out
}

fn is_asset_prefix(s: &str) -> bool {
    // 2026-10-20（第二次修正）：`plugins/??pkg,...` 复合包**也走稳定前缀**。
    // 之前误判"上游 404"是因为测试 URL 少了 `&rev=`（实测：不带 rev→404；带 rev→200 4.2MB br）。
    // 稳定前缀 = 插件 URL 不再随 shareId 变 → 浏览器**跨分享命中缓存**（首次 4.2MB，之后 0 传输）。
    s.starts_with("assets/")
        || s.starts_with("plugins/")
        || s == "manifest.webmanifest"
        || s.starts_with("favicon")
}

/// 公网网关监听（env 启动时拉起；端口被占只告警不崩）。
pub async fn start_public_gateway() {
    crate::startup_trace::mark("gw-enter");
    let port = gw_port();
    let gateway_app = public_router();
    // 公共旧口最外层剥自报身份；viewer/VNETP 用 gateway_app 并由可信 listener 覆盖身份。
    let app = gateway_app
        .clone()
        .layer(axum::middleware::from_fn(strip_public_viewer_identity));
    let listener = match tokio::net::TcpListener::bind(format!("127.0.0.1:{port}")).await {
        Ok(l) => l,
        Err(e) => {
            tracing::warn!("[dsh-share] 公网网关端口 {port} 绑定失败(被占?): {e}");
            return;
        }
    };
    // 2026-10-11 云端中转：注册本设备为 provider（P2P 不通时对端可经中继到达本机）
    // 2026-10-15 删（整晚 30s 断连风暴的根因）：这里起的 cloud_relay provider 与
    // p2p_client::start_sync_loop → p2p_tunnel::relay_provider_start() 起的那个
    // **用同一 did 双注册**——服务器 REGISTER 语义是"替换旧连接"，两条循环互相
    // 顶：稳定态下本连接龄恰为对方的退避上限（30s），表现为 provider 每 30.0x 秒
    // EOF（relay-trace 全晚实锤；独立探针同路径 180s 稳活即排除网络/服务器）。
    // 正主是 p2p_tunnel 版（幂等守卫 + 心跳 25s + 会话泵到 p2p_server:9100）；
    // cloud_relay 版保留代码但不再从网关启动。
    tracing::info!("[dsh-share] 分享网关就绪 http://127.0.0.1:{port}/gw/<shareId>/");
    crate::startup_trace::mark_detail("gw-bound", &format!("port={port}"));
    // 统一端口档案：网关口本期固定（跨设备寻址锚，另议），只把实际值写进
    // ports.json 供调用方发现；bind 失败（上方已 return）不更新档案。
    crate::ports_file::record("gw", port);
    tokio::spawn(reaper());
    // 2026-10-19 R7：启动即后台预热（DSH 拉热 + 关键读 API 写忙窗缓存）
    spawn_gateway_cache_prewarm();
    // 发现层：网关启动即注册 presence（带当前分享列表），协作者可查在线状态。
    // 2026-10-23：由 await 改后台——presence 是云上 HTTP，断网/服务慢时会把网关
    // 的 accept 面一起拖住（网关 LISTEN 已就绪，但 serve 没开始 = 连接悬着）。
    tokio::spawn(async move { update_share_presence().await });
    // 2026-10-10 设备名预同步：启动时从云端拉一次设备名到本地 share_auth——
    // display_label 署名用（"phone·XXXX" 替代 DID 尾回退 "…DD9F"）。
    tokio::spawn(sync_device_names());
    // 2026-10-19 R7：预热循环 `spawn_gateway_cache_prewarm()` 已在上面启动（首轮立即跑）。
    // 2026-10-23：删掉这里额外的同步 `prewarm_before_gateway_serves().await`——它和
    // 预热循环干的是同一件事，却把 axum::serve 挡在后面最多 4s；网关是 DSH web 的
    // 转发面，serve 晚 4s = 页面/WS 晚 4s。
    crate::startup_trace::mark("gw-serve-start");
    if device_origin_enabled() {
        // 2026-11-10 方案 A 预研：15200 传输面按 MYCO_VNET_TRANSPORT 选 A（PeerListener
        // 交付）/B（VNETP 前导）；默认 B。总入口见 `start_device_origin_transport`。
        start_device_origin_transport();
        if let Err(e) = ensure_device_origin_listener(viewer_http_port()) {
            tracing::warn!("[device-origin] viewer 固定口启动失败：{e}");
        }
    }
    // （151xx viewer 专属口已物理删除：终态只有 24011 全局口 + VNETP 15200，
    // 不再有「按分享×授权重开专属口」的启动重建段。）
    let _ = axum::serve(listener, app).await;
}

/// 云端设备名 → 本地 share_auth 缓存（幂等，失败静默下次再试）。
async fn sync_device_names() {
    match myco_core::identity::account_list_devices().await {
        Ok(overview) => {
            let mut count = 0;
            for d in &overview.devices {
                if !d.did.is_empty() && !d.name.is_empty() {
                    crate::share_auth::shared()
                        .upsert_device(&d.did, &d.name, None, None, None, None);
                    count += 1;
                }
            }
            tracing::info!("[dsh-share] 设备名同步：{} 台（署名用）", count);
        }
        Err(e) => {
            tracing::warn!("[dsh-share] 设备名同步失败（署名将用 DID 尾）: {e}");
        }
    }
}

// ── reaper（承主仓：连续 3 拍不通 + pid 确认死才摘；孤儿猎杀防内存堆积）──

async fn reaper() {
    loop {
        tokio::time::sleep(Duration::from_secs(60)).await;
        let sh = shares();
        static PORT_FAILS: std::sync::LazyLock<Mutex<HashMap<String, u32>>> =
            std::sync::LazyLock::new(|| Mutex::new(HashMap::new()));
        let now = now_ms();
        let mut dead: Vec<String> = Vec::new();
        {
            let insts = sh.instances.lock().unwrap();
            let mut fails = PORT_FAILS.lock().unwrap();
            for (k, i) in insts.iter() {
                // 30s 保护期：pre-insert 占位记录的端口在 spawn 完成前未监听
                if i.port == 0 || now.saturating_sub(i.spawned_at) <= 30_000 {
                    continue;
                }
                if port_open_fast(i.port) {
                    fails.remove(k);
                    continue;
                }
                let n = fails.entry(k.clone()).or_insert(0);
                *n += 1;
                if *n >= 3 && !pid_alive(i.pid) {
                    dead.push(k.clone());
                }
            }
            for k in dead.iter() {
                fails.remove(k);
            }
        }
        if !dead.is_empty() {
            sh.instances
                .lock()
                .unwrap()
                .retain(|k, _| !dead.contains(k));
            save_registry(&sh);
            for k in &dead {
                audit("reap", &[("home", k)]);
            }
        }
        // 孤儿猎杀：端口段监听者命令行含 dsh 且不在注册表 → 杀（防 env 重启后残留堆积）
        let live_ports: Vec<u16> = sh
            .instances
            .lock()
            .unwrap()
            .values()
            .map(|i| i.port)
            .filter(|p| *p > 0)
            .collect();
        orphan_sweep(&live_ports);
    }
}

fn orphan_sweep(live_ports: &[u16]) {
    let live_csv = live_ports
        .iter()
        .map(|p| p.to_string())
        .collect::<Vec<_>>()
        .join(",");
    let script = format!(
        r#"$live = '{live_csv}' -split ','
$killed = @()
foreach ($c in Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object {{ $_.LocalPort -ge {PORT_BASE} -and $_.LocalPort -le {PORT_MAX} }} | Sort-Object LocalPort -Unique) {{
  if ($live -contains $c.LocalPort.ToString()) {{ continue }}
  $cl = (Get-CimInstance Win32_Process -Filter ('ProcessId=' + $c.OwningProcess) -ErrorAction SilentlyContinue).CommandLine
  if ($cl -match 'dsh') {{
    Stop-Process -Id $c.OwningProcess -Force -ErrorAction SilentlyContinue
    $killed += ($c.LocalPort.ToString() + ':' + $c.OwningProcess)
  }}
}}
if ($killed) {{ Write-Output ($killed -join ' ') }}"#
    );
    let mut c = std::process::Command::new("powershell");
    c.args(["-NoProfile", "-Command", &script]);
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        c.creation_flags(0x0800_0000);
    }
    if let Ok(o) = c.output() {
        let out = String::from_utf8_lossy(&o.stdout).trim().to_string();
        if !out.is_empty() {
            for pair in out.split_whitespace() {
                audit("orphan-kill", &[("target", pair)]);
            }
        }
    }
}

// ═══════════════════════════════════════════════════════════════════════
// CLI bridge（cli.rs 的 session 组——「给 DSH 会话发消息」的 agent 间通讯）
//
// wire 知识全部留在本文件（信封/arg_key/cookie/取票/隧道都是这里实测过的），
// cli.rs 只做命令面。三条能力：
//   · cli_local_sessions()        本机会话清单（operator 身份，与 UI 选项面同一条加工链）
//   · cli_local_session_prompt()  本机直投 prompt（mint cookie → :19387 session/prompt）
//   · cli_prompt_via_share()      经分享网关投递（--task：本机注册表捷径 / 取票+隧道）
// ═══════════════════════════════════════════════════════════════════════

/// 本机 DSH 会话清单 → JSON（`cli session list` 的数据源；与 UI 的选项面同一条
/// 加工链：滤掉子 agent/空白会话、最近在前、label 消歧——清单口径与分享面板一致）。
pub(crate) async fn cli_local_sessions() -> Result<Value, String> {
    // 15s 短缓存：回信/连续发送时不再每条都重打 11.8MB 的 session/list。
    // 2026-10-19：回信超时的另一半根因就是"每条回信都付一次清单重活"。
    let now = now_ms();
    if std::env::var("MYCO_CLI_NO_LIST_CACHE")
        .map(|v| v.trim() == "1")
        .unwrap_or(false)
    {
        // 诊断口：强制直查（对比缓存命中率/验清单新鲜度用）
    } else if let Some((at, v)) = CLI_LIST_CACHE.lock().unwrap().clone() {
        if cache_fresh(at, now, CLI_LIST_CACHE_MS) {
            return Ok(v);
        }
    }
    let v = dsh_ready_retry_budget(cli_local_sessions_once, CLI_RETRY_BUDGET_MS).await?;
    *CLI_LIST_CACHE.lock().unwrap() = Some((now, v.clone()));
    Ok(v)
}

static CLI_LIST_CACHE: std::sync::Mutex<Option<(u64, Value)>> = std::sync::Mutex::new(None);

/// 清 CLI 清单缓存（测试/切会话/诊断用；`POST /api/cli {"action":"session_cache_clear"}`）。
pub(crate) fn clear_cli_list_cache() {
    *CLI_LIST_CACHE.lock().unwrap() = None;
}

async fn cli_local_sessions_once() -> Result<Value, String> {
    let rows = fetch_dsh_session_list().await?;
    let opts = process_session_list(rows, SESSION_OPTIONS_MAX);
    Ok(json!({
        "count": opts.sessions.len(),
        "sessions": opts.sessions.iter().map(|s| json!({
            "sessionId": s.value,
            "name": s.label,
            "cwd": if s.cwd.is_empty() { Value::Null } else { json!(s.cwd) },
            "updatedAt": if s.updated_at == i64::MIN { Value::Null } else { json!(s.updated_at) },
        })).collect::<Vec<_>>(),
        "summary": opts.summary(),
    }))
}

/// 全量会话清单（**含子代理/子会话**；仅 CLI 的目标/署名解析用，不进 UI 选项面）。
///
/// 2026-10-17 设计定稿（a+c）真案：子代理会话被 `process_session_list` 过滤出清单后，
/// `session send --to` 根本找不到它们 → 各会话只能手写头"直投"（绕过 myco 签名层）→
/// 收件方看到满屏十几进制 ID 尾和旧格式头。这里给 CLI 一条**能寻址子代理、且署名仍由
/// myco 生成**的通道；子代理显示成「父会话名/子代理」，不再出现裸 session ID 尾。
pub(crate) async fn cli_all_sessions() -> Result<Value, String> {
    let rows = fetch_dsh_session_list().await?;
    let titles: std::collections::HashMap<&str, &str> = rows
        .iter()
        .map(|r| (r.session_id.as_str(), r.title.as_str()))
        .collect();
    let list: Vec<Value> = rows
        .iter()
        .map(|r| {
            let parent_name = r
                .parent_session_id
                .as_deref()
                .and_then(|p| titles.get(p).copied())
                .filter(|t| !t.is_empty());
            let name = if let Some(p) = parent_name {
                format!("{p}/子代理")
            } else if !r.title.is_empty() {
                r.title.clone()
            } else {
                format!("…{}", crate::cli::tail_chars(&r.session_id, 8))
            };
            json!({
                "sessionId": r.session_id,
                "name": name,
                "cwd": if r.cwd.is_empty() { Value::Null } else { json!(r.cwd) },
                "updatedAt": if r.updated_at == i64::MIN { Value::Null } else { json!(r.updated_at) },
                "subagent": r.subagent,
                "parentSessionId": r.parent_session_id,
            })
        })
        .collect();
    Ok(json!({ "count": list.len(), "sessions": list, "all": true }))
}

// ═══════════════════════════════════════════════════════════════════════
// 署名解析用会话清单（2026-10-19：fork 会话补全）
//
// 真案（申诉管理实测问题）：myco 清单 163 条（过滤子代理/空白后）而 DSH 有 968 条——
// DSH **fork 出来的新会话**（申诉管理 session-55babc93…）在 DSH 有、在过滤清单里
// 没有 → `session send --from "申诉管理"` 报「署名不在本机会话清单里」，改用
// `--session-id` 能送达但署名退化成 `[from: 70f04816]`（名字查不到 → ID 尾兜底）。
//
// 修复：署名解析路径带**按需刷新**的完整清单（含 fork/子代理，title 优先做名字）：
//   · 5 分钟 TTL 缓存（防每次发送都全量拉）；miss 时实时 fetch DSH session/list；
//   · 刷新后日志 `[session-name] 缓存未命中，已从 DSH 刷新清单（新增 N 条）`；
//   · 名字优先级：title（fork 继承的标题）> 父会话名/子代理 > ID 尾 8。
const SESSION_SIGN_CACHE_MS: u64 = 5 * 60_000;
static SESSION_SIGN_CACHE: std::sync::Mutex<Option<(u64, Vec<serde_json::Value>)>> =
    std::sync::Mutex::new(None);

/// 会话行 → 署名解析清单（纯函数，单测直击）：title 优先（fork 会话标题就是它的名字），
/// 子代理（无标题）用父会话名 + "/子代理"，最后兜底 ID 尾 8。
fn signature_session_rows(rows: &[SessionRow]) -> Vec<serde_json::Value> {
    let titles: std::collections::HashMap<&str, &str> = rows
        .iter()
        .map(|r| (r.session_id.as_str(), r.title.as_str()))
        .collect();
    rows.iter()
        .map(|r| {
            let parent_name = r
                .parent_session_id
                .as_deref()
                .and_then(|p| titles.get(p).copied())
                .filter(|t| !t.is_empty());
            let name = if !r.title.is_empty() {
                r.title.clone()
            } else if let Some(p) = parent_name {
                format!("{p}/子代理")
            } else {
                format!("…{}", crate::cli::tail_chars(&r.session_id, 8))
            };
            json!({
                "sessionId": r.session_id,
                "name": name,
                "title": r.title,
                "subagent": r.subagent,
                "parentSessionId": r.parent_session_id,
                "updatedAt": if r.updated_at == i64::MIN { Value::Null } else { json!(r.updated_at) },
            })
        })
        .collect()
}

/// 给署名解析用的完整会话清单（含 fork/子代理；5 分钟 TTL 缓存，miss 实时刷新）。
/// 返回值与 `cli_all_sessions` 同形（`{count, sessions:[{sessionId,name,...}]}`）。
pub(crate) async fn cli_sessions_for_sender() -> Result<Value, String> {
    let now = now_ms();
    if let Some((at, list)) = SESSION_SIGN_CACHE.lock().unwrap().clone() {
        if cache_fresh(at, now, SESSION_SIGN_CACHE_MS) {
            return Ok(
                json!({ "count": list.len(), "sessions": list, "all": true, "cached": true }),
            );
        }
    }
    let rows = dsh_ready_retry_budget(fetch_dsh_session_list, CLI_RETRY_BUDGET_MS).await?;
    let list = signature_session_rows(&rows);
    let old: Vec<String> = SESSION_SIGN_CACHE
        .lock()
        .unwrap()
        .as_ref()
        .map(|(_, l)| {
            l.iter()
                .filter_map(|v| v["sessionId"].as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default();
    let added = list
        .iter()
        .filter_map(|v| v["sessionId"].as_str())
        .filter(|id| !old.iter().any(|o| o == *id))
        .count();
    eprintln!(
        "[session-name] 缓存未命中，已从 DSH 刷新清单（新增 {} 条，共 {} 条）",
        added,
        list.len()
    );
    *SESSION_SIGN_CACHE.lock().unwrap() = Some((now, list.clone()));
    Ok(json!({ "count": list.len(), "sessions": list, "all": true }))
}

/// 同步预热门（2026-10-19 补充：HTTP action 路径）：`dispatch_structured` 跑在
/// `spawn_blocking` 线程里，署名解析前先把**完整会话清单**（含 fork/子代理）刷进
/// 5 分钟缓存——否则 `POST /api/cli {"action":"session_send",...}` 这条大多数会话
/// 走的路会拿呈现口径清单解析署名 → fork 会话报「署名不在清单」或退化成 ID 尾。
/// 已有 TTL 内缓存则不重复拉（真正的按需刷新仍在 `cli::session_send` 内）。
fn seed_session_sign_cache_sync() {
    if SESSION_SIGN_CACHE.lock().unwrap().is_some() {
        return;
    }
    let Ok(rt) = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
    else {
        return;
    };
    let _ = rt.block_on(cli_sessions_for_sender());
}
/// 测试/切会话后强制清缓存（诊断口用）。
pub(crate) fn clear_session_sign_cache() {
    *SESSION_SIGN_CACHE.lock().unwrap() = None;
}
/// session/prompt 的 0.2 信封（arg_key 是 **"request"**——asar 端点表实测；
/// `session/list` 才是 "_request"，别混）。与 handle_say / instance_rpc 同 wire。
/// 2026-10-14 mode 参数化：默认 "queue"（排尾）；"interrupt"=插队（DSH web
/// ctrl+enter 同款——用户要求支持）。
fn cli_prompt_envelope_mode(session_id: &str, text: &str, mode: &str) -> Value {
    json!({
        "type": "client-request",
        "rpcId": format!("cli{}{}", now_ms(), rand_hex(4)),
        "method": "session/prompt",
        "payload": {"args": {"request": {
            "requestId": format!("cli-{}", rand_hex(12)),
            "sessionId": session_id,
            "mode": if mode.is_empty() { "queue" } else { mode },
            "content": [{"type": "text", "text": text}],
        }}},
    })
}

fn cli_prompt_envelope(session_id: &str, text: &str) -> Value {
    cli_prompt_envelope_mode(session_id, text, "queue")
}

/// DSH web 应答 → Result：HTTP 非 2xx / `result.ok:false` → Err(人话)；成功给 `result.value`。
/// 信封形状与 `fetch_dsh_session_list` / `instance_rpc` 的应答处理同口径。
async fn cli_rpc_result(resp: reqwest::Response) -> Result<Value, String> {
    let status = resp.status();
    if status == reqwest::StatusCode::UNAUTHORIZED {
        // 2026-10-14 真案：DSH 重启后有数十秒窗口——HTTP 已监听但鉴权子系统未就绪，
        // 期间任何签名 cookie 都被 401。旧文案"签名密钥可能被换过"是误导（实测密钥
        // 完好：手工铸 cookie 直测 200）。区分「未就绪可重试」与「签名真失效」。
        return Err(
            "DSH 未就绪（401）——若刚重启过 DSH，等几秒重试即可；持续 401 才需查签名密钥".into(),
        );
    }
    if !status.is_success() {
        let head: String = resp
            .text()
            .await
            .unwrap_or_default()
            .chars()
            .take(200)
            .collect();
        return Err(format!("DSH 回了 HTTP {}（{}）", status.as_u16(), head));
    }
    let v: Value = resp
        .json()
        .await
        .map_err(|e| format!("DSH 的应答不是 JSON：{e}"))?;
    let result = v.get("result").cloned().unwrap_or_else(|| v.clone());
    if result.get("ok").and_then(|x| x.as_bool()) == Some(false) {
        let msg = result
            .pointer("/error/message")
            .and_then(|m| m.as_str())
            .or_else(|| result.get("error").and_then(|e| e.as_str()))
            .unwrap_or("rpc 错误");
        return Err(format!("DSH 拒绝了这次调用（{msg}）"));
    }
    Ok(result.get("value").cloned().unwrap_or(result))
}

/// DSH 就绪窗口重试（2026-10-14）：DSH 重启后有数十秒窗口——端口已监听但鉴权/服务
/// 未就绪（401 或连接拒绝）。对「未就绪」类错误退避重试（300ms/900ms/2s），其它错误
/// 立即返回（真错误不该被重试掩盖）。
async fn dsh_ready_retry<F, Fut, T>(f: F) -> Result<T, String>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<T, String>>,
{
    dsh_ready_retry_budget(f, u64::MAX).await
}

/// 带**总预算**的就绪窗口重试（2026-10-19）：预算内用原排期退避，预算不够时把最后一次
/// 等待截断到剩余额度，用尽就**快速失败**并给出"≥5s 后重试"的可编程结论。
/// 原排期 [300,1000,2500,5000,10000,20000] 最坏 39s——比客户端超时（10~15s）长，
/// 调用方只看到"超时"、看不到"忙窗可重试"，且可能重发（重复投递风险）。
async fn dsh_ready_retry_budget<F, Fut, T>(mut f: F, budget_ms: u64) -> Result<T, String>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<T, String>>,
{
    let t0 = tokio::time::Instant::now();
    let mut tries: u32 = 1;
    let mut last = match f().await {
        Ok(v) => return Ok(v),
        Err(e) => e,
    };
    // 2026-10-14 下午实测量化（运维会话同窗 9 连发全败佐证）：DSH 的 401 是**阵发性**
    // （窗口分钟级——三会话并发活跃时更长）。5 次 19s 只兜短窗，拉到 6 次 ~39s；
    // 更长的窗快速失败（503+retryable），调用方选择稍后重发——比干等数分钟好排查。
    for delay in [300u64, 1000, 2500, 5000, 10000, 20000] {
        if !dsh_not_ready_err(&last) {
            return Err(last);
        }
        let elapsed = t0.elapsed().as_millis() as u64;
        let remaining = budget_ms.saturating_sub(elapsed);
        if remaining < 250 {
            println!(
                "[dsh-retry] 预算耗尽（已试 {tries} 次 / {elapsed}ms，上限 {budget_ms}ms）→ 快速失败：{last}"
            );
            return Err(format!(
                "{last}（myco 已自动重试 {tries} 次 / {elapsed}ms，超出本次预算）\
                 ——请等 ≥5s 后重试这条消息，最多 3 次"
            ));
        }
        let wait = delay.min(remaining);
        tokio::time::sleep(Duration::from_millis(wait)).await;
        tries += 1;
        match f().await {
            Ok(v) => {
                println!(
                    "[dsh-retry] 忙窗内第 {tries} 次尝试成功（{}ms）",
                    t0.elapsed().as_millis()
                );
                return Ok(v);
            }
            Err(e) => {
                println!(
                    "[dsh-retry] 第 {tries} 次失败（{}ms，等待 {}ms 后继续）：{e}",
                    t0.elapsed().as_millis(),
                    delay
                );
                last = e;
            }
        }
    }
    Err(last)
}

/// 「DSH 未就绪」类错误判定（可重试）。
fn dsh_not_ready_err(e: &str) -> bool {
    e.contains("DSH 未就绪") || e.contains("连不上本机 DSH") || e.contains("没在运行")
}

/// 本机直投：把 text 作为 prompt 注入本机 DSH 的某个会话（operator 身份，
/// 与 `fetch_dsh_session_list` 同一套 mint cookie + 信封）。对方 AI 立即处理。
/// 2026-10-14 mode 参数：默认 "queue"（排尾）；"steer"=插队（ctrl+enter 同款）。
pub(crate) async fn cli_local_session_prompt(
    session_id: &str,
    text: &str,
) -> Result<Value, String> {
    cli_local_session_prompt_mode(session_id, text, "queue").await
}

pub(crate) async fn cli_local_session_prompt_mode(
    session_id: &str,
    text: &str,
    mode: &str,
) -> Result<Value, String> {
    dsh_ready_retry_budget(
        || cli_local_session_prompt_once(session_id, text, mode),
        CLI_RETRY_BUDGET_MS,
    )
    .await
}

async fn cli_local_session_prompt_once(
    session_id: &str,
    text: &str,
    mode: &str,
) -> Result<Value, String> {
    let port = native_port();
    if !port_open_fast(port) {
        return Err(format!(
            "本机 DSH 没在运行（{}）——打开 DSH 桌面版后重试",
            native_authority()
        ));
    }
    let Some(cookie) = mint_dsh_cookie() else {
        return Err(
            "读不到 DSH 的签名密钥（$DSH_HOME/.credentials.yaml 缺 browser-session）".into(),
        );
    };
    let authority = native_authority();
    let client = reqwest::Client::builder()
        .no_proxy()
        .redirect(reqwest::redirect::Policy::none())
        .timeout(Duration::from_secs(20))
        .build()
        .map_err(|e| format!("HTTP 客户端建不起来：{e}"))?;
    let resp = client
        .post(format!("http://{authority}/api/session/prompt"))
        .header("cookie", cookie)
        .header("origin", format!("http://{authority}"))
        .json(&cli_prompt_envelope_mode(session_id, text, mode))
        .send()
        .await
        .map_err(|e| format!("连不上本机 DSH：{e}"))?;
    cli_rpc_result(resp).await
}

/// `http://127.0.0.1:PORT/gw/...?mt=..` → `http://127.0.0.1:PORT`（scheme://authority）。
fn split_url_base(url: &str) -> Result<String, String> {
    let rest = url
        .split_once("://")
        .ok_or("入口 URL 形态不对（无 scheme）")?
        .1;
    let auth = rest.split(['/', '?']).next().unwrap_or("");
    if auth.is_empty() {
        return Err("入口 URL 形态不对（无主机）".into());
    }
    Ok(format!("{}://{auth}", &url[..url.find("://").unwrap_or(0)]))
}

/// `--task` 投递目标定位（纯函数，单测直击）：多可见会话时按优先级挑——
/// ① 本机注册表记得的绑定会话；② 源侧 grant 随票回传的绑定会话
/// （`boundSessionId`——跨设备常态：分享不在本机注册表时的唯一权威来源）。
/// 匹配同时认裸 uuid 与 `session-<uuid>` 两种形态（与 cli.rs 的 sender 匹配同款）。
/// 都没有/都匹配不上 → None（调用方拒绝投递，不猜目标）。
#[cfg(feature = "gui")]
fn pick_prompt_target(
    rows: &[SessionRow],
    local_sid: Option<&str>,
    ticket_sid: Option<&str>,
) -> Option<String> {
    fn norm(s: &str) -> &str {
        s.trim().trim_start_matches("session-")
    }
    for cand in [local_sid, ticket_sid] {
        let Some(c) = cand.map(str::trim).filter(|s| !s.is_empty()) else {
            continue;
        };
        if let Some(hit) = rows.iter().find(|r| norm(&r.session_id) == norm(c)) {
            return Some(hit.session_id.clone());
        }
    }
    None
}

/// 经分享网关投递（`--task` 面）：
///   ① 本机注册表捷径——分享在本机、原生挂载、已绑会话、归当前账号 → 直接本机
///      直投（不开网关不开隧道，与 `--to` 同一条路）；
///   ② 网关路径——设备域入口全复用 `remote_open_impl_dev`（本地/远程都生成
///      设备域 URL + 预热路由；legacy 取票已退役）→ 入口种 cookie →
///      `session/list`（session 档的可见范围白名单会把清单裁到「分享绑定的
///      那个会话」）→ `session/prompt`。
/// 注意：2026-11-10 起源侧网关不再改写正文；经插件 owner 口转发时，署名由插件按
/// 连接身份（viewer DID）决定，未入 policy 的连接不署名。
#[cfg(feature = "gui")]
pub(crate) async fn cli_prompt_via_share(share_id: &str, text: &str) -> Result<Value, String> {
    let share_id = share_id.trim();
    // ① 本机注册表捷径
    let local = {
        let sh = shares();
        let hit = sh
            .shares
            .lock()
            .unwrap()
            .iter()
            .find(|s| s.id == share_id)
            .cloned();
        drop(sh);
        hit
    };
    if let Some(s) = &local {
        if s.state == ST_CLOSED {
            return Err("这个任务已经结束了".into());
        }
        let sid = s.session_id.clone().unwrap_or_default();
        if !sid.is_empty() && is_native_share(s) && share_owned_by_active(s) {
            let v = cli_local_session_prompt(&sid, text).await?;
            return Ok(json!({
                "ok": true, "route": "local", "shareId": share_id,
                "sessionId": sid, "reply": v,
            }));
        }
    }
    // ② 网关路径：取票 + （远程时）隧道。bound_sid = 源侧 grant 随票回传的绑定
    // 会话——分享不在本机注册表（跨设备常态）时，它是多可见会话下定位目标的
    // 唯一权威来源。
    let (entry, bound_sid) = remote_open_impl_dev(share_id, "", "", None).await?;
    let base = split_url_base(&entry)?;
    let client = reqwest::Client::builder()
        .no_proxy()
        .redirect(reqwest::redirect::Policy::none())
        .timeout(Duration::from_secs(30))
        .build()
        .map_err(|e| format!("HTTP 客户端建不起来：{e}"))?;
    // 入口：验 mt → set-cookie（分享凭证 + 路由标记）。不跟随 302。
    let resp = client
        .get(&entry)
        .send()
        .await
        .map_err(|e| format!("分享入口打不开（{entry}）：{e}"))?;
    let st = resp.status();
    if st.as_u16() >= 400 {
        let head: String = resp
            .text()
            .await
            .unwrap_or_default()
            .chars()
            .take(200)
            .collect();
        return Err(format!("分享入口 HTTP {}（{}）", st.as_u16(), head));
    }
    let mut cookies: Vec<String> = Vec::new();
    for hv in resp.headers().get_all("set-cookie") {
        if let Ok(sc) = hv.to_str() {
            if let Some(pair) = sc.split(';').next() {
                let pair = pair.trim();
                if !pair.is_empty() && !cookies.iter().any(|c| c == pair) {
                    cookies.push(pair.to_string());
                }
            }
        }
    }
    let cookie_hdr = cookies.join("; ");
    if cookie_hdr.is_empty() {
        return Err("分享入口没有种下凭证 cookie（票可能被拒或已吊销）".into());
    }
    // session/list（经网关）：instance/workspace 档可能仍在拉起 → 有界短重试。
    let list_url = format!("{base}/gw/{share_id}/app/api/session/list");
    let mut rows: Vec<SessionRow> = Vec::new();
    let mut last_err = String::new();
    for attempt in 0..3u32 {
        let env = json!({
            "type": "client-request",
            "rpcId": format!("cli{}{}", now_ms(), rand_hex(4)),
            "method": "session/list",
            // wire 名是 `_request`（asar 端点表实测；session/prompt 才是 "request"）
            "payload": {"args": {"_request": {}}},
        });
        match client
            .post(&list_url)
            .header("cookie", &cookie_hdr)
            .header("origin", &base)
            .json(&env)
            .send()
            .await
        {
            Ok(r) => match cli_rpc_result(r).await {
                Ok(v) => {
                    rows = parse_session_list(&v).unwrap_or_default();
                    if !rows.is_empty() {
                        break;
                    }
                    last_err = "清单为空".into();
                }
                Err(e) => last_err = e,
            },
            Err(e) => last_err = format!("连不上分享网关：{e}"),
        }
        if attempt < 2 {
            tokio::time::sleep(Duration::from_millis(1500)).await;
        }
    }
    if rows.is_empty() {
        return Err(format!(
            "这张任务卡名下看不到任何会话（{last_err}）——确认分享还在有效期，或在目标机器上改用 --to 直投"
        ));
    }
    // 目标定位：多个可见会话（如 machine 档全可见）时，本机注册表知道绑定关系就用
    // 它；注册表没有（跨设备）就用源侧 grant 随票回传的绑定会话；都没有——不猜目标。
    let target_sid = if rows.len() == 1 {
        rows[0].session_id.clone()
    } else if let Some(sid) = pick_prompt_target(
        &rows,
        local.as_ref().and_then(|s| s.session_id.as_deref()),
        bound_sid.as_deref(),
    ) {
        sid
    } else {
        let cands: Vec<String> = rows.iter().map(|r| r.session_id.clone()).take(5).collect();
        return Err(format!(
            "这张任务卡能看到多个会话，无法确定投递目标（{:?}）——请在目标机器上用 --to <会话名> 直投",
            cands
        ));
    };
    let prompt_url = format!("{base}/gw/{share_id}/app/api/session/prompt");
    let r = client
        .post(&prompt_url)
        .header("cookie", &cookie_hdr)
        .header("origin", &base)
        .json(&cli_prompt_envelope(&target_sid, text))
        .send()
        .await
        .map_err(|e| format!("投递请求发不出去（{prompt_url}）：{e}"))?;
    let v = cli_rpc_result(r).await?;
    Ok(json!({
        "ok": true, "route": "gateway", "shareId": share_id,
        "sessionId": target_sid, "reply": v,
    }))
}

