    // ── 2026-10-25：I5「首条 session/list 必须回源」的引导标记机制（真案：二次开卡列表空白）──

    #[tokio::test]
    async fn event_stream_response_is_streamed_not_buffered_to_empty_response() {
        let app = Router::new().route(
            "/plugins/events",
            get(|| async {
                (
                    StatusCode::OK,
                    [
                        ("content-type", "text/event-stream; charset=utf-8"),
                        ("cache-control", "no-cache"),
                    ],
                    Body::from(": connected\n\ndata: {\"type\":\"graph\"}\n\n"),
                )
            }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
        let resp = reqwest::Client::new()
            .get(format!("http://127.0.0.1:{port}/plugins/events"))
            .send()
            .await
            .unwrap();
        assert!(is_event_stream_response(
            resp.status().as_u16(),
            resp.headers()
        ));
        let out = rebuild_event_stream_response(resp);
        assert_eq!(out.status(), StatusCode::OK);
        assert!(out
            .headers()
            .get(header::CONTENT_TYPE)
            .and_then(|v| v.to_str().ok())
            .unwrap_or("")
            .contains("text/event-stream"));
        let bytes = axum::body::to_bytes(out.into_body(), usize::MAX)
            .await
            .unwrap();
        let text = String::from_utf8_lossy(&bytes);
        assert!(text.contains(": connected"));
        assert!(text.contains("data: {\"type\":\"graph\"}"));
    }

    #[test]
