    /// CLI bridge 的 wire 不变量：session/prompt 信封的 arg_key 是 **request**（不是
    /// session/list 的 `_request`）；URL 基址裁剪不丢端口。
    #[test]
    fn cli_bridge_wire_invariants() {
        let env = cli_prompt_envelope("sess-1", "[myco]: 你好");
        assert_eq!(env["method"], json!("session/prompt"));
        assert_eq!(env["type"], json!("client-request"));
        assert_eq!(
            env.pointer("/payload/args/request/sessionId"),
            Some(&json!("sess-1"))
        );
        assert_eq!(
            env.pointer("/payload/args/request/mode"),
            Some(&json!("queue"))
        );
        assert_eq!(
            env.pointer("/payload/args/request/content/0/type"),
            Some(&json!("text"))
        );
        assert_eq!(
            env.pointer("/payload/args/request/content/0/text"),
            Some(&json!("[myco]: 你好"))
        );
        assert!(env
            .pointer("/payload/args/request/requestId")
            .unwrap()
            .as_str()
            .unwrap()
            .starts_with("cli-"));
        // ⚠️ 这两个端点的 arg_key 不同（asar 实测），永远别混：
        assert!(env["payload"]["args"].get("request").is_some());
        assert!(env["payload"]["args"].get("_request").is_none());
        // URL 基址：带路径与 query 的入口 → scheme://authority
        assert_eq!(
            split_url_base("http://127.0.0.1:13911/gw/sh-abc/?mt=xyz").unwrap(),
            "http://127.0.0.1:13911"
        );
        assert_eq!(
            split_url_base("http://127.0.0.1:53000/gw/sh-x").unwrap(),
            "http://127.0.0.1:53000"
        );
        assert!(split_url_base("garbage").is_err());
    }

    /// **cookie 票寿命**（2026-10-12 笔记本实测根修）：分享页断连 2.7 小时后刷新
    /// → `no valid share cookie`。旧口径 cookie 沿用入口窄票（300s）或只滑 30 分钟
    /// → 断连一久必死。新口径：授权窗内尽量长（7 天对齐），**绝不越过 grant**。
    #[test]
    fn cookie_ticket_survives_outage_without_exceeding_grant() {
        let now = 1_700_000_000_000u64;
        let five_min = now + 5 * 60_000; // 入口窄票：5 分钟
        let grant_2d = now + 2 * 24 * 3600_000;

        // ① 短票 + grant 还剩 2 天 → cookie 票给到 2 天（不再沿用 5 分钟窄票）
        let e1 = cookie_target_exp(five_min, Some(grant_2d), now);
        assert_eq!(e1, grant_2d, "应给到 grant 授权窗尽头");
        assert!(e1 > now + 2 * 3600_000, "至少活过数小时断连");

        // ② 不越 grant：grant 只剩 10 分钟 → cookie 票也就是 10 分钟（授权到期即失效）
        let grant_10m = now + 10 * 60_000;
        assert_eq!(cookie_target_exp(five_min, Some(grant_10m), now), grant_10m);

        // ③ 原票比目标更长（owner 长票）→ 绝不缩短
        let long_ticket = now + 30 * 24 * 3600_000;
        assert_eq!(
            cookie_target_exp(long_ticket, Some(grant_2d), now),
            long_ticket
        );

        // ④ 无 grant（吊销/改签）→ 不擅自放大（调用方走保守的 renewed_exp）
        assert_eq!(cookie_target_exp(five_min, None, now), five_min);
    }

    /// 断连自愈四要素（2026-10-12 用户报"程序更新后已开分享页断连不恢复"；
    /// 2026-10-15 ①换代；2026-10-24 Phase 2 收进 D 决策核）：
    /// ① 挂起长探 ping?h=1500（**永远有一个探测在途**，断连 0 延迟被发现）；
    /// ② 数据面死 → D 规则 3 → A.reload_page（**唯一** reload 出口）；
    /// ③ 会话内上限 3 次；④ 60s 节流（全入口共享一份计数）。
    /// 注：自愈心跳在 **bootstrap_script**（conn_status_snippet 那份心跳只管
    /// 图标/续票，职责分离）。
    #[test]
    fn heartbeat_snippet_heals_datasurface_outage() {
        let s = bootstrap_script("sh-check", None);
        assert!(s.contains("ping?h=1500"), "① 挂起长探（在途探测）缺失");
        assert!(s.contains("decideAction"), "② D 决策核缺失");
        assert!(s.contains("A.reload_page"), "② 统一 reload 出口缺失");
        assert!(s.contains("n>=3"), "③ 上限缺失");
        assert!(s.contains("60000"), "④ 节流缺失");
    }

    /// Phase 2 统一契约（2026-10-24）：decideAction 是唯一决策入口；
    /// **全脚本只允许一处 `location.reload()`**（在 A.reload_page 里）——
    /// 4 个散乱的 reload 入口（watch/netFix/emptyListFix/bootCheck）不得复活。
    #[test]
    fn bootstrap_has_single_reload_exit_behind_decide_action() {
        let s = bootstrap_script("sh-uni", None);
        assert!(s.contains("function decideAction"), "D 决策函数缺失: {s}");
        assert!(s.contains("A.reload_page"), "A 动作表缺失: {s}");
        assert!(
            s.contains("A.dispatch_event"),
            "A 动作表缺 dispatch_event: {s}"
        );
        assert!(s.contains("[vnet-d] rule="), "决策审计日志缺失: {s}");
        let n = s.matches("location.reload()").count();
        assert_eq!(
            n, 1,
            "只允许 A.reload_page 一处 location.reload()，实际 {n}: {s}"
        );
        assert!(!s.contains("netFix("), "散乱入口 netFix 调用不得复活: {s}");
        assert!(
            !s.contains("reloadOnce("),
            "散乱入口 reloadOnce 调用不得复活: {s}"
        );
        assert!(
            !s.contains("myco_netfix_"),
            "netFix 私有计数键不得复活: {s}"
        );
        assert!(
            !s.contains("myco_boot_reload_"),
            "bootCheck 私有计数键不得复活: {s}"
        );
        assert!(
            !s.contains("myco_emptylist_"),
            "emptyListFix 私有计数键不得复活: {s}"
        );
    }

    /// 重连页快失败刷新契约（2026-10-15）：自刷必须带 `myco_fast=1`（网关据此跳过
    /// 401 长重试——否则 DSH 长窗口时每轮都要等满 23s，用户反复停在重连页：真案窗口
    /// 持续 80s）。同时锁网关侧判定与"不把自家标记转发上游"的语义。
    #[test]
    fn reconnect_page_fast_flag_contract() {
        assert!(
            RECONNECT_PAGE_HTML.contains("data-myco-reconnect"),
            "标记属性丢失"
        );
        assert!(
            RECONNECT_PAGE_HTML.contains("myco_fast=1"),
            "自刷必须带快失败标记"
        );
        assert!(
            RECONNECT_PAGE_HTML.contains("location.replace"),
            "自刷应走 replace"
        );
        let detect = |q: &str| q.split('&').any(|p| p == "myco_fast=1");
        let strip = |q: &str| {
            q.split('&')
                .filter(|p| *p != "myco_fast=1")
                .collect::<Vec<_>>()
                .join("&")
        };
        assert!(detect("myco_fast=1"));
        assert!(detect("mt=abc&myco_fast=1"));
        assert!(!detect("mt=abc"), "无标记不得快失败");
        assert_eq!(
            strip("mt=abc&myco_fast=1"),
            "mt=abc",
            "上游不得收到自家标记"
        );
        assert_eq!(strip("myco_fast=1"), "");
        assert_eq!(strip("a=1&b=2"), "a=1&b=2");
    }

    /// 快失败标记**只对文档请求生效**（2026-10-16 真案回归锚）：
    ///   重连页自刷 → 真应用以"带标记的同一 URL"加载 → 应用后续每个 API 调用都继承
    ///   `myco_fast=1`；若标记对 API 也生效，用户写操作（prompt/selectModel）在上游
    ///   401 段里会被**零重试同毫秒 503** 打掉（审计实证：prompt/selectModel 的 401 与
    ///   503 同一毫秒、forced=false）。这里钉住"API 请求即便带标记也不算快失败"。
    #[test]
    fn fast_flag_only_applies_to_documents() {
        // 文档（重连页自刷）：生效——这是标记的唯一正当用途
        assert!(fast_reload_applies(true, Some("myco_fast=1")));
        assert!(fast_reload_applies(true, Some("mt=abc&myco_fast=1")));
        // API/资源请求：**不生效**（本轮真案的核心）
        assert!(
            !fast_reload_applies(false, Some("myco_fast=1")),
            "API 请求不得跳过 401 重试"
        );
        assert!(
            !fast_reload_applies(false, Some("mt=abc&myco_fast=1")),
            "标记泄漏进 API URL 也必须照常重试"
        );
        // 无标记：都不生效
        assert!(!fast_reload_applies(true, None));
        assert!(!fast_reload_applies(true, Some("mt=abc")));
        assert!(!fast_reload_applies(false, None));
        // 标记"有没有"与"生效没生效"是两件事：审计要分别记（mark / fast）
        assert!(fast_marker_present(Some("mt=abc&myco_fast=1")));
        assert!(!fast_marker_present(Some("mt=abc")));
        assert!(!fast_marker_present(None));
        // 反复自刷也不会把标记变成 `myco_fast=10` 之类而漏检（只认精确 `myco_fast=1`）
        assert!(!fast_marker_present(Some("myco_fast=10")));
    }

