    /// 2026-10-14 真案（playwright 复现：重启 myco 后页面挂 DSH 认证错误 60s 不自愈）：
    /// 浏览器自带的过期 `dsh-auth-*` 必须剔除，只留 myco 注入的权威值——否则 DSH 读到
    /// 排在前面那个旧值 → 401。
    #[test]
    fn cookie_merge_drops_stale_dsh_auth() {
        let injected = "dsh-auth-abc=v1.FRESH";
        let existing = "dsh-auth-abc=v1.STALE; myco_share=xyz";
        let merged = merged_cookie_header(Some(existing), Some(injected)).unwrap();
        assert!(!merged.contains("STALE"), "{merged}");
        assert!(merged.contains("v1.FRESH"), "{merged}");
        assert!(merged.contains("myco_share=xyz"), "{merged}");
        // 只有旧 dsh-auth → 结果就是注入值
        assert_eq!(
            merged_cookie_header(Some("dsh-auth-abc=old"), Some(injected)).unwrap(),
            injected
        );
        // 无注入（隔离实例档）→ 保留其它 cookie，剔除 dsh-auth
        assert_eq!(
            merged_cookie_header(Some("a=1; dsh-auth-x=old"), None).unwrap(),
            "a=1"
        );
        // 全空 → None（不写空头）
        assert!(merged_cookie_header(None, None).is_none());
        assert!(merged_cookie_header(Some(""), Some("")).is_none());
        assert!(merged_cookie_header(Some("dsh-auth-only=old"), None).is_none());
    }

    /// DSH 未就绪类错误识别（重启窗口的重试判据）：只有「未就绪/连不上/没在运行」
    /// 才重试；业务错误必须立即返回（不能被重试掩盖）。
    #[test]
    fn dsh_not_ready_classification() {
        assert!(dsh_not_ready_err(
            "DSH 未就绪（401）——若刚重启过 DSH，等几秒重试即可"
        ));
        assert!(dsh_not_ready_err("连不上本机 DSH：connection refused"));
        assert!(dsh_not_ready_err(
            "本机 DSH 没在运行（127.0.0.1:19387）——打开 DSH 桌面版后重试"
        ));
        assert!(!dsh_not_ready_err("DSH 拒绝了这次调用（会话不存在）"));
        assert!(!dsh_not_ready_err(
            "没有叫 \"X\" 的会话——myco cli session list 看清单"
        ));
        assert!(!dsh_not_ready_err("--text 太长（>8000 字）"));
    }

    #[test]
    fn ticket_roundtrip() {
        let exp = now_ms() + 3600_000;
        let t = sign_ticket("did:youling:abc", "sh-x", exp);
        let (d, e) = verify_ticket(&t, "sh-x").expect("verify");
        assert_eq!(d, "did:youling:abc");
        assert_eq!(e, exp);
        assert!(verify_ticket(&t, "sh-other").is_none());
    }

    #[test]
    fn window_filter() {
        let now = now_ms();
        let mut v = serde_json::json!({"records": [
            {"event": {"time": (now_ms() - 10 * 3600_000) as i64, "type": "a"}},
            {"event": {"time": now as i64, "type": "b"}},
        ]});
        filter_page_window(&mut v, 6 * 3600_000);
        let left = v["records"].as_array().unwrap();
        assert_eq!(left.len(), 1);
        assert_eq!(left[0]["event"]["type"], "b");
        // 返回删掉的条数（§3.20 审计：这条裁剪是不是可见范围驱动的）
        let mut v2 = serde_json::json!({"records": [
            {"event": {"time": (now_ms() - 10 * 3600_000) as i64}},
            {"event": {"time": now as i64}},
        ]});
        assert_eq!(filter_page_window(&mut v2, 6 * 3600_000), 1);
    }

    // ═══════════════════════════════════════════════════════════════════
    // §3.20 状态空间可见性（S→O 投影）：默认不裁（回归保护）· 收窄才裁 ·
    // 逐人只能收紧 · 老记录兼容
    // ═══════════════════════════════════════════════════════════════════

    /// 一份 dsh 0.2 的 `session/list` 真实应答（`server-response` 信封 + 三个会话）。
    fn session_list_envelope() -> serde_json::Value {
        json!({
            "type": "server-response", "rpcId": "r1",
            "result": { "ok": true, "value": {
                "sessions": [
                    {"sessionId": "session-a", "cwd": "D:\\p", "title": "甲"},
                    {"sessionId": "session-b", "cwd": "D:\\p", "title": "乙"},
                    {"sessionId": "session-c", "cwd": "D:\\q", "title": "丙"},
                ],
                "nextCursor": null,
            }},
        })
    }

    /// **默认全可见 → 不裁剪**（本特性最高优先级的回归保护）：缺字段 / 空对象 /
    /// 坏类型一律退化成"没做过滤"，`session/list` 应答**一个字节都不动**。
    #[test]
    fn visibility_default_cuts_nothing() {
        assert_eq!(
            visibility_default(),
            json!({"space":"machine","sessions":[],"windowMs":null})
        );
        assert!(vis_all().is_all_visible());
        for v in [
            json!(null),
            json!({}),
            json!({"space": "整机"}),
            json!({"sessions": "x"}),
            json!({"windowMs": -1}),
            json!({"space": "session"}), // session 但没给白名单 = 不额外限制
        ] {
            let vis = vis_of(&v);
            assert!(vis.is_all_visible(), "→ 全可见: {v}");
            assert!(!vis.restricts_sessions(), "→ 不收窄会话面: {v}");
            assert!(
                vis.allows_session("session-b"),
                "全可见 → 任何会话都放行: {v}"
            );
            let mut doc = session_list_envelope();
            let before = doc.clone();
            assert_eq!(
                filter_session_list(&mut doc, &vis),
                (0, 0),
                "未收窄 → 不裁: {v}"
            );
            assert_eq!(doc, before, "未收窄 → JSON 逐字节不变: {v}");
        }
        // 时间窗合并：默认全可见时**恒等于**既有 windowMs（零回归）
        assert_eq!(window_stricter(None, None), None);
        assert_eq!(
            window_stricter(Some(6 * 3600_000), None),
            Some(6 * 3600_000)
        );
    }

    /// `space=session` + 白名单 → `session/list` 被裁到白名单（会话级隔离；原生挂载
    /// 档下"视野收窄"的唯一真解）。
    #[test]
    fn visibility_session_scope_cuts_session_list() {
        let vis = vis_of(&json!({"space":"session","sessions":["session-b"]}));
        assert!(vis.restricts_sessions());
        assert!(vis.allows_session("session-b"));
        assert!(!vis.allows_session("session-a"));
        let mut doc = session_list_envelope();
        assert_eq!(filter_session_list(&mut doc, &vis), (3, 1), "3 → 1");
        let rows = doc["result"]["value"]["sessions"].as_array().unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0]["sessionId"], json!("session-b"));
        // 信封其余部分原样（SPA 靠 `rpcId` 配对、靠 `result.ok` 判定）
        assert_eq!(doc["type"], json!("server-response"));
        assert_eq!(doc["rpcId"], json!("r1"));
        assert_eq!(doc["result"]["ok"], json!(true));
        assert!(
            doc["result"]["value"].get("nextCursor").is_some(),
            "非会话清单字段不动"
        );
        // 认不出会话 id 的行：收窄态下一律不投影（宁可少给，不可漏给）
        let mut doc2 = json!({"sessions": [{"title": "没有 id 的行"}, {"sessionId": "session-a"}]});
        assert_eq!(filter_session_list(&mut doc2, &vis), (2, 0));
        // 认不出结构 → 原样（不猜、不误删）
        let mut doc3 = json!({"result": {"ok": true, "value": {"weird": true}}});
        let keep = doc3.clone();
        assert_eq!(filter_session_list(&mut doc3, &vis), (0, 0));
        assert_eq!(doc3, keep);
    }

    /// 2026-10-18（用户问"项目档为什么只有当前项目"）：`space=project` 现在真的按项目
    /// 裁 `session/list`（此前只裁工作区清单，会话清单原样透传）；项目路径可由
    /// `projectCwd` 显式指定，null/缺省=沿用分享自身 cwd。
    #[test]
    fn visibility_project_scope_cuts_session_list_by_cwd() {
        // 显式项目路径 D:\p → 只留 cwd 等价的两条
        let vis = vis_of(&json!({"space":"project","projectCwd":"D:\\p"}));
        assert_eq!(vis.space, "project");
        assert_eq!(vis.project_cwd.as_deref(), Some("D:\\p"));
        let mut doc = session_list_envelope();
        assert_eq!(
            filter_session_list_project(&mut doc, &vis, &["D:\\p"]),
            (3, 2)
        );
        let rows = doc["result"]["value"]["sessions"].as_array().unwrap();
        assert_eq!(rows.len(), 2);
        assert!(rows.iter().all(|r| r["cwd"] == json!("D:\\p")));
        // Windows 路径等价：大小写/斜杠不敏感、末尾分隔符忽略
        let mut doc2 = session_list_envelope();
        assert_eq!(
            filter_session_list_project(&mut doc2, &vis, &["d:/P/"]),
            (3, 2)
        );
        // 认不出 cwd 的行：判不了 → 不投影
        let mut doc3 = json!({"sessions": [
            {"sessionId": "session-a"},
            {"sessionId": "session-b", "cwd": "D:\\p"},
        ]});
        assert_eq!(
            filter_session_list_project(&mut doc3, &vis, &["D:\\p"]),
            (2, 1)
        );
        // 非 project 档 / 空项目清单：一律不动（默认档逐字节红线）
        let mut doc4 = session_list_envelope();
        let keep4 = doc4.clone();
        assert_eq!(
            filter_session_list_project(&mut doc4, &vis_all(), &["D:\\p"]),
            (0, 0)
        );
        assert_eq!(doc4, keep4);
        assert_eq!(filter_session_list_project(&mut doc4, &vis, &[]), (0, 0));
        // 归一化：projectCwd 省略 → 不落键（旧记录逐字节兼容）；显式 null → 不落键
        assert_eq!(
            visibility_normalize(&json!({"space":"project"})),
            json!({"space":"project","sessions":[],"windowMs":null})
        );
        assert_eq!(
            visibility_normalize(&json!({"space":"project","projectCwd":"  D:\\p  "})),
            json!({"space":"project","sessions":[],"windowMs":null,"projectCwd":"D:\\p"})
        );
        assert!(visibility_check(&json!({"space":"project","projectCwd":"D:\\p"})).is_ok());
        assert!(visibility_check(&json!({"space":"project","projectCwd":null})).is_ok());
        assert!(visibility_check(&json!({"space":"project","projectCwd":"   "})).is_err());
        assert!(visibility_check(&json!({"space":"project","projectCwd":42})).is_err());
    }

    /// 2026-10-18 真好友实测：`session/list` 应答含 lone surrogate（DSH 按 UTF-16 码元
    /// 截断历史预览）→ `serde_json::from_slice` 整包失败 → 裁剪被静默跳过 → 好友看到
    /// 全机 949 个会话清单（隔离失效）。`parse_upstream_json` 必须先修复再解析。
    #[test]
    fn parse_upstream_json_repairs_lone_surrogate_before_cut() {
        // 真实坏体：合法 JSON + 一个孤立高代理项（serde 严格解析会拒）
        let bad = br#"{"result":{"ok":true,"value":{"items":[{"sessionId":"session-keep","preview":"\ud83d"},{"sessionId":"session-drop"}]}}}"#;
        assert!(
            serde_json::from_slice::<serde_json::Value>(bad).is_err(),
            "前提：坏体必须被 strict serde 拒（否则这条测试没意义）"
        );
        let mut doc = parse_upstream_json(bad).expect("修复后应当能解析");
        let vis = vis_of(&json!({"space":"session","sessions":["session-keep"]}));
        let (before, after) = filter_session_list(&mut doc, &vis);
        assert_eq!(
            (before, after),
            (2, 1),
            "修复后裁剪生效（此前 0 裁剪=泄露）"
        );
        assert_eq!(doc["result"]["value"]["items"].as_array().unwrap().len(), 1);
        // 合法体 → 原样（不修复、不改写）
        let ok = br#"{"result":{"ok":true,"value":{"items":[]}}}"#;
        assert!(parse_upstream_json(ok).is_some());
        // 坏透的体（不是 JSON）→ None（调用方保持原样透传）
        assert!(parse_upstream_json(b"not json at all").is_none());
    }

    // ═══════════════════════════════════════════════════════════════════
    // 2026-11-11 P0 安全回归：压缩（gzip/deflate/br）响应不得绕过可见性裁剪
    //
    // 根因（实测复现：单会话可见性分享 `session/list` 200 ok 1625 条 / 1624 条
    // 越权）：6651ec09（2026-11-09）起网关对上游要压缩，而裁剪靠
    // `parse_upstream_json`——压缩字节解析必失败 → 裁剪被静默跳过 → 原样透传。
    // 修法＝解压优先于裁剪（`rebuild_proxy_response` resp-decode + 裁剪核心内
    // 兜底）+ 解析失败 fail-closed（`TrimOutcome::Refuse` → 502）。下列用例锁死：
    //   ① 压缩与明文的裁剪语义完全一致（同白名单 → 同条数、同会话、同字节）；
    //   ② 解不开的一律 Refuse，绝不退化为透传（旧漏洞路径）；
    //   ③「要不要为裁剪而解压」只覆盖安全边界（未收窄响应继续压缩透传）。
    // ═══════════════════════════════════════════════════════════════════

    fn gz(bytes: &[u8]) -> Vec<u8> {
        use std::io::Write as _;
        let mut e = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::default());
        e.write_all(bytes).unwrap();
        e.finish().unwrap()
    }

    fn trimmed_session_count(body: &[u8]) -> usize {
        serde_json::from_slice::<serde_json::Value>(body)
            .expect("裁剪输出应是可解析 JSON")
            .pointer("/result/value/sessions")
            .and_then(|x| x.as_array())
            .map(|a| a.len())
            .unwrap_or(0)
    }

    /// 复现口径的函数级回归：单会话可见性 + gzip 上游响应 → 恰好 1 条（白名单那条），
    /// 且与 identity 路径的裁剪输出**逐字节一致**。
    #[test]
    fn p0_gzip_session_list_trimmed_to_single_session() {
        let vis = vis_of(&json!({"space":"session","sessions":["session-b"]}));
        let plain = serde_json::to_vec(&session_list_envelope()).unwrap();
        let gzipped = gz(&plain);
        // gzip：解压 → 裁剪 → 重序列化，3 → 1
        let (out, before, after) = trim_session_list_bytes(&gzipped, Some("gzip"), &vis);
        assert_eq!((before, after), (3, 1), "gzip 响应也必须裁到白名单");
        let TrimOutcome::Rewritten(body) = out else {
            panic!("gzip 响应必须 Rewritten（裁剪生效），而不是透传/拒绝: {out:?}");
        };
        assert_eq!(trimmed_session_count(&body), 1, "单会话可见性 → 至多 1 条");
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            v.pointer("/result/value/sessions/0/sessionId"),
            Some(&json!("session-b")),
            "留下的必须是白名单那条"
        );
        // 信封不被裁剪破坏（SPA 靠 rpcId 配对）
        assert_eq!(v["type"], json!("server-response"));
        assert_eq!(v["rpcId"], json!("r1"));
        // identity：同一份应答，裁剪结果与 gzip 路径逐字节一致（编码不改变语义）
        let (out2, before2, after2) = trim_session_list_bytes(&plain, None, &vis);
        assert_eq!((before2, after2), (3, 1));
        let TrimOutcome::Rewritten(body2) = out2 else {
            panic!("identity 响应应 Rewritten: {out2:?}");
        };
        assert_eq!(trimmed_session_count(&body2), 1);
        assert_eq!(body, body2, "同一应答 gzip/identity 裁剪输出必须一致");
        // 白名单内一条不差 → Passthrough（原字节原样，保持既有回归红线）
        let vis_all3 = vis_of(&json!({"space":"session","sessions":["session-a","session-b","session-c"]}));
        let (out3, b3, a3) = trim_session_list_bytes(&plain, None, &vis_all3);
        assert_eq!((b3, a3), (3, 3));
        assert_eq!(out3, TrimOutcome::Passthrough);
    }

    /// 解不开 / 不支持的编码 → Refuse（fail-closed），绝不退化成透传——这正是旧漏洞
    /// （解析失败 → 原样放行全机清单）的路径，任何编码下都不许再出现。
    #[test]
    fn p0_unparseable_body_refuses_instead_of_passthrough() {
        let vis = vis_of(&json!({"space":"session","sessions":["session-b"]}));
        let plain = serde_json::to_vec(&session_list_envelope()).unwrap();
        // ① 坏 gzip 字节 + gzip 头
        let (out, _, _) = trim_session_list_bytes(b"not-gzip-at-all", Some("gzip"), &vis);
        assert_eq!(out, TrimOutcome::Refuse, "坏 gzip 必须拒绝");
        // ② 明文 JSON 谎报 gzip
        let (out2, _, _) = trim_session_list_bytes(&plain, Some("gzip"), &vis);
        assert_eq!(out2, TrimOutcome::Refuse, "明文字节谎报 gzip 必须拒绝");
        // ③ 未在请求白名单里的编码（zstd）——同样不许透传
        let (out3, _, _) = trim_session_list_bytes(&gz(&plain), Some("zstd"), &vis);
        assert_eq!(out3, TrimOutcome::Refuse, "未知编码必须拒绝");
        // ④ 根本不是 JSON 的明文
        let (out4, _, _) = trim_session_list_bytes(b"<html>err</html>", None, &vis);
        assert_eq!(out4, TrimOutcome::Refuse, "非 JSON 明文必须拒绝");
        // 对照：全可见（未收窄）不会进裁剪核心（parts 只在 restricts_sessions 时进来）
        assert!(!vis_all().restricts_sessions());
    }

    /// session/page 时间窗（P0 同款旁路）：gzip 的历史页也必须过窗，解不开必须拒绝。
    #[test]
    fn p0_gzip_page_window_filtered_and_failclosed() {
        let now = now_ms();
        let page = json!({"records": [
            {"event": {"type": "old", "time": (now - 10 * 3600_000) as i64}},
            {"event": {"type": "new", "time": now as i64}},
        ]});
        let plain = serde_json::to_vec(&page).unwrap();
        // gzip：10h 前的记录被删（窗 6h）
        let (out, dropped) = trim_page_window_bytes(&gz(&plain), Some("gzip"), 6 * 3600_000);
        assert_eq!(dropped, 1, "gzip 的时间窗裁剪必须生效");
        let TrimOutcome::Rewritten(body) = out else {
            panic!("应 Rewritten: {out:?}");
        };
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();
        let left = v["records"].as_array().unwrap();
        assert_eq!(left.len(), 1, "只留窗内记录");
        assert_eq!(left[0]["event"]["type"], json!("new"));
        // identity：一致
        let (out2, dropped2) = trim_page_window_bytes(&plain, None, 6 * 3600_000);
        assert_eq!(dropped2, 1);
        assert!(matches!(out2, TrimOutcome::Rewritten(_)));
        // 坏 gzip → Refuse（旧路径会整页透传 = 时间窗泄漏）
        let (out3, _) = trim_page_window_bytes(b"junk", Some("gzip"), 6 * 3600_000);
        assert_eq!(out3, TrimOutcome::Refuse);
        // 谎报 gzip 的明文 → Refuse
        let (out4, _) = trim_page_window_bytes(&plain, Some("gzip"), 6 * 3600_000);
        assert_eq!(out4, TrimOutcome::Refuse);
    }

    /// 项目档同款：gzip 的清单按项目边界裁；空项目清单保持既有 fail-open（判不了
    /// 不裁，与编码无关）；坏包 fail-closed。
    #[test]
    fn p0_gzip_project_list_trimmed() {
        let vis = vis_of(&json!({"space":"project","projectCwd":"D:\\p"}));
        let plain = serde_json::to_vec(&session_list_envelope()).unwrap();
        let (out, before, after) =
            trim_session_list_project_bytes(&gz(&plain), Some("gzip"), &vis, &["D:\\p"]);
        assert_eq!((before, after), (3, 2), "gzip 的项目边界裁剪必须生效");
        let TrimOutcome::Rewritten(body) = out else {
            panic!("应 Rewritten: {out:?}");
        };
        assert_eq!(trimmed_session_count(&body), 2);
        // 空项目清单（判不了）→ 不裁（既有 fail-open 语义不因本修复改变）
        let (out2, _, _) = trim_session_list_project_bytes(&gz(&plain), Some("gzip"), &vis, &[]);
        assert_eq!(out2, TrimOutcome::Passthrough);
        // 坏包 → Refuse
        let (out3, _, _) =
            trim_session_list_project_bytes(b"junk", Some("gzip"), &vis, &["D:\\p"]);
        assert_eq!(out3, TrimOutcome::Refuse);
    }

    /// 解压核心本身：gzip（含 x-gzip 别名）/ zlib 包装 deflate / 裸 deflate / brotli
    /// 往返；identity / 未知编码 / 坏字节 → None（调用方 fail-closed）。
    #[test]
    fn p0_decode_content_encoding_roundtrips() {
        use std::io::Write as _;
        let data: &[u8] = br#"{"result":{"value":{"sessions":[{"sessionId":"s1"}]}}}"#;
        // gzip + x-gzip 别名 + 头部空白容忍
        assert_eq!(
            decode_content_encoding("gzip", &gz(data)).as_deref(),
            Some(data)
        );
        assert_eq!(
            decode_content_encoding(" x-gzip ", &gz(data)).as_deref(),
            Some(data)
        );
        // deflate：RFC 的 zlib 包装与裸 deflate 两种都要认
        let mut z = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
        z.write_all(data).unwrap();
        let zlibbed = z.finish().unwrap();
        assert_eq!(
            decode_content_encoding("deflate", &zlibbed).as_deref(),
            Some(data)
        );
        let mut d = flate2::write::DeflateEncoder::new(Vec::new(), flate2::Compression::default());
        d.write_all(data).unwrap();
        let raw = d.finish().unwrap();
        assert_eq!(
            decode_content_encoding("deflate", &raw).as_deref(),
            Some(data)
        );
        // br：真 brotli 字节（与 reqwest 同族解码）
        let mut br_out = Vec::new();
        {
            let mut enc = brotli::CompressorWriter::new(&mut br_out, 4096, 6, 22);
            enc.write_all(data).unwrap();
        }
        assert_eq!(
            decode_content_encoding("br", &br_out).as_deref(),
            Some(data)
        );
        // identity / 未知编码 / 坏字节 → None（安全上等同"解不开"→ fail-closed）
        assert_eq!(decode_content_encoding("identity", data), None::<Vec<u8>>);
        assert_eq!(decode_content_encoding("zstd", data), None::<Vec<u8>>);
        assert_eq!(decode_content_encoding("gzip", b"corrupt"), None::<Vec<u8>>);
    }

    /// 「要不要为裁剪而解压」的判定只覆盖安全边界：未收窄（默认全可见）的
    /// session/list / session/page 继续压缩透传（6651ec09 的 TTI 收益不受影响）；
    /// 会话白名单（任务级/逐人）、项目边界、时间窗一律触发。
    #[test]
    fn p0_response_needs_gateway_trim_scope() {
        let post = Method::POST;
        let mut session_share = test_share(Vec::new());
        session_share.state_visibility = json!({"space":"session","sessions":["s1"]});
        let machine_share = test_share(Vec::new()); // state_visibility = 默认全可见
        // ① 任务级单会话可见性（owner 打开也算）→ list 必须解压裁剪
        assert!(response_needs_gateway_trim(
            &session_share,
            &mux_authz(default_caps(), vis_all()),
            "api/session/list",
            &post
        ));
        // ② 逐人收窄同样触发
        let authz_narrow = mux_authz(
            default_caps(),
            vis_of(&json!({"space":"session","sessions":["s1"]})),
        );
        assert!(response_needs_gateway_trim(
            &machine_share,
            &authz_narrow,
            "session/list",
            &post
        ));
        // ③ 项目边界 → list 触发
        let authz_proj = mux_authz(
            default_caps(),
            vis_of(&json!({"space":"project","projectCwd":"D:\\p"})),
        );
        assert!(response_needs_gateway_trim(
            &machine_share,
            &authz_proj,
            "session/list",
            &post
        ));
        // ④ 时间窗 → page 触发（visibility.windowMs 与逐人 windowMs 同把尺）
        let authz_win = mux_authz(default_caps(), vis_of(&json!({"windowMs": 3600_000})));
        assert!(response_needs_gateway_trim(
            &machine_share,
            &authz_win,
            "api/session/page",
            &post
        ));
        // ⑤ 未收窄（默认全可见）：list/page/写路径一律不解压（压缩透传保持）
        let authz_all = mux_authz(default_caps(), vis_all());
        for rest in [
            "api/session/list",
            "session/list",
            "api/session/page",
            "session/page",
            "api/session/prompt",
        ] {
            assert!(
                !response_needs_gateway_trim(&machine_share, &authz_all, rest, &post),
                "未收窄不得解压: {rest}"
            );
        }
    }

    /// 2026-10-18 真好友实测：写路径（`session/prompt`）此前没有会话白名单门，
    /// 被授权单会话的好友能按 id 往任意会话发言（accepted）。与读路径同一把尺。
    #[test]
    fn prompt_outside_visibility_is_denied() {
        let vis = vis_of(&json!({"space":"session","sessions":["session-a"]}));
        let allowed = br#"{"payload":{"args":{"request":{"sessionId":"session-a","content":[]}}}}"#;
        assert_eq!(
            prompt_visibility_violation(allowed, &vis),
            None,
            "白名单内 → 放行"
        );
        let outside = br#"{"payload":{"args":{"request":{"sessionId":"session-b","content":[]}}}}"#;
        assert_eq!(
            prompt_visibility_violation(outside, &vis).as_deref(),
            Some("session-b"),
            "白名单外 → 拒（返回被拒会话 id）"
        );
        // 未收窄（默认全可见）→ 恒不拦（零回归）
        let all = vis_of(&json!({"space":"machine"}));
        assert_eq!(prompt_visibility_violation(outside, &all), None);
        // 抽不出会话 id（畸形体）→ 不拦（与既有读路径一致：不猜）
        assert_eq!(prompt_visibility_violation(b"{}", &vis), None);
    }

    /// 2026-10-18 补洞：**项目档按 id 越界校验**（读/写共用纯函数）。
    /// 此前 project 档只裁清单，知道项目外会话 id 就能直接读/写。
    #[test]
    fn project_session_violation_blocks_outside_project() {
        let cwd_of = |sid: &str| -> Option<String> {
            match sid {
                "s-in" => Some(r"C:\dev\alpha".to_string()),
                "s-out" => Some(r"C:\dev\beta".to_string()),
                _ => None,
            }
        };
        // 项目内 → 放行
        assert_eq!(
            project_session_violation(&["s-in".to_string()], &[r"C:\dev\alpha"], &cwd_of),
            None
        );
        // Windows 路径等价（大小写/斜杠/尾分隔符）→ 放行
        assert_eq!(
            project_session_violation(&["s-in".to_string()], &["c:/dev/alpha/"], &cwd_of),
            None
        );
        // 项目外 → 拦（返回该 id + 人话原因）
        let got = project_session_violation(
            &["s-in".to_string(), "s-out".to_string()],
            &[r"C:\dev\alpha"],
            &cwd_of,
        );
        assert_eq!(got.map(|x| x.0), Some("s-out".to_string()));
        // 未知 id → 纯函数按"查不到=拦"（可用性策略由调用方决定）
        assert!(project_session_violation(
            &["s-unknown".to_string()],
            &[r"C:\dev\alpha"],
            &cwd_of
        )
        .is_some());
        // 空项目清单 → 不拦（调用方另有空清单防护/fail-open）
        assert_eq!(
            project_session_violation(&["s-out".to_string()], &[], &cwd_of),
            None
        );
    }

    /// 2026-10-24「指定项目」多选：归一化/严格校验/回读往返/兼容 projectCwd 旧记录。
    #[test]
    fn visibility_projects_roundtrip_and_legacy_compat() {
        // 归一化：去空白/去重/丢非串；非空清单才落键
        assert_eq!(
            visibility_normalize(
                &json!({"space":"project","projects":[" D:\\a ","D:\\a","",r"D:\b"]})
            ),
            json!({"space":"project","sessions":[],"windowMs":null,"projects":["D:\\a",r"D:\b"]}),
        );
        // 旧记录（无 projects 键）：逐字节不变（回归红线）
        assert_eq!(
            visibility_normalize(&json!({"space":"project","projectCwd":"D:\\a"})),
            json!({"space":"project","sessions":[],"windowMs":null,"projectCwd":"D:\\a"}),
        );
        // 严格校验：null/空数组/字符串数组过；空串元素/非数组/非串元素拒
        assert!(visibility_check(&json!({"space":"project","projects":["D:\\a"]})).is_ok());
        assert!(visibility_check(&json!({"space":"project","projects":[]})).is_ok());
        assert!(visibility_check(&json!({"space":"project","projects":null})).is_ok());
        assert!(visibility_check(&json!({"space":"project","projects":[""]})).is_err());
        assert!(visibility_check(&json!({"space":"project","projects":"D:\\a"})).is_err());
        assert!(visibility_check(&json!({"space":"project","projects":[1]})).is_err());
        // vis_of / vis_json 往返：session 档给了 projects → project_bound 也成立（预筛选）
        let v = vis_of(&json!({"space":"session","sessions":["s1"],"projects":["D:\\a"]}));
        assert_eq!(v.projects, vec!["D:\\a"]);
        assert!(
            v.project_bound,
            "session 档 + projects 白名单 → 项目边界成立（先按项目筛再应用会话白名单）"
        );
        assert_eq!(vis_json(&v)["projects"], json!(["D:\\a"]));
        // machine 档带 projects：解析保留但不受其约束（整机忽略 projects）
        let m = vis_of(&json!({"space":"machine","projects":["D:\\a"]}));
        assert_eq!(m.projects, vec!["D:\\a"]);
        assert!(!m.project_bound, "machine 档不受 projects 影响");
    }

    /// 生效项目清单（effective_project_paths）：projects 优先 → 旧单值 projectCwd →
    /// 分享自身 cwd；全空 = 判不了（调用方 fail-open）。
    #[test]
    fn effective_project_paths_multi_and_legacy_fallback() {
        let mut s = test_share(vec![]);
        s.cwd = r"D:\share".into();
        // ① 多项目白名单优先
        let vis = vis_of(&json!({"space":"project","projects":[r"D:\a", r"D:\b"]}));
        assert_eq!(effective_project_paths(&s, &vis), vec![r"D:\a", r"D:\b"]);
        // ② 旧记录 projectCwd（projects 空）= 单项目白名单
        let legacy = vis_of(&json!({"space":"project","projectCwd":r"D:\legacy"}));
        assert_eq!(effective_project_paths(&s, &legacy), vec![r"D:\legacy"]);
        // ③ 都没有 → 分享自身 cwd（2026-10-18 之前的旧行为）
        let none = vis_of(&json!({"space":"project"}));
        assert_eq!(effective_project_paths(&s, &none), vec![r"D:\share"]);
        // ④ 连分享 cwd 都空 → 空清单 = 判不了
        s.cwd = String::new();
        assert!(effective_project_paths(&s, &none).is_empty());
    }

    /// 多项目生效链（effective_visibility）：逐人 projects 与任务级取**交集**（只能收紧）；
    /// 逐人列的都在任务级之外（不相交）= 无效收窄 → 回落任务级清单，绝不放宽。
    #[test]
    fn effective_visibility_projects_merge_only_tightens() {
        let mut share = test_share(vec![]);
        share.state_visibility = json!({"space":"project","projects":[r"D:\a", r"D:\b"]});
        let g = Grant {
            label: "小B".into(),
            did: Some("did:youling:zB".into()),
            ro: false,
            exp: 0,
            window_ms: None,
            caps: None,
            visibility: Some(json!({"space":"project","projects":[r"D:\b", r"D:\c"]})),
        };
        let eff = effective_visibility(&share, Some(&g));
        assert_eq!(
            eff.projects,
            vec![r"D:\b"],
            "逐人 projects ∩ 任务级 projects"
        );
        assert!(eff.project_bound);
        // 不相交 → 回落任务级（天花板不动）
        let g2 = Grant {
            label: "小B".into(),
            did: Some("did:youling:zB".into()),
            ro: false,
            exp: 0,
            window_ms: None,
            caps: None,
            visibility: Some(json!({"space":"project","projects":[r"D:\z"]})),
        };
        let eff2 = effective_visibility(&share, Some(&g2));
        assert_eq!(
            eff2.projects,
            vec![r"D:\a", r"D:\b"],
            "不相交 = 无效收窄 → 任务级清单兜底"
        );
        // 任务级没给 projects、逐人自带 → 逐人清单生效（session 档预筛选场景）
        share.state_visibility = json!({"space":"machine"});
        let eff3 = effective_visibility(&share, Some(&g));
        assert_eq!(eff3.projects, vec![r"D:\b", r"D:\c"]);
        assert!(eff3.project_bound, "逐人 projects 非空 → 边界成立");
    }

    /// 多项目会话清单裁剪：白名单内（含路径归一）留、白名单外丢、认不出 cwd 丢；
    /// session 档 + projects 的预筛选同一把尺。
    #[test]
    fn filter_session_list_project_multi_whitelist() {
        let vis = vis_of(&json!({"space":"project","projects":[r"D:\a", r"D:\b"]}));
        assert!(vis.project_bound);
        let mut doc = json!({"result":{"value":{"sessions":[
            {"sessionId":"s-a","cwd":r"D:\a"},
            {"sessionId":"s-a2","cwd":"d:/A/"},
            {"sessionId":"s-b","cwd":r"D:\b"},
            {"sessionId":"s-c","cwd":r"D:\c"},
            {"sessionId":"s-x"}
        ]}}});
        assert_eq!(
            filter_session_list_project(&mut doc, &vis, &[r"D:\a", r"D:\b"]),
            (5, 3)
        );
        let ids: Vec<&str> = doc["result"]["value"]["sessions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| r["sessionId"].as_str().unwrap())
            .collect();
        assert_eq!(
            ids,
            vec!["s-a", "s-a2", "s-b"],
            "多项目白名单命中（路径归一）+ 白名单外/无 cwd 丢弃"
        );
        // session 档 + projects：预筛选同款（与 sessions 白名单两段叠加 = 先项目后会话）
        let vis_sess = vis_of(&json!({"space":"session","sessions":["s-a"],"projects":[r"D:\a"]}));
        assert!(vis_sess.project_bound);
        let mut doc2 = json!({"sessions":[
            {"sessionId":"s-a","cwd":r"D:\a"},
            {"sessionId":"s-a2","cwd":r"D:\z"},
        ]});
        assert_eq!(
            filter_session_list_project(&mut doc2, &vis_sess, &[r"D:\a"]),
            (2, 1)
        );
    }

    /// 2026-10-24 动作能力审计钉子：`session/selectModel`（换模型/思考等级的会话内入口）
    /// 协作者默认拒；owner 通配放行；任务 caps 显式声明照常放行（任务自己开的门）。
    /// 2026-10-27 设备级 P/A hotfix 后：session/selectModel 走方法级高风险规则
    /// （需要 `model.select` 能力 id 显式声明——session.input 的方法列表携带不再放行）。
    #[test]
    fn caps_session_select_model_default_denied_for_collaborator() {
        let caps = default_caps();
        // 方法级 deny：高风险方法未由对应能力 id（model.select）声明 → 拒
        assert_eq!(
            caps_violation(&caps, "/api/session/selectModel"),
            Some("high-risk")
        );
        assert_eq!(
            caps_violation_as(&owner_caps(), "/api/session/selectModel", true),
            None,
            "owner 通配不受限（admin 显式放行）"
        );
        // session.input 的方法列表携带 selectModel **不再放行**（方法级 deny 只认 model.select id）
        let declared = json!({
            "o": [{"id":"session.read","label":"看","methods":["session/page","session/list"]}],
            "a": [{"id":"session.input","label":"输","methods":["session/prompt","session/selectModel"]}],
        });
        assert_eq!(
            caps_violation(&declared, "/api/session/selectModel"),
            Some("high-risk"),
            "方法级 deny 只认 model.select id——session.input 携带不放行"
        );
        // 显式声明 model.select → 放行
        let with_model = json!({
            "o": [{"id":"session.read","label":"看","methods":["session/page","session/list"]}],
            "a": [{"id":"model.select","label":"选模型","methods":["session/selectModel"]}],
        });
        assert_eq!(
            caps_violation(&with_model, "/api/session/selectModel"),
            None,
            "显式声明 model.select → 放行"
        );
        // 邻居不受伤：默认声明里的 session/prompt 照常放行
        assert_eq!(caps_violation(&caps, "/api/session/prompt"), None);
        // settings/model/llm 写面本就在默认关名单（审计结论的回归钉子）
        assert_eq!(
            caps_violation(&caps, "/api/settings/update"),
            Some("settings/")
        );
        assert_eq!(
            caps_violation(&caps, "/api/model/setDefault"),
            Some("model/")
        );
        // settings 的形状读（describe）仍在豁免面
        assert_eq!(caps_violation(&caps, "/api/settings/describe"), None);
    }

    /// 2026-10-24 授权面板契约：schema 顶层 `sessionCwds` 映射 + sessions options 每条
    /// 带 `cwd`（同源同值；cwd 缺失的会话不进映射）——「指定会话先按已选项目筛」用。
    #[test]
    fn schema_carries_session_cwd_mapping() {
        let view = SessionOptions {
            sessions: vec![
                SessionOption {
                    value: "s1".into(),
                    label: "会话一".into(),
                    cwd: r"D:\a".into(),
                    updated_at: 1,
                },
                SessionOption {
                    value: "s2".into(),
                    label: "会话二".into(),
                    cwd: String::new(),
                    updated_at: 2,
                },
            ],
            workspaces: Vec::new(),
            ..Default::default()
        };
        let mut schema = visibility_schema();
        apply_options_to_schema(&mut schema, "", &view);
        let cwds = schema["sessionCwds"].as_object().unwrap();
        assert_eq!(cwds.len(), 1, "cwd 缺失的会话不进映射");
        assert_eq!(cwds["s1"], json!(r"D:\a"));
        let opts: Vec<serde_json::Value> = schema["items"]
            .as_array()
            .unwrap()
            .iter()
            .find(|i| i["id"] == json!("sessions"))
            .unwrap()["options"]
            .as_array()
            .unwrap()
            .clone();
        assert_eq!(opts[0]["value"], json!("s1"));
        assert_eq!(
            opts[0]["cwd"],
            json!(r"D:\a"),
            "options 每条带 cwd（与 sessionCwds 同源同值）"
        );
    }

    /// 2026-10-18：全量会话行 → id→cwd 映射（项目闸用；空 id 跳过、cwd 原样保留）。
    #[test]
    fn session_rows_cwd_map_builds_all_rows() {
        let row = |id: &str, cwd: &str| SessionRow {
            session_id: id.into(),
            cwd: cwd.into(),
            title: String::new(),
            updated_at: 0,
            blank: false,
            subagent: false,
            parent_session_id: None,
        };
        let rows = vec![row("s-a", r"D:\A"), row("s-b", r"D:\B"), row("  ", r"D:\C")];
        let m = session_rows_cwd_map(&rows);
        assert_eq!(m.len(), 2, "空白 id 不收录");
        assert_eq!(m.get("s-a").map(String::as_str), Some(r"D:\A"));
        assert_eq!(m.get("s-b").map(String::as_str), Some(r"D:\B"));
        assert!(!m.contains_key(""), "空串键不得出现");
    }

    /// 白名单外的 `session/page` → 拒（良性 RPC 错误信封；SPA 不崩、文案是人话）。
    #[test]
    fn visibility_page_outside_whitelist_denied() {
        let vis = vis_of(&json!({"space":"session","sessions":["session-a"]}));
        // 0.2 真实信封：sessionId 藏在 payload.args.request.address 里
        let body: &[u8] = br#"{"type":"client-request","rpcId":"p9","method":"session/page","payload":{"args":{"request":{"address":{"kind":"session","sessionId":"session-b"},"throughSeq":1}}}}"#;
        assert_eq!(
            body_session_ids(body),
            vec!["session-b".to_string()],
            "任意深度抽取会话 id"
        );
        let asked = body_session_ids(body);
        assert!(!vis.allows_session(&asked[0]), "白名单外 → 拒");
        assert!(vis.allows_session("session-a"), "白名单内 → 放行");
        // 全可见 → 谁都放行（默认路径零回归）
        assert!(vis_all().allows_session("session-b"));
        // 拒应答的形状：harness `parseConnectionResponse` 硬校验 error 三者齐全，
        // 且 code 会被原样打印给用户 → 中文短标签、不出现内部术语
        let denied = visibility_denied_json("session-b", "p9");
        assert_eq!(denied["type"], json!("server-response"));
        assert_eq!(denied["rpcId"], json!("p9"));
        assert_eq!(denied["result"]["ok"], json!(false));
        assert!(denied["result"]["error"]["code"].is_string());
        assert_eq!(denied["result"]["error"]["code"], json!("不在可见范围"));
        assert!(denied["result"]["error"]["message"].is_string());
        assert!(denied["result"]["error"]["details"].is_object());
        let wording = denied["result"]["error"]["message"].as_str().unwrap();
        assert!(
            !wording.contains("caps")
                && !wording.contains("visibility")
                && !wording.contains("白名单"),
            "不许出现内部术语: {wording}"
        );
    }

    /// 生效 = **逐人 ∩ 任务级**：只能收紧不能放大；owner 不受限。
    #[test]
    fn visibility_grant_only_narrows_task_scope() {
        let mut s = test_share(vec![]);
        s.state_visibility = json!({"space":"session","sessions":["session-a","session-b"]});
        // ① 没有逐人覆盖 → 就是任务级
        assert_eq!(effective_visibility(&s, None), vis_of(&s.state_visibility));
        // ② 逐人也给 session → 白名单取**交集**
        let mut g = grant("小王", Some("did:youling:w"));
        g.visibility = Some(json!({"space":"session","sessions":["session-b","session-c"]}));
        let eff = effective_visibility(&s, Some(&g));
        assert_eq!(eff.sessions, vec!["session-b".to_string()], "交集");
        assert!(eff.allows_session("session-b"));
        assert!(
            !eff.allows_session("session-c"),
            "逐人不能引进任务级之外的会话"
        );
        // ③ 逐人给 machine（想放大）→ 放大不了，仍受任务级会话白名单约束
        let mut wide = grant("小王", Some("did:youling:w"));
        wide.visibility = Some(json!({"space":"machine","sessions":[]}));
        let eff_w = effective_visibility(&s, Some(&wide));
        assert_eq!(eff_w.space, "session", "取更窄的范围语义");
        assert!(eff_w.restricts_sessions());
        assert!(eff_w.allows_session("session-b"));
        assert!(!eff_w.allows_session("session-c"), "任务级之外一律不可见");
        // ④ owner 行（label=owner 且无 did）→ 全可见（分享者本人不受限）
        assert!(effective_visibility(&s, Some(&grant("owner", None))).is_all_visible());
        // ⑤ 任务级全可见 + 逐人 session → 对这一人收窄（合法：逐人只收紧自己）
        let mut s2 = test_share(vec![]);
        s2.state_visibility = visibility_default();
        let eff2 = effective_visibility(&s2, Some(&g));
        assert_eq!(
            eff2.sessions,
            vec!["session-b".to_string(), "session-c".to_string()]
        );
        assert!(!eff2.allows_session("session-a"));
        // ⑥ 时间窗取更严者（None = 不限历史 = 最宽松）
        s2.state_visibility = json!({"space":"machine","sessions":[],"windowMs":86_400_000});
        let mut w6 = grant("小王", Some("did:youling:w"));
        w6.visibility = Some(json!({"space":"machine","sessions":[],"windowMs":21_600_000}));
        assert_eq!(
            effective_visibility(&s2, Some(&w6)).window_ms,
            Some(21_600_000),
            "逐人 6h 更严"
        );
        let mut w_none = grant("小王", Some("did:youling:w"));
        w_none.visibility = Some(json!({"space":"machine","sessions":[],"windowMs":null}));
        assert_eq!(
            effective_visibility(&s2, Some(&w_none)).window_ms,
            Some(86_400_000),
            "逐人想不限 → 任务级 1d 说了算"
        );
        assert_eq!(
            window_stricter(Some(86_400_000), Some(21_600_000)),
            Some(21_600_000)
        );
    }

    /// 读路径的**生效时间窗** = 既有 `Authz.window_ms`（逐人 windowMs）与
    /// §3.20 `visibility.windowMs` 取更严者；默认全可见时与既有行为逐字节一致。
    #[test]
    fn visibility_effective_window_takes_stricter() {
        let mk = |grant_win: Option<u64>, vis: Vis| Authz {
            label: "小李·a1b2".into(),
            ro: false,
            window_ms: grant_win,
            did: Some("did:youling:x".into()),
            caps: default_caps(),
            vis,
            mt: None,
            device: None,
            role: "legacy_collaborator".into(),
            admin: false,
        };
        assert_eq!(
            mk(Some(21_600_000), vis_all()).eff_window_ms(),
            Some(21_600_000),
            "既有行为不变"
        );
        assert_eq!(
            mk(None, vis_all()).eff_window_ms(),
            None,
            "两边都不限 → 不限"
        );
        assert_eq!(
            mk(None, vis_of(&json!({"windowMs": 21_600_000}))).eff_window_ms(),
            Some(21_600_000),
            "只有 visibility 给了窗 → 用它"
        );
        assert_eq!(
            mk(Some(86_400_000), vis_of(&json!({"windowMs": 21_600_000}))).eff_window_ms(),
            Some(21_600_000),
            "两者都有 → 更严的那个"
        );
        assert_eq!(
            mk(Some(21_600_000), vis_of(&json!({"windowMs": 604_800_000}))).eff_window_ms(),
            Some(21_600_000),
            "visibility 想放宽 → 放不了"
        );
    }

