    /// **实测夹具**：收窄档（`space=session`，白名单 `session-wf-keep`）下从隔离实例
    /// 抓到的 `workspace/follow` baseline 帧**逐字**（2026-10-06，见报告 ①）。
    /// 三个工作区都在里面 —— 这就是"没有会话参数 → S 削减够不着"的泄漏面。
    const WS_BASELINE_MEASURED: &str = r#"{"type":"item","streamId":"f56bb487-4bf7-49a4-9578-741b66329801","value":{"type":"baseline","value":{"items":[{"workspaceId":"ws-wf-keep","path":"D:\\Projects\\labs\\repo-a\\repo-b\\.tmp-e2e\\probe-ws","title":"probe-ws","sessionIds":[],"createdAt":"2026-10-05T09:21:34.699Z","updatedAt":"2026-10-06T09:21:34.699Z"},{"workspaceId":"ws-wf-alpha","path":"D:\\Projects\\labs\\repo-a\\repo-b\\.tmp-e2e\\ws-alpha","title":"ws-alpha","sessionIds":[],"createdAt":"2026-10-05T09:21:34.699Z","updatedAt":"2026-10-06T09:21:34.699Z"},{"workspaceId":"ws-wf-beta","path":"D:\\Projects\\labs\\repo-a\\repo-b\\.tmp-e2e\\ws-beta","title":"ws-beta","sessionIds":[],"createdAt":"2026-10-05T09:21:34.699Z","updatedAt":"2026-10-06T09:21:34.699Z"}],"archivedSessionIds":["session-wf-archived","session-wf-other-archived"]}}}"#;

    /// **实测夹具**：同一次会话里 `$events` 的 `ready` 帧**逐字**（带宿主 home 路径）。
    const EVENTS_READY_MEASURED: &str = r#"{"type":"item","streamId":"c1b71c63-08f5-49aa-9252-714e91eb4664","value":{"type":"ready","clientId":"1b2eebcb-6943-43c4-908f-435d6912b9b5","host":{"home":"C:\\Users\\you"}}}"#;

    /// 夹具里的分享 cwd（`space=project` 的归属判定目标；与帧里 `ws-wf-keep.path` 同一个）。
    const WS_PROJECT_CWD: &str = r#"D:\Projects\labs\repo-a\repo-b\.tmp-e2e\probe-ws"#;

    /// ① **实测帧的空间面裁剪**（`mux_trim_workspace_space`，纯函数）：
    /// 默认档 = 逐字节不动；session 档 = 只留含白名单会话的工作区；project 档 = 只留那一个项目。
    #[test]
    fn mux_workspace_baseline_space_trim_uses_measured_frame() {
        // ── 默认档（machine）：一字节都不改（回归红线）──
        let mut kept = None;
        match mux_trim_workspace_space(
            WS_BASELINE_MEASURED,
            &vis_all(),
            &[WS_PROJECT_CWD],
            &mut kept,
        ) {
            WsSpace::Keep => {}
            _ => panic!("默认档必须原样返回"),
        }

        // ── project 档：只留分享 cwd 那一条（实测帧里就是 ws-wf-keep / probe-ws）──
        let vis_proj = vis_of(&json!({"space": "project", "sessions": [], "windowMs": null}));
        let mut kept_proj = None;
        let out = match mux_trim_workspace_space(
            WS_BASELINE_MEASURED,
            &vis_proj,
            &[WS_PROJECT_CWD],
            &mut kept_proj,
        ) {
            WsSpace::Trimmed(s, n) => {
                assert_eq!(n, 2, "应删掉另外两个工作区");
                s
            }
            _ => panic!("project 档应裁"),
        };
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        let items = v["value"]["value"]["items"].as_array().unwrap();
        assert_eq!(items.len(), 1);
        assert_eq!(items[0]["workspaceId"], json!("ws-wf-keep"));
        assert_eq!(items[0]["title"], json!("probe-ws"));
        // 路径归一（末尾分隔符/大小写/`/`≡`\`）也认得出同一个项目
        let mut kept_proj2 = None;
        assert!(
            matches!(
                mux_trim_workspace_space(
                    WS_BASELINE_MEASURED,
                    &vis_proj,
                    &[r"d:/projects/labs/repo-a/repo-b/.tmp-e2e/probe-ws/"],
                    &mut kept_proj2,
                ),
                WsSpace::Trimmed(_, 2)
            ),
            "路径归一后应仍认得出这一个项目"
        );

        // ── session 档 + 实测帧（三个工作区 sessionIds 都是空）──
        // **2026-10-19 行为变更（用户真案）**：原口径是"判不了归属 → 清空"，但实测帧
        // 就是这种形状（`sessionIds: []`），清空 = 好友打开分享卡只看得到
        // 「选择工作区/暂无会话」、点不进被授权的会话（审计 `mux-workspace-space
        // dropped:176`）。改为 **fail-open 不裁 + 点名信号**：工作区名字/路径会露出来
        // （会话内容仍由 session-list/session-page 白名单拦），换取"好友能真正进入会话"。
        let vis_sess =
            vis_of(&json!({"space": "session", "sessions": ["session-wf-keep"], "windowMs": null}));
        // 2026-10-20：`sessionIds` 空时**先用分享 cwd 做项目归属兜底**——只留被授权会话
        // 所在项目那一个工作区（既避免"暂无会话"，也不把 176 个工作区全发给好友：
        // 少露项目名 + SPA 少渲染 ~500ms）。
        let mut kept_sess = None;
        let out = match mux_trim_workspace_space(
            WS_BASELINE_MEASURED,
            &vis_sess,
            &[WS_PROJECT_CWD],
            &mut kept_sess,
        ) {
            WsSpace::Trimmed(s, n) => {
                assert_eq!(n, 4, "2 个工作区 + 2 条归档 id 越界");
                s
            }
            other => panic!(
                "有 cwd 时应按项目归属裁到 1 个（拿到 {:?}）",
                std::mem::discriminant(&other)
            ),
        };
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        let items = v["value"]["value"]["items"].as_array().unwrap();
        assert_eq!(items.len(), 1, "只留被授权会话所在项目");
        assert_eq!(items[0]["workspaceId"], json!("ws-wf-keep"));
        assert_eq!(
            kept_sess.as_ref().map(|k| k.len()).unwrap_or(0),
            1,
            "账本只记放行的那一个"
        );
        // 没有 cwd 的老分享：仍 fail-open（不能把好友页裁成"暂无会话"）
        let mut kept_nocwd = None;
        match mux_trim_workspace_space(WS_BASELINE_MEASURED, &vis_sess, &[], &mut kept_nocwd) {
            WsSpace::Untrimmed(sig) => assert_eq!(sig, "sessionIds-missing"),
            _ => panic!("无 cwd 时必须 fail-open 不裁 + 信号"),
        }
        assert_eq!(
            kept_nocwd.as_ref().map(|k| k.len()).unwrap_or(0),
            3,
            "fail-open 时账本记全部"
        );

        // ── session 档 + **生产形状**（`sessionIds` 非空：白名单会话在 probe-ws 里）──
        // 实测宿主 `workspaceView()` 逐字：`sessionIds: [...workspace.sessionIds]`
        // （`dsh-api-workspace-controller/lib/index.js`），真实工作区里非空。
        let prod = WS_BASELINE_MEASURED
            .replace(
                r#""title":"probe-ws","sessionIds":[]"#,
                r#""title":"probe-ws","sessionIds":["session-wf-keep"]"#,
            )
            .replace(
                r#""title":"ws-alpha","sessionIds":[]"#,
                r#""title":"ws-alpha","sessionIds":["session-wf-other"]"#,
            )
            .replace(
                r#""archivedSessionIds":["session-wf-archived","session-wf-other-archived"]"#,
                r#""archivedSessionIds":["session-wf-keep","session-wf-other-archived"]"#,
            );
        let mut kept_prod = None;
        let out =
            match mux_trim_workspace_space(&prod, &vis_sess, &[WS_PROJECT_CWD], &mut kept_prod) {
                WsSpace::Trimmed(s, n) => {
                    assert_eq!(n, 3, "另两个工作区 + 1 条越界归档 id");
                    s
                }
                _ => panic!("session 档（生产形状）应裁"),
            };
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        let items = v["value"]["value"]["items"].as_array().unwrap();
        assert_eq!(items.len(), 1, "只留含白名单会话的那个工作区");
        assert_eq!(items[0]["workspaceId"], json!("ws-wf-keep"));
        assert_eq!(
            v["value"]["value"]["archivedSessionIds"],
            json!(["session-wf-keep"])
        );
        assert_eq!(
            kept_prod
                .as_ref()
                .map(|k| k.contains("ws-wf-keep"))
                .unwrap_or(false),
            true,
            "账本要记下已放行的 workspaceId（order 帧过滤用）"
        );

        // ── 形状漂移：认不出 `items` → **不裁** + 留信号（fail-open 要点名）──
        let drift =
            json!({"type":"item","streamId":"s1","value":{"type":"baseline","value":{"nope":[]}}})
                .to_string();
        let mut kept_drift = None;
        match mux_trim_workspace_space(&drift, &vis_sess, &[WS_PROJECT_CWD], &mut kept_drift) {
            WsSpace::Untrimmed(sig) => assert_eq!(sig, "shape-unknown"),
            _ => panic!("形状认不出必须退化为不裁 + 信号"),
        }
        // 分享没有 cwd（project 档判不了）→ 不裁 + 点名
        let mut kept_nocwd = None;
        match mux_trim_workspace_space(WS_BASELINE_MEASURED, &vis_proj, &[], &mut kept_nocwd) {
            WsSpace::Untrimmed(sig) => assert_eq!(sig, "project-unknown"),
            _ => panic!("project 档没有 cwd 时必须退化为不裁 + 信号"),
        }
    }

    // ── 2026-10-24 掉空真案：mux 重连回放（`ws-replay-inject hit:0` 修复）──
    // 根因：①machine 档 u2t 早退从不入槽（回放缓存只有 prewarm 时一次，TTL 一过即空）；
    // ②会话清单快照（session/control baseline——侧栏列表真正的内容源）根本没有回放通道；
    // ③TTL 180s < 页面静置时长，重连必 miss。修后：三个测试分别钉住 machine 入槽、
    // control 槽「裁剪后出口字节」回放、workspace 槽重连命中。

    /// machine 档原样转发的同时把 workspace/control 两槽都续存（此前从不入槽 →
    /// 重连 hit:0 → 列表掉空）。逐字节红线不动：返回值与输入完全相等。
    #[test]
    fn ws_replay_machine_passthrough_fills_both_slots() {
        let gate = Mutex::new(MuxGate::default());
        let authz = mux_authz(owner_caps(), vis_all());
        let out = mux_gate_server_text(
            WS_BASELINE_MEASURED,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-rp-m1",
            "小李·a1b2",
            &vis_all(),
        );
        assert_eq!(out, WS_BASELINE_MEASURED, "machine 档逐字节原样（红线）");
        assert!(
            WS_WORKSPACE_REPLAY
                .lock()
                .unwrap()
                .contains_key(&ws_replay_key("sh-rp-m1", "machine")),
            "workspace baseline 应入槽（重连才有得回放）"
        );
        let control = json!({"type":"item","streamId":"c1","value":{"type":"baseline","value":{"projections":{
            "session-wf-keep": {"title": "keep"}, "session-other": {"title": "x"}}}}}).to_string();
        let out2 = mux_gate_server_text(
            &control,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-rp-m1",
            "小李·a1b2",
            &vis_all(),
        );
        assert_eq!(out2, control, "machine 档 control 帧同样逐字节原样");
        assert!(
            WS_WORKSPACE_REPLAY
                .lock()
                .unwrap()
                .contains_key(&ws_replay_control_key("sh-rp-m1", "machine")),
            "会话清单快照（control baseline）应入 control 槽"
        );
    }

    /// 2026-11-11 数据驱动移除：control 流回放禁用。
    /// 此测试改口径：重连 open 时**不再注入回放**（rx 空 = 无回放数据），
    /// 原断言"应回放一帧"改为"不回放（hit=0）"——回放+抑制整套废弃。
    #[test]
    fn ws_replay_control_replays_trimmed_on_reconnect() {
        // ① session 档真实下行：裁剪 + 入槽（走 u2t 真路径，非直捣缓存）
        let gate = Mutex::new(MuxGate::default());
        let vis = vis_of(&json!({"space": "session", "sessions": ["session-wf-keep"]}));
        let authz = mux_authz(owner_caps(), vis.clone());
        let control = json!({"type":"item","streamId":"c1","value":{"type":"baseline","value":{"projections":{
            "session-wf-keep": {"title": "keep"}, "session-other": {"title": "x"}}}}}).to_string();
        let out = mux_gate_server_text(
            &control,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-rp-c1",
            "小李·a1b2",
            &vis_all(),
        );
        let stored = WS_WORKSPACE_REPLAY
            .lock()
            .unwrap()
            .get(&ws_replay_control_key("sh-rp-c1", "session"))
            .map(|(_, f)| f.clone());
        let stored = stored.expect("裁剪认出形状 → 应入 control 槽");
        assert!(
            stored.contains("session-wf-keep") && !stored.contains("session-other"),
            "槽里=出口字节（已裁）"
        );
        assert_eq!(out, stored, "回放内容与首连所见逐字一致");
        // ② 重连：open(session/control) → 回放已禁用，不注入
        let (tx, mut rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let open = mux_open_frame("session/control", json!({"args": {}}));
        mux_gate_client_text(
            &open,
            MuxMode::Filter,
            &gate,
            &authz,
            "sh-rp-c1",
            "小李·a1b2",
            &tx,
        );
        assert!(
            rx.try_recv().is_err(),
            "control 流回放已禁用（2026-11-11 数据驱动移除，80% 空列表）"
        );
    }

    /// 2026-10-25 笔记本队列不显示真案（RED→GREEN）：
    /// `session/control` 回放命中后，上游再发的那份 **开场 baseline 必须被吞掉**——
    /// 否则客户端见到两份 opening snapshot，直接按协议违规断流（队列从此不显示）。
    /// 只吞第一帧；后续同 streamId 的帧照常透传。
    #[test]
    fn ws_replay_control_suppresses_duplicate_upstream_baseline() {
        // ① 先让 control 槽有货（session 档裁剪 + 入槽）
        let gate = Mutex::new(MuxGate::default());
        let vis = vis_of(&json!({"space": "session", "sessions": ["session-wf-keep"]}));
        let authz = mux_authz(owner_caps(), vis.clone());
        let seed = json!({"type":"item","streamId":"seed-1","value":{"type":"baseline","value":{"projections":{
            "session-wf-keep": {"title": "keep"}, "session-other": {"title": "x"}}}}}).to_string();
        mux_gate_server_text(
            &seed,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-rp-dup",
            "小李·a1b2",
            &vis_all(),
        );
        // ② open(session/control) 命中回放（streamId 改写为 1111…）
        let (tx, mut rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let open = mux_open_frame("session/control", json!({"args": {}}));
        mux_gate_client_text(
            &open,
            MuxMode::Filter,
            &gate,
            &authz,
            "sh-rp-dup",
            "小李·a1b2",
            &tx,
        );
        assert!(rx.try_recv().is_err(), "回放已禁用，不应有注入数据");
        // ③ 上游随后发来同 streamId 的开场 baseline —— 2026-11-11 废弃抑制后必须通过
        let upstream = json!({"type":"item","streamId":"11111111-2222-3333-4444-555555555555","value":{"type":"baseline","value":{"projections":{
            "session-wf-keep": {"title": "keep"}, "session-other": {"title": "x"}}}}}).to_string();
        let passed = mux_gate_server_text(
            &upstream,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-rp-dup",
            "小李·a1b2",
            &vis_all(),
        );
        assert!(
            !passed.is_empty(),
            "control 流 baseline 必须直接通过（回放+抑制已废弃）: {}",
            if passed.is_empty() { "(空串=被吞)" } else { "有数据" }
        );
        // ④ 同 streamId 的后续帧（replacement/增量）不再被吞
        let next = json!({"type":"item","streamId":"11111111-2222-3333-4444-555555555555","value":{"type":"projection","sessionId":"session-wf-keep","values":{"title":"keep2"}}}).to_string();
        let passed = mux_gate_server_text(
            &next,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-rp-dup",
            "小李·a1b2",
            &vis_all(),
        );
        assert!(
            !passed.is_empty(),
            "只吞第一帧，后续同流帧必须照常透传: {passed}"
        );
    }

