    /// 2026-10-27 真案：`session/follow` snapshot 也含 `projections`，但它是
    /// `/value/projections`（同级还有 assistantStream/cursor/header），绝不是
    /// `session/control` 的开场 baseline。旧守卫会把它存进 control 槽，重连时
    /// 回放成首帧 → DSH 报 “update before its opening snapshot” 并断流。
    #[test]
    fn ws_replay_control_rejects_session_follow_snapshot_shape() {
        let gate = Mutex::new(MuxGate::default());
        let authz = mux_authz(owner_caps(), vis_all());
        let follow_snapshot = json!({
            "type": "item",
            "streamId": "follow-1",
            "value": {
                "assistantStream": {"revision": 49},
                "cursor": 21,
                "hasMore": false,
                "header": {"id": "session-x", "version": 4},
                "projections": {"asOfSeq": 21, "values": {"title": "x"}}
            }
        })
        .to_string();
        let out = mux_gate_server_text(
            &follow_snapshot,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-rp-follow",
            "小李·a1b2",
            &vis_all(),
        );
        assert_eq!(out, follow_snapshot, "live 转发不能改字节");
        assert!(
            !WS_WORKSPACE_REPLAY
                .lock()
                .unwrap()
                .contains_key(&ws_replay_control_key("sh-rp-follow", "machine")),
            "session/follow snapshot 绝不能进 control 回放槽"
        );
        // 老缓存里若已有坏帧：take 时也必须拒绝注入（宁可 miss 等上游真 baseline）
        ws_replay_store_at(
            ws_replay_control_key("sh-rp-bad", "machine"),
            &follow_snapshot,
        );
        let (tx, mut rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let hit = ws_replay_take_control("sh-rp-bad", "machine", "new-stream", &tx);
        assert!(!hit, "坏形状 control 缓存必须拒绝回放");
        assert!(rx.try_recv().is_err(), "拒绝回放时不能 inject 任何帧");
    }

