    /// A1（RED）：follow snapshot 天然含 `projections`（真机帧 projection-reconnect-debug
    /// t=19.837：`/value/projections` + assistantStream/cursor/header）。旧代码在 session
    /// 档把它当 control 候选短路 return → `mux_trim_follow_window` 永不可达 → 时间窗
    /// （S 削减的时间面）被绕过，好友可见全部历史。
    #[test]
    fn a1_follow_snapshot_with_projections_still_gets_window_trim() {
        let now = now_ms();
        let stream_id = "11111111-2222-3333-4444-555555555555";
        let follow_open = mux_open_frame("session/follow", mux_follow_payload("session-abc"));
        // 真机形状：/value/type=snapshot + /value/projections（单层）+ value.records
        let snapshot = json!({"type":"item","streamId":stream_id,"value":{
        "type":"snapshot","cursor":21,"hasMore":false,
        "header":{"id":"session-abc","version":4},
        "projections":{"asOfSeq":21,"values":{"title":"x"}},
        "records":[
            {"type":"event","event":{"type":"turn/start","time":now - 7 * 3600 * 1000, "data":{}}},
            {"type":"event","event":{"type":"turn/start","time":now - 1000, "data":{}}},
        ]}})
        .to_string();
        let gate = Mutex::new(MuxGate::default());
        let (tx, _rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let authz = mux_authz(
            default_caps(),
            vis_of(
                &json!({"space":"session","sessions":["session-abc"],"windowMs":6 * 3600 * 1000}),
            ),
        );
        assert!(matches!(
            mux_gate_client_text(
                &follow_open,
                MuxMode::Filter,
                &gate,
                &authz,
                "sh-a1",
                "小李·a1b2",
                &tx
            ),
            MuxOutcome::Forward(_)
        ));
        let out = mux_gate_server_text(
            &snapshot,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-a1",
            "小李·a1b2",
            &vis_all(),
        );
        let v: serde_json::Value =
            serde_json::from_str(&out).unwrap_or_else(|_| panic!("出口应仍是合法 JSON: {out}"));
        let records = v["value"]["records"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        assert_eq!(
            records.len(),
            1,
            "6h 窗必须删掉 7h 前的 record——follow snapshot 不能被 control 分支短路: {out}"
        );
        assert!(
            records[0]["event"]["time"].as_i64().unwrap_or(0) as i128
                > (now - 6 * 3600 * 1000) as i128
        );
    }

