    /// ① 走**真门**（open → item 两个方向）：默认档逐字节、收窄档生效；
    /// 增量帧（`upsert`/`order`/`archived`）同判——否则裁了基线、一条 upsert 又漏。
    #[test]
    fn mux_workspace_space_trim_flows_through_gate() {
        let ws_open = mux_open_frame("workspace/follow", json!({"args": {}}));
        let stream_id = "11111111-2222-3333-4444-555555555555";

        // ── 默认档：open 原样 + baseline 逐字节 ──
        let gate = Mutex::new(MuxGate::default());
        let (tx, _rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let open = mux_authz(default_caps(), vis_all());
        match mux_gate_client_text(
            &ws_open,
            MuxMode::Filter,
            &gate,
            &open,
            "sh-x",
            "小李·a1b2",
            &tx,
        ) {
            MuxOutcome::Forward(s) => assert_eq!(s, ws_open, "默认档 open 帧逐字节"),
            MuxOutcome::Drop => panic!("workspace/follow 默认放行"),
        }
        let measured =
            WS_BASELINE_MEASURED.replace("f56bb487-4bf7-49a4-9578-741b66329801", stream_id);
        assert_eq!(
            mux_gate_server_text(
                &measured,
                MuxMode::Filter,
                &gate,
                &open,
                &[WS_PROJECT_CWD],
                "sh-x",
                "小李·a1b2",
                &vis_all()
            ),
            measured,
            "默认档 baseline 必须逐字节原样（回归红线）"
        );

        // ── 收窄档（session）：同一帧被裁 ──
        let gate2 = Mutex::new(MuxGate::default());
        let narrowed = mux_authz(
            default_caps(),
            vis_of(&json!({"space": "session", "sessions": ["session-wf-keep"], "windowMs": null})),
        );
        assert!(matches!(
            mux_gate_client_text(
                &ws_open,
                MuxMode::Filter,
                &gate2,
                &narrowed,
                "sh-x",
                "小李·a1b2",
                &tx
            ),
            MuxOutcome::Forward(_)
        ));
        let out = mux_gate_server_text(
            &measured,
            MuxMode::Filter,
            &gate2,
            &narrowed,
            &[WS_PROJECT_CWD],
            "sh-x",
            "小李·a1b2",
            &vis_all(),
        );
        // 2026-10-20：实测帧 `sessionIds` 全空 + 有分享 cwd → 按**项目归属**裁到 1 个
        // （上一版为了不出现"暂无会话"直接 fail-open 全放；现在能精确到项目，既可用又不
        // 把 176 个工作区发给好友）。
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        assert_eq!(v["streamId"], json!(stream_id), "只动内容，streamId 不动");
        let items = v["value"]["value"]["items"].as_array().unwrap();
        assert_eq!(items.len(), 1, "只留被授权会话所在项目");
        assert_eq!(items[0]["workspaceId"], json!("ws-wf-keep"));

        // ── 增量 `upsert`：不可见的工作区 → **整帧丢**（空串，连接层据此 continue）──
        let upsert = json!({"type":"item","streamId":stream_id,"value":{"type":"upsert","workspace":{
            "workspaceId":"ws-wf-beta","path":r"D:\Projects\labs\repo-a\repo-b\.tmp-e2e\ws-beta",
            "title":"ws-beta","sessionIds":[],"createdAt":"2026-10-06T09:21:34.699Z","updatedAt":"2026-10-06T09:21:34.699Z"}}})
            .to_string();
        assert_eq!(
            mux_gate_server_text(
                &upsert,
                MuxMode::Filter,
                &gate2,
                &narrowed,
                &[WS_PROJECT_CWD],
                "sh-x",
                "x",
                &vis_all()
            ),
            "",
            "不可见工作区的 upsert 必须整帧丢弃"
        );
        // 可见的那一条 upsert（含白名单会话）→ 原样
        let upsert_ok = upsert
            .replace(r#""ws-wf-beta""#, r#""ws-wf-keep""#)
            .replace(r#""sessionIds":[]"#, r#""sessionIds":["session-wf-keep"]"#);
        assert_eq!(
            mux_gate_server_text(
                &upsert_ok,
                MuxMode::Filter,
                &gate2,
                &narrowed,
                &[WS_PROJECT_CWD],
                "sh-x",
                "x",
                &vis_all()
            ),
            upsert_ok,
            "可见的 upsert 一字节不改"
        );
        // ── 增量 `order`：隐藏工作区的 id 也不该出现（按账本过滤）──
        let order = json!({"type":"item","streamId":stream_id,"value":{"type":"order",
            "workspaceIds":["ws-wf-keep","ws-wf-alpha","ws-wf-beta"]}})
        .to_string();
        let out = mux_gate_server_text(
            &order,
            MuxMode::Filter,
            &gate2,
            &narrowed,
            &[WS_PROJECT_CWD],
            "sh-x",
            "x",
            &vis_all(),
        );
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        // 2026-10-19：基线帧因 `sessionIds` 全空走了 fail-open → 账本记下**全部** workspaceId，
        // order 帧据此全放行（侧栏与基线一致，否则又会出现"有基线没顺序"的空白侧栏）。
        assert_eq!(
            v["value"]["workspaceIds"],
            json!(["ws-wf-keep"]),
            "按项目归属裁后 order 只留那一个"
        );
        // 默认档：同一帧逐字节原样
        assert_eq!(
            mux_gate_server_text(
                &order,
                MuxMode::Filter,
                &gate,
                &open,
                &[WS_PROJECT_CWD],
                "sh-x",
                "x",
                &vis_all()
            ),
            order
        );
    }

    /// ② `$events` 的 `ready` 帧：收窄档把宿主 `host.home` 改成空串占位；
    /// 默认档**逐字节原样**；且改写后仍满足客户端解析器的**严格形状**
    /// （`host` 恰好一个键 `home`、`typeof home === "string"`）。
    #[test]
    fn mux_events_host_home_hidden_only_when_narrowed() {
        let open_frame = mux_open_frame("$events", json!({"args": {}}));
        // 实测帧的 streamId 换成夹具帧的（同一条流的 open 与 item 必须同 id）
        let ready = EVENTS_READY_MEASURED.replace(
            "c1b71c63-08f5-49aa-9252-714e91eb4664",
            "11111111-2222-3333-4444-555555555555",
        );
        let (tx, _rx) = tokio::sync::mpsc::channel::<WsMsg>(4);

        // ── 默认档：一字节不改 ──
        let gate = Mutex::new(MuxGate::default());
        let open = mux_authz(default_caps(), vis_all());
        assert!(matches!(
            mux_gate_client_text(
                &open_frame,
                MuxMode::Filter,
                &gate,
                &open,
                "sh-x",
                "小李·a1b2",
                &tx
            ),
            MuxOutcome::Forward(_)
        ));
        assert_eq!(
            mux_gate_server_text(
                &ready,
                MuxMode::Filter,
                &gate,
                &open,
                &[],
                "sh-x",
                "x",
                &vis_all()
            ),
            ready,
            "默认档 ready 帧必须逐字节原样"
        );

        // ── 收窄档：home → ""（帧其余部分不变，形状仍严格合法）──
        let gate2 = Mutex::new(MuxGate::default());
        let narrowed = mux_authz(
            default_caps(),
            vis_of(&json!({"space": "session", "sessions": ["session-wf-keep"], "windowMs": null})),
        );
        assert!(matches!(
            mux_gate_client_text(
                &open_frame,
                MuxMode::Filter,
                &gate2,
                &narrowed,
                "sh-x",
                "小李@b",
                &tx
            ),
            MuxOutcome::Forward(_)
        ));
        let out = mux_gate_server_text(
            &ready,
            MuxMode::Filter,
            &gate2,
            &narrowed,
            &[],
            "sh-x",
            "x",
            &vis_all(),
        );
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        assert_eq!(
            v["value"]["host"]["home"],
            json!(""),
            "宿主 home 必须是不可反推的占位"
        );
        assert_eq!(
            v["value"]["clientId"],
            json!("1b2eebcb-6943-43c4-908f-435d6912b9b5"),
            "握手字段不动"
        );
        // 客户端解析器的**严格形状**（`dsh-api-gateway` parseRemoteEventReady 逐字）：
        let mut vkeys: Vec<String> = v.as_object().unwrap().keys().cloned().collect();
        vkeys.sort();
        assert_eq!(vkeys, vec!["streamId", "type", "value"], "帧外壳不能多键");
        let mut inner: Vec<String> = v["value"].as_object().unwrap().keys().cloned().collect();
        inner.sort();
        assert_eq!(inner, vec!["clientId", "host", "type"]);
        assert_eq!(
            v["value"]["host"]
                .as_object()
                .unwrap()
                .keys()
                .collect::<Vec<_>>(),
            vec!["home"],
            "host 必须**恰好**一个键（多一个键客户端就判 invalid）"
        );
        assert!(
            v["value"]["host"]["home"].is_string(),
            "home 必须是 string（删键会整页起不来）"
        );
        assert!(!out.contains("Users"), "宿主家目录路径不得留在帧里");
        // 已经是空串 → 不该重复改写（逐字节纪律）
        assert_eq!(
            mux_gate_server_text(
                &out,
                MuxMode::Filter,
                &gate2,
                &narrowed,
                &[],
                "sh-x",
                "x",
                &vis_all()
            ),
            out
        );
    }

    /// ③ 两个一元端点的 **HTTP 面**收口：`skills/list`（技能名 + 文件路径）、
    /// `speech/transcribe`（音频外发 + 转写算力）→ 默认拒；读豁免面不受影响；
    /// 任务显式声明仍然开得了门（能力集属于任务）。
    #[test]
    fn caps_denied_covers_unary_skill_and_speech_http_face() {
        let caps = default_caps();
        assert_eq!(
            caps_violation(&caps, "api/skills/list"),
            Some("skills/list")
        );
        assert_eq!(
            caps_violation(&caps, "/api/speech/transcribe"),
            Some("speech/transcribe")
        );
        // 2026-10-06 第四轮：语音面其余三个一元端点（取证见 CAPS_DENIED 段注释：
        // prepare/configure/cancelPreparation 客户端全部 try/catch + 行内 alert，不坏页）
        assert_eq!(
            caps_violation(&caps, "api/speech/prepare"),
            Some("speech/prepare")
        );
        assert_eq!(
            caps_violation(&caps, "api/speech/configure"),
            Some("speech/configure")
        );
        assert_eq!(
            caps_violation(&caps, "api/speech/cancelPreparation"),
            Some("speech/cancelPreparation")
        );
        // 另外三个（既有规则）：确认它们本来就落在名单上（HTTP 面同判）
        assert_eq!(
            caps_violation(&caps, "api/terminal/write"),
            Some("terminal")
        );
        assert_eq!(
            caps_violation(&caps, "api/workspace/unpinSession"),
            Some("workspace/unpinSession")
        );
        assert_eq!(
            caps_violation(&caps, "api/workspaceFiles/stat"),
            Some("workspaceFiles/")
        );
        // 读豁免面**不得**被误伤（装载面必需：拒了只有噪音）
        for ok in [
            "api/commands/list",
            "api/llm/listProviders",
            "api/settings/describe",
            "api/permissionPresets/catalog",
            "api/session/list",
            "api/session/page",
            "api/session/prompt",
        ] {
            assert_eq!(caps_violation(&caps, ok), None, "{ok} 必须仍然放行");
        }
        // `speech/follow`（mux 上已放行的 provider 目录流）与 `speech/catalog`
        // （读命令）**不得被误伤**——三条新条目是全等条目，绝不能上 `speech/` 前缀
        assert_eq!(
            caps_violation(&caps, "api/speech/follow"),
            None,
            "speech/follow 必须仍然放行"
        );
        assert_eq!(
            caps_violation(&caps, "api/speech/catalog"),
            None,
            "speech/catalog 必须仍然放行"
        );
        // 任务显式声明 → 同一请求放行（网关不代替任务做主）
        let declared = json!({"o": [{"id": "skill.view", "label": "看技能", "methods": ["skills/*"]}],
                              "a": [{"id": "speech.stt", "label": "语音转写", "methods": ["speech/transcribe"]}]});
        assert_eq!(caps_violation(&declared, "api/skills/list"), None);
        assert_eq!(caps_violation(&declared, "api/speech/transcribe"), None);
        // owner（全通配）不受影响
        assert_eq!(
            caps_violation_as(&owner_caps(), "api/skills/list", true),
            None
        );
        for ep in [
            "api/speech/prepare",
            "api/speech/configure",
            "api/speech/cancelPreparation",
        ] {
            assert_eq!(
                caps_violation_as(&owner_caps(), ep, true),
                None,
                "owner 全通配：{ep} 不受默认关名单影响"
            );
        }
        // mux 面同判（两条都是一元方法 → 宿主本来就在流载体上自拒；这里只是"同一份名单"）
        let guest = mux_authz(default_caps(), vis_all());
        for ep in [
            "skills/list",
            "speech/transcribe",
            "speech/prepare",
            "speech/configure",
            "speech/cancelPreparation",
        ] {
            let v: serde_json::Value =
                serde_json::from_str(&mux_open_frame(ep, json!({"args": {}}))).unwrap();
            assert!(
                matches!(mux_open_verdict(&guest, ep, &v), Some(MuxDeny::Caps(_))),
                "{ep} 与 HTTP 面用同一份默认关名单"
            );
        }
    }

    /// 帧样本解析：认得出 `endpoint` 与会话 id；非 open / 无会话参数 → 不猜。
    #[test]
    fn mux_frame_parsing_matches_measured_wire() {
        let f = mux_open_frame("session/follow", mux_follow_payload("session-abc"));
        let v: serde_json::Value = serde_json::from_str(&f).unwrap();
        assert_eq!(mux_open_endpoint(&v).as_deref(), Some("session/follow"));
        assert_eq!(mux_open_session_id(&v).as_deref(), Some("session-abc"));
        // 非 open 帧：没有方法名载体
        assert_eq!(
            mux_open_endpoint(&json!({"type": "item", "streamId": "s1", "value": {}})),
            None
        );
        // workspace/follow 实测就是空 args（无会话可寻址）→ 不猜出会话 id
        let w: serde_json::Value =
            serde_json::from_str(&mux_open_frame("workspace/follow", json!({"args": {}}))).unwrap();
        assert_eq!(mux_open_session_id(&w), None);
    }

    /// **零回归红线**：默认 caps + 不收窄可见性时，实测 SPA 真开的 5 条流
    /// 全部放行，且**逐字节原样转发**（不重新序列化）。
    #[test]
    fn mux_default_path_forwards_every_measured_stream_byte_for_byte() {
        let gate = Mutex::new(MuxGate::default());
        let (tx, mut rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let authz = mux_authz(default_caps(), vis_all());
        // 2026-10-06 抓包：分享页启动时实际开的流（顺序即实测顺序）
        let measured: [(&str, serde_json::Value); 5] = [
            ("speech/follow", json!({"args": {}})),
            ("workspace/follow", json!({"args": {}})),
            ("$events", json!({"args": {}})),
            ("session/control", json!({"args": {}})),
            ("session/follow", mux_follow_payload("session-abc")),
        ];
        for (ep, payload) in measured {
            let f = mux_open_frame(ep, payload);
            match mux_gate_client_text(&f, MuxMode::Filter, &gate, &authz, "sh-x", "小李·a1b2", &tx)
            {
                MuxOutcome::Forward(out) => assert_eq!(out, f, "默认路径必须逐字节原样转发：{ep}"),
                MuxOutcome::Drop => panic!("默认路径不得拦实测流：{ep}"),
            }
        }
        assert!(rx.try_recv().is_err(), "默认路径不得回任何合成帧");
    }

    /// A 限制在帧面与 HTTP 面**同一套判定**：HTTP 拒的（终端/文件面）mux 上同样拒。
    #[test]
    fn mux_caps_deny_agrees_with_http_face() {
        let authz = mux_authz(default_caps(), vis_all());
        for ep in [
            "terminal/write",
            "terminal/follow",
            "terminal/retain",
            "workspaceFiles/stat",
            "workspaceFiles/changes",
        ] {
            let v: serde_json::Value =
                serde_json::from_str(&mux_open_frame(ep, json!({"args": {}}))).unwrap();
            assert!(
                matches!(mux_open_verdict(&authz, ep, &v), Some(MuxDeny::Caps(_))),
                "{ep} 在 mux 面也必须被 caps 拦住（与 HTTP 面同一份默认关名单）"
            );
        }
        // 反面：任务显式声明 → 同一帧放行（能力集属于任务，帧面不另立规矩）
        // 2026-10-27 设备级 P/A hotfix：terminal 方法需要 terminal.exec id（terminal.rw 不再放行）
        let declared = json!({"o": [], "a": [{"id": "terminal.exec", "label": "终端", "methods": ["terminal/*"]}]});
        let authz2 = mux_authz(declared, vis_all());
        let v: serde_json::Value =
            serde_json::from_str(&mux_open_frame("terminal/write", json!({"args": {}}))).unwrap();
        assert!(
            mux_open_verdict(&authz2, "terminal/write", &v).is_none(),
            "显式 terminal.exec → 放行"
        );
    }

    /// **mux 流端点权限表**（2026-10-06 第二轮实测收口）：把 18 个被枚举出来的
    /// "流"名字逐条钉住判定——**该拒的拒了 / 该放的没动**。
    ///
    /// 证据链（三份独立材料，逐条可回溯）：
    ///   ① 客户端 + 宿主描述符严格解析（花括号配对，不信子串匹配）→ 真流 **13** 条；
    ///   ② 运行时自证：把一元端点当流开，宿主回
    ///      `gateway/signature-invalid: unary Remote methods cannot be opened through
    ///       the stream carrier`（隔离实例真页面实测，逐字）；
    ///   ③ 页面真流量抓包（透明 relay 观测 `/api/remote.mux`）+ 宿主 open 应答。
    #[test]
    fn mux_stream_surface_verdicts_match_measured_evidence() {
        let guest = mux_authz(default_caps(), vis_all());
        let verdict = |ep: &str| -> Option<MuxDeny> {
            let v: serde_json::Value =
                serde_json::from_str(&mux_open_frame(ep, json!({"args": {}}))).unwrap();
            mux_open_verdict(&guest, ep, &v)
        };

        // ── 拒：终端执行面 / 文件读写面 / 后台 job 输出面 ──
        // （`terminal/*` 与 `workspaceFiles/*` 是既有规则；`job/*` 是 2026-10-06 补：
        //   载荷带原始命令输出 `chunks[].text` 与绝对路径 `output.spillPaths`）
        for ep in [
            "terminal/follow",
            "terminal/retain",
            "terminal/write",
            "workspaceFiles/changes",
            "workspaceFiles/stat",
            "job/list",
            "job/follow",
            // 写方法（一元，故实际只在 HTTP 面生效；mux 上宿主自拒，这里同判为拒）
            "workspace/unpinSession",
        ] {
            assert!(
                matches!(verdict(ep), Some(MuxDeny::Caps(_))),
                "{ep} 必须被 mux 帧层拒（越界类：终端执行 / 文件 / job 输出 / 写）"
            );
        }

        // ── 放行：无内容 / 纯状态 / 已有裁剪 ──
        // 含 5 条**未触发**的（`account/*` 与 `productAnalytics/watchPolicy` 只在
        // DSH Desktop 开；`userQuestions/attachWait` 需带 timeout 的 agent 提问回合）——
        // **无证据不默认拒**（§3.12.4：升版不该整页崩），只记普查。
        for ep in [
            "account/watch",
            "account/watchExpiry",
            "productAnalytics/watchPolicy",
            "userQuestions/attachWait",
            "session/follow",
            "session/control",
            "workspace/follow",
            "speech/follow",
        ] {
            assert!(
                verdict(ep).is_none(),
                "{ep} 不在默认关名单里 → 默认放行（只记普查）"
            );
        }
        // 2026-10-06 第三轮：`skills/list`·`speech/transcribe` 是**一元**方法
        // （宿主在流载体上自拒），这一轮按 HTTP 面取证把它们加进同一份默认关名单 →
        // mux 面同判为拒（不新造第二套语义；见 `caps_denied_covers_unary_skill_and_speech_http_face`）。
        for ep in ["skills/list", "speech/transcribe"] {
            assert!(
                matches!(verdict(ep), Some(MuxDeny::Caps(_))),
                "{ep} 已进默认关名单（HTTP 面收口，mux 面同判）"
            );
        }

        // 反面：owner 是全通配（`*`）+ Authz.admin=true → 连 job/* 也照放
        // （名单只裁非 admin；admin 由 Authz.admin 显式放行，不再用 caps 形状猜）
        let mut owner = mux_authz(owner_caps(), vis_all());
        owner.admin = true;
        let v: serde_json::Value =
            serde_json::from_str(&mux_open_frame("job/list", json!({"args": {}}))).unwrap();
        assert!(
            mux_open_verdict(&owner, "job/list", &v).is_none(),
            "owner 不受默认关名单影响"
        );
    }

    /// `mux-unscoped` 留痕面（纯函数）：收窄档下**带会话语义却认不出目标**的流要点名，
    /// 而本就无会话目标的全局流（workspace/follow、speech/follow）不该被算进来当噪音。
    #[test]
    fn mux_unscoped_stream_faces_are_exact() {
        let no_sid = json!({"args": {}});
        // 带会话语义 + 认不出目标 → 该留痕
        for ep in [
            "session/control",
            "job/follow",
            "job/list",
            "terminal/follow",
            "workspaceFiles/changes",
            "userQuestions/attachWait",
            "subagent/list",
        ] {
            assert!(
                mux_unscoped_stream(ep, &no_sid),
                "{ep} 属「看不清目标」的会话流 → 必须留痕"
            );
        }
        // 全局流（无会话语义）→ 不该留痕（否则审计变噪音，等于没有审计）
        for ep in [
            "workspace/follow",
            "speech/follow",
            "account/watch",
            "$events",
        ] {
            assert!(
                !mux_unscoped_stream(ep, &no_sid),
                "{ep} 是全局流，不该记 mux-unscoped"
            );
        }
        // 认得出目标 → 走会话白名单那条路，不算 unscoped
        // （注意：会话 id 只在 **open 帧** 的 payload 里取，所以要喂帧不是喂 payload）
        let with_sid: serde_json::Value = serde_json::from_str(&mux_open_frame(
            "job/list",
            json!({"args": {"sessionId": "session-abc"}}),
        ))
        .unwrap();
        assert!(
            !mux_unscoped_stream("job/list", &with_sid),
            "认得出会话 → 由 vis 校验兜着"
        );
        let follow: serde_json::Value = serde_json::from_str(&mux_open_frame(
            "session/follow",
            mux_follow_payload("session-abc"),
        ))
        .unwrap();
        assert!(
            !mux_unscoped_stream("session/follow", &follow),
            "session/follow 认得出目标"
        );
    }

    /// 被拒的流：`open` 不转发 + 回一帧**形状严格**的良性 error；后续
    /// `item`/`end`/`cancel` 一并丢弃（上游从没见过这条流）。
    #[test]
    fn mux_denied_stream_is_dropped_and_answered_with_strict_error_frame() {
        let gate = Mutex::new(MuxGate::default());
        let (tx, mut rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let authz = mux_authz(default_caps(), vis_all());
        let f = mux_open_frame("terminal/write", json!({"args": {}}));
        assert!(
            matches!(
                mux_gate_client_text(&f, MuxMode::Filter, &gate, &authz, "sh-x", "小李·a1b2", &tx),
                MuxOutcome::Drop
            ),
            "默认关名单内的流不得转发"
        );
        let injected = match rx.try_recv() {
            Ok(WsMsg::Text(t)) => t.to_string(),
            other => panic!("应回一帧 error，实际 {other:?}"),
        };
        let v: serde_json::Value = serde_json::from_str(&injected).unwrap();
        assert_eq!(v["type"], "error");
        assert_eq!(v["streamId"], "11111111-2222-3333-4444-555555555555");
        assert_eq!(
            v["error"]["code"], "受保护",
            "文案与 HTTP 面同源（中文短标签）"
        );
        // ⚠️ harness 的 parseRemoteStreamServerMessage 严格校验：error 恰好 code/message/details
        let mut keys: Vec<String> = v["error"].as_object().unwrap().keys().cloned().collect();
        keys.sort();
        assert_eq!(
            keys,
            vec!["code", "details", "message"],
            "error 多一个键整帧就被判无效"
        );
        assert!(v["error"]["details"].is_object(), "details 必须是对象");
        assert!(
            v["error"]["message"].as_str().unwrap().contains("任务群"),
            "人话 + 指路"
        );
        // 后续帧不再转给上游
        let sid = "11111111-2222-3333-4444-555555555555";
        for tail in [
            json!({"type": "item", "streamId": sid, "value": 1}),
            json!({"type": "end", "streamId": sid}),
            json!({"type": "cancel", "streamId": sid}),
        ] {
            assert!(
                matches!(
                    mux_gate_client_text(
                        &tail.to_string(),
                        MuxMode::Filter,
                        &gate,
                        &authz,
                        "sh-x",
                        "小李·a1b2",
                        &tx
                    ),
                    MuxOutcome::Drop
                ),
                "已拒流的后续帧必须丢：{tail}"
            );
        }
    }

    /// S 削减上帧面：收窄到白名单后，`session/follow` 指到白名单外 → 拒；
    /// 指白名单内 / 默认全可见 → 放行（后者是零回归红线）。
    #[test]
    fn mux_follow_respects_session_visibility() {
        let vis =
            vis_of(&json!({"space": "session", "sessions": ["session-abc"], "windowMs": null}));
        let restricted = mux_authz(default_caps(), vis);
        let gate = Mutex::new(MuxGate::default());
        let (tx, mut rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let ok = mux_open_frame("session/follow", mux_follow_payload("session-abc"));
        assert!(
            matches!(
                mux_gate_client_text(
                    &ok,
                    MuxMode::Filter,
                    &gate,
                    &restricted,
                    "sh-x",
                    "小李·a1b2",
                    &tx
                ),
                MuxOutcome::Forward(_)
            ),
            "白名单内的会话必须放行"
        );
        let bad = mux_open_frame("session/follow", mux_follow_payload("session-other"));
        assert!(
            matches!(
                mux_gate_client_text(
                    &bad,
                    MuxMode::Filter,
                    &gate,
                    &restricted,
                    "sh-x",
                    "小李·a1b2",
                    &tx
                ),
                MuxOutcome::Drop
            ),
            "白名单外的会话内容不得经 mux 流出去"
        );
        let injected = match rx.try_recv() {
            Ok(WsMsg::Text(t)) => t.to_string(),
            other => panic!("应回一帧 error，实际 {other:?}"),
        };
        let v: serde_json::Value = serde_json::from_str(&injected).unwrap();
        assert_eq!(
            v["error"]["code"], "不在可见范围",
            "与 HTTP 面 visibility_denied_json 同款文案"
        );
        // 零回归：不设可见性时同一个帧放行
        let open = mux_authz(default_caps(), vis_all());
        let gate2 = Mutex::new(MuxGate::default());
        assert!(
            matches!(
                mux_gate_client_text(
                    &bad,
                    MuxMode::Filter,
                    &gate2,
                    &open,
                    "sh-x",
                    "小李·a1b2",
                    &tx
                ),
                MuxOutcome::Forward(_)
            ),
            "默认全可见 → 不拦（零回归）"
        );
    }

    /// 收窄档下"带会话语义但认不出目标"的流（实测：`session/control` 就是空 args）
    /// **放行**（同 §3.12.4：未识别不默认拒，拒了会把收窄档的页面弄坏），但留痕。
    #[test]
    fn mux_unscoped_session_stream_is_allowed_but_audited() {
        let restricted = mux_authz(
            default_caps(),
            vis_of(&json!({"space": "session", "sessions": ["session-abc"]})),
        );
        let v: serde_json::Value =
            serde_json::from_str(&mux_open_frame("session/control", json!({"args": {}}))).unwrap();
        assert!(
            mux_open_verdict(&restricted, "session/control", &v).is_none(),
            "认不出目标 → 不拒"
        );
        // 默认档更不必说
        let open = mux_authz(default_caps(), vis_all());
        assert!(mux_open_verdict(&open, "session/control", &v).is_none());
    }

    /// 时间窗裁剪：`session/follow` 的 `item.value.records` 与 `session/page` 同形状，
    /// 复用同一个 `filter_page_window`；**没删到就逐字节原样**（默认路径不变）。
    #[test]
    fn mux_follow_snapshot_window_trim_reuses_page_filter() {
        let now = now_ms();
        let item = json!({
            "type": "item",
            "streamId": "s1",
            "value": {
                "type": "snapshot",
                "cursor": 7559,
                "records": [
                    {"type": "event", "event": {"type": "turn/start", "time": now - 7 * 3600 * 1000, "data": {}}},
                    {"type": "event", "event": {"type": "turn/start", "time": now - 1000, "data": {}}},
                ],
            },
        })
        .to_string();
        let (out, dropped) = mux_trim_follow_window(&item, 6 * 3600 * 1000);
        assert_eq!(dropped, 1, "6h 窗应删掉 7h 前那条");
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        assert_eq!(v["value"]["records"].as_array().unwrap().len(), 1);
        // 窗内一条都删不掉 → 原样（不重新序列化）
        let (same, d0) = mux_trim_follow_window(&item, 100 * 3600 * 1000);
        assert_eq!(d0, 0);
        assert_eq!(same, item);
        // 非 item / 非 JSON → 原样
        assert_eq!(mux_trim_follow_window("not json", 1000).0, "not json");
        assert_eq!(
            mux_trim_follow_window(&json!({"type": "end", "streamId": "s1"}).to_string(), 1000).1,
            0
        );
    }

    /// `passthrough` = 应急回退位：**一帧都不改、一帧都不拦**，但普查照记
    /// （否则"哪些走 mux"永远查不出来）。
    #[test]
    fn mux_passthrough_never_touches_frames_but_still_censuses() {
        let gate = Mutex::new(MuxGate::default());
        let (tx, mut rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        // 故意给最坏输入：收窄可见性 + 默认关名单内的方法
        let authz = mux_authz(
            default_caps(),
            vis_of(&json!({"space": "session", "sessions": ["session-abc"]})),
        );
        for (ep, payload) in [
            ("terminal/write", json!({"args": {}})),
            ("session/follow", mux_follow_payload("session-other")),
        ] {
            let f = mux_open_frame(ep, payload);
            match mux_gate_client_text(
                &f,
                MuxMode::Passthrough,
                &gate,
                &authz,
                "sh-x",
                "小李·a1b2",
                &tx,
            ) {
                MuxOutcome::Forward(out) => {
                    assert_eq!(out, f, "passthrough 必须逐字节原样转发：{ep}")
                }
                MuxOutcome::Drop => panic!("passthrough 不得丢帧：{ep}"),
            }
        }
        assert!(rx.try_recv().is_err(), "passthrough 不得回任何合成帧");
        assert!(
            rpc_census()
                .lock()
                .unwrap()
                .keys()
                .any(|k| k.starts_with("MUX open(")),
            "passthrough 也要把 mux 面记进普查"
        );
        // 下行同样不动
        let down = json!({"type": "item", "streamId": "s1", "value": {"records": []}}).to_string();
        assert_eq!(
            mux_gate_server_text(
                &down,
                MuxMode::Passthrough,
                &gate,
                &authz,
                &[],
                "sh-x",
                "小李·a1b2",
                &vis_all()
            ),
            down
        );
    }

    /// 模式解析：**默认 filter**，认不出的值不静默退化成全放行。
    #[test]
    fn mux_mode_defaults_to_filter() {
        assert_eq!(mux_mode_of(""), MuxMode::Filter, "未设 = filter（默认档）");
        assert_eq!(mux_mode_of("  FILTER "), MuxMode::Filter);
        assert_eq!(
            mux_mode_of("garbage"),
            MuxMode::Filter,
            "认不出 → 回落默认档，不得变全放行"
        );
        assert_eq!(mux_mode_of("passthrough"), MuxMode::Passthrough);
        assert_eq!(mux_mode_of("off"), MuxMode::Passthrough);
        assert_eq!(mux_mode_of("deny"), MuxMode::Deny);
    }

    /// 路由识别：只对 Typert 流多路复用面做帧门控（其它 WS 路由不被我们的语义绑架）。
    #[test]
    fn mux_path_detection_is_exact() {
        assert!(is_mux_path("api/remote.mux"));
        assert!(is_mux_path("app/api/remote.mux"));
        assert!(is_mux_path("/api/remote.mux/"));
        assert!(!is_mux_path("api/session/list"));
        assert!(!is_mux_path("remote.mux.evil"));
        assert!(!is_mux_path(""));
    }

    /// 归一化（宽松：读盘不报错）与严格校验（写入面：失败一律 Err）。
    #[test]
    fn visibility_normalize_and_check() {
        assert_eq!(
            visibility_normalize(
                &json!({"space":"session","sessions":[" b ","b","",3],"windowMs":6})
            ),
            json!({"space":"session","sessions":["b"],"windowMs":6}),
            "去空白/去重/丢非串"
        );
        assert_eq!(
            visibility_normalize(&json!({"space":"整机","sessions":"x","windowMs":-5})),
            visibility_default(),
            "坏值退化成全可见（不报错）"
        );
        assert_eq!(
            visibility_normalize(&json!({"extra": 1})),
            visibility_default(),
            "只留三个已知键"
        );
        assert!(
            visibility_check(&json!({"space":"session","sessions":["s1"],"windowMs":null})).is_ok()
        );
        assert!(
            visibility_check(&json!({})).is_ok(),
            "空对象 = 用默认（合法）"
        );
        for bad in [
            json!("全可见"),
            json!({"space": "all"}),
            json!({"space": 7}),
            json!({"sessions": [1]}),
            json!({"sessions": "s1"}),
            json!({"windowMs": "6h"}),
        ] {
            assert!(visibility_check(&bad).is_err(), "必须 Err: {bad}");
        }
    }

