    /// 界面契约：可配置项清单（**哪些给人选、哪些是默认**）——UI 按它渲染，
    /// 所以 id / 默认值 / 枚举值 / dependsOn 都要钉死。
    #[test]
    fn visibility_schema_items_locked() {
        let s = visibility_schema();
        let items = s["items"].as_array().unwrap();
        let ids: Vec<&str> = items.iter().filter_map(|i| i["id"].as_str()).collect();
        assert_eq!(ids, vec!["space", "sessions", "windowMs", "capsO", "capsA"]);
        assert_eq!(items[0]["kind"], json!("enum"));
        assert_eq!(items[0]["default"], json!("machine"));
        let spaces: Vec<serde_json::Value> = items[0]["options"]
            .as_array()
            .unwrap()
            .iter()
            .map(|o| o["value"].clone())
            .collect();
        assert_eq!(
            spaces,
            vec![json!("machine"), json!("project"), json!("session")]
        );
        assert_eq!(items[1]["kind"], json!("multi"));
        assert_eq!(items[1]["source"], json!("sessions"));
        assert_eq!(items[1]["default"], json!([]));
        assert_eq!(items[1]["dependsOn"], json!({"space": "session"}));
        assert_eq!(items[2]["default"], json!(null));
        let windows: Vec<serde_json::Value> = items[2]["options"]
            .as_array()
            .unwrap()
            .iter()
            .map(|o| o["value"].clone())
            .collect();
        assert_eq!(
            windows,
            vec![
                json!(null),
                json!(21600000),
                json!(86400000),
                json!(604800000)
            ]
        );
        // 既有三项可配；能力面两项（2026-10-24 用户要求）也已接线可编辑——
        // 写路径见 share_set_visibility_impl 的 capsO/capsA 分支。
        assert!(items.iter().all(|i| i["selectable"] == json!(true)));
        // 能力面两项：骨架自带兜底词表（四项全列，options 恰好 {value,label} 两键）
        for (idx, dir) in [(3usize, "o"), (4, "a")] {
            assert_eq!(items[idx]["kind"], json!("multi"));
            assert_eq!(items[idx]["source"], json!("capabilityCatalog"));
        }
        let o_vals: Vec<serde_json::Value> = items[3]["options"]
            .as_array()
            .unwrap()
            .iter()
            .map(|o| o["value"].clone())
            .collect();
        assert_eq!(o_vals, vec![json!("session.read"), json!("agent.view")]);
        let a_vals: Vec<serde_json::Value> = items[4]["options"]
            .as_array()
            .unwrap()
            .iter()
            .map(|o| o["value"].clone())
            .collect();
        assert_eq!(a_vals, vec![json!("session.input"), json!("scope.switch")]);
        assert_eq!(
            items[3]["default"],
            json!(["session.read"]),
            "默认授予与 default_caps 同口径"
        );
        assert_eq!(items[4]["default"], json!(["session.input"]));
        assert!(
            items[3]["options"]
                .as_array()
                .unwrap()
                .iter()
                .all(|o| o.as_object().unwrap().len() == 2),
            "option 只有 {{value,label}} 两键"
        );
    }

    /// 兼容（**升级不能丢分享、也不能把既有分享突然变看不见**）：老记录缺
    /// `stateVisibility` / grant 缺 `visibility` → 全可见；发布面 `visibility`
    /// （private|public）语义与落盘键不变。
    #[test]
    fn parse_share_visibility_backward_compatible() {
        let old = json!({
            "id": "sh-old", "title": "老分享", "visibility": "public",
            "grants": [{"label": "owner", "exp": 9}, {"label": "小王", "did": "did:youling:w", "exp": 9}],
        });
        let s = parse_share(&old).expect("老记录必须能加载");
        assert_eq!(
            s.listing, "public",
            "发布面语义不变（落盘键仍叫 visibility）"
        );
        assert!(
            vis_of(&s.state_visibility).is_all_visible(),
            "缺 stateVisibility → 全可见"
        );
        assert_eq!(
            s.grants[1].visibility, None,
            "缺逐人 visibility → None（继承任务级）"
        );
        // 新记录：任务级 + 逐人都落盘读回
        let new = json!({
            "id": "sh-new", "stateVisibility": {"space":"session","sessions":["s1"],"windowMs":21600000},
            "grants": [{"label": "小王", "did": "did:youling:w", "visibility": {"space":"project"}}],
        });
        let s2 = parse_share(&new).expect("新记录");
        assert_eq!(
            s2.state_visibility,
            json!({"space":"session","sessions":["s1"],"windowMs":21600000})
        );
        assert_eq!(
            s2.grants[0].visibility,
            Some(json!({"space":"project","sessions":[],"windowMs":null}))
        );
        // 脏数据：非对象 / 坏类型 → 全可见，不 panic、不报错
        for junk in [json!("全可见"), json!(7), json!([])] {
            let s3 = parse_share(&json!({"id": "sh-junk", "stateVisibility": junk})).unwrap();
            assert!(
                vis_of(&s3.state_visibility).is_all_visible(),
                "坏 stateVisibility → 全可见: {junk}"
            );
        }
    }

    // ═══════════════════════════════════════════════════════════════════
    // §3.22 可选项来源：服务端自动读 DSH 会话清单
    // （信封→options · label 兜底链 · 截断标记 · harness 不可用降级 · TTL 缓存）
    // ═══════════════════════════════════════════════════════════════════

    /// 造一行会话（单测用；默认非空白、非子会话）。
    fn srow(id: &str, cwd: &str, title: &str, updated_at: i64) -> SessionRow {
        SessionRow {
            session_id: id.to_string(),
            cwd: cwd.to_string(),
            title: title.to_string(),
            updated_at,
            blank: false,
            subagent: false,
            parent_session_id: None,
        }
    }

    /// --task 多可见会话目标定位（2026-10-14 跨设备投递）：本地注册表绑定优先、
    /// 源侧 grant 随票回传的绑定兜底；裸 uuid 与 session- 前缀等价；都没有=拒绝。
    #[test]
    fn pick_prompt_target_prefers_local_then_ticket() {
        let rows = vec![
            srow("session-11111111-0000-0000-0000-000000000001", "d", "a", 3),
            srow("22222222-0000-0000-0000-000000000002", "d", "b", 2),
        ];
        // ① 本地注册表优先
        assert_eq!(
            pick_prompt_target(&rows, Some("22222222-0000-0000-0000-000000000002"), None),
            Some("22222222-0000-0000-0000-000000000002".to_string())
        );
        // ② 本地没有 → 票面绑定；形态归一化（裸 uuid 认 session- 前缀行，反之亦然）
        assert_eq!(
            pick_prompt_target(
                &rows,
                None,
                Some("session-22222222-0000-0000-0000-000000000002")
            ),
            Some("22222222-0000-0000-0000-000000000002".to_string())
        );
        assert_eq!(
            pick_prompt_target(&rows, None, Some("11111111-0000-0000-0000-000000000001")),
            Some("session-11111111-0000-0000-0000-000000000001".to_string())
        );
        // ③ 都没有 / 对不上清单 / 空串 → None（不猜目标）
        assert_eq!(pick_prompt_target(&rows, None, None), None);
        assert_eq!(pick_prompt_target(&rows, None, Some("deadbeef-nope")), None);
        assert_eq!(
            pick_prompt_target(&rows, Some("  "), Some("deadbeef-0000")),
            None
        );
    }

    /// 一份**实测形状**的 `session/list` 应答（2026-10-06 本机 harness `:19387` 真调）：
    /// 清单键是 `result.value.items`（**不是** ACP 类型名 `sessions`）、标题在
    /// `projections.values.title` 里、`updatedAt` 是 epoch **毫秒数字**。
    fn real_session_list_envelope() -> serde_json::Value {
        json!({
            "type": "server-response", "rpcId": "r1",
            "result": { "ok": true, "value": { "items": [
                { "sessionId": "3a70c0b0-b8c5-4eea-ac6c-4ba8bd01e185",
                  "updatedAt": 1_791_272_657_881i64, "agentAvailable": true, "running": true,
                  "blank": false, "parentSessionId": "session-parent", "origin": "subagent",
                  "cwd": "D:\\Projects\\labs\\myco",
                  "projections": { "kind": "sequenced", "asOfSeq": 506,
                                   "values": { "title": "子 agent 内部会话" } } },
                { "sessionId": "b2bf59cb-54ce-4030-aca5-67b1bf0be3e7",
                  "updatedAt": 1_791_272_642_128i64, "agentAvailable": true, "running": true,
                  "blank": false, "cwd": "D:\\Projects\\labs\\myco",
                  "projections": { "values": { "title": "把分享范围配成自动读清单" } } },
                { "sessionId": "aaaaaaaa-0000-0000-0000-000000000000",
                  "updatedAt": 1_791_200_000_000i64, "agentAvailable": true, "running": false,
                  "blank": false, "cwd": "D:\\Projects\\labs\\repo-a\\youling-myco",
                  "projections": { "values": { "title": null } } },
                { "sessionId": "bbbbbbbb-0000-0000-0000-000000000000",
                  "updatedAt": 1_791_100_000_000i64, "agentAvailable": true, "running": false,
                  "blank": true, "cwd": "D:\\Projects\\labs\\myco",
                  "projections": { "values": { "title": null } } },
                { "sessionId": "cccccccc-1111-2222-3333-444455556666",
                  "updatedAt": 1_791_050_000_000i64, "agentAvailable": true, "running": false,
                  "blank": false,
                  "projections": { "values": { "title": null } } },
            ]}},
        })
    }

    /// **信封 → options**：认实测形状（`items` + projections 里的 title + 数字 updatedAt），
    /// 也认 ACP 类型名 `sessions[]` 与字符串时间（跟版风险隔离）；子 agent 与空白会话
    /// **不进可选清单**（会淹掉真正的会话），但**计数上报**，不静默丢。
    #[test]
    fn session_options_parse_real_envelope() {
        let rows = parse_session_list(&real_session_list_envelope()).expect("实测应答应能解析");
        assert_eq!(rows.len(), 5, "解析层不丢行（过滤是加工层的事）");
        let view = process_session_list(rows, SESSION_OPTIONS_MAX);
        assert_eq!(
            view.total, 5,
            "total = harness 原始条数（truncated 的分母）"
        );
        assert_eq!(view.skipped_subagent, 1, "origin=subagent 不进可选清单");
        assert_eq!(view.skipped_blank, 1, "blank 不进可选清单");
        assert_eq!(view.sessions.len(), 3);
        assert!(!view.truncated());
        // 按 updatedAt 倒序（最近的在前）
        assert_eq!(
            view.sessions[0].value,
            "b2bf59cb-54ce-4030-aca5-67b1bf0be3e7"
        );
        assert_eq!(
            view.sessions[0].label, "把分享范围配成自动读清单",
            "title 优先"
        );
        assert_eq!(
            view.sessions[1].label, "youling-myco",
            "无 title → cwd 末段目录名"
        );
        assert_eq!(
            view.sessions[2].label, "55556666",
            "无 title 无 cwd → 会话编号尾 8 位"
        );
        // 工作区清单从会话 cwd 派生（去重保序，最近的在前；没 cwd 的行不参与）
        let dirs: Vec<&str> = view.workspaces.iter().map(|w| w.label.as_str()).collect();
        assert_eq!(dirs, vec!["myco", "youling-myco"]);
        // option 的 JSON 形状 = value/label/cwd 三键（2026-10-24 起 cwd 随 option 带出——
        // 授权面板「指定会话先按已选项目筛」的契约，与顶层 sessionCwds 同源同值）
        let o = view.sessions[0].to_json();
        assert_eq!(o["value"], json!("b2bf59cb-54ce-4030-aca5-67b1bf0be3e7"));
        assert_eq!(o["label"], json!("把分享范围配成自动读清单"));
        assert_eq!(o["cwd"], json!("D:\\Projects\\labs\\myco"));
        assert_eq!(
            o.as_object().unwrap().len(),
            3,
            "option 恰好 value/label/cwd 三个键"
        );
        // 兼容面：ACP 类型名 `sessions[]` + 顶层 title + RFC3339 字符串时间
        let acp = json!({"type":"server-response","rpcId":"r2","result":{"ok":true,"value":{
            "sessions":[{"sessionId":"s-acp","cwd":"/home/j/myco","title":"ACP 形状",
                         "updatedAt":"2026-10-06T15:44:02+08:00"}],
            "nextCursor":null}}});
        let rows2 = parse_session_list(&acp).expect("ACP 形状也要认");
        assert_eq!(rows2.len(), 1);
        assert_eq!(rows2[0].title, "ACP 形状");
        assert!(
            rows2[0].updated_at > 1_700_000_000_000,
            "RFC3339 也要能比大小"
        );
        // rpc 失败信封 → Err（人话），由调用方降级；不是 panic
        let bad = json!({"type":"server-response","rpcId":"r3",
                         "result":{"ok":false,"error":{"code":"x","message":"session list unavailable"}}});
        let e = parse_session_list(&bad).unwrap_err();
        assert!(
            e.contains("session list unavailable"),
            "把 harness 的原因带出来: {e}"
        );
        // 形状不认识 → 空清单（**不报错**：没有会话不是错误）
        assert!(
            parse_session_list(&json!({"result":{"ok":true,"value":{"weird":1}}}))
                .unwrap()
                .is_empty()
        );
        assert!(parse_session_list(&json!("不是对象")).unwrap().is_empty());
    }

    /// label 兜底链（**纯函数**）：`title` → `cwd` 末段目录名 → `sessionId` 尾 8 位；
    /// 统一按**字符**（中文按字）裁到 ~40 字。
    #[test]
    fn session_label_fallback_chain() {
        assert_eq!(
            session_label("把分享范围配成自动读清单", "D:\\x", "sid-12345678"),
            "把分享范围配成自动读清单"
        );
        assert_eq!(
            session_label("   ", "D:\\Projects\\labs\\myco\\", "sid-12345678"),
            "myco",
            "空白 title → cwd 末段（末尾分隔符忽略）"
        );
        assert_eq!(
            session_label("", "/home/j/youling-myco", "sid-1"),
            "youling-myco",
            "Unix 路径同款"
        );
        assert_eq!(
            session_label("", "", "abc-12345678"),
            "12345678",
            "无 title 无 cwd → 尾 8 位"
        );
        assert_eq!(
            session_label("", "D:\\", "short"),
            "short",
            "盘根不算目录名 → 继续往下兜"
        );
        assert_eq!(session_label("", "", "short"), "short", "不足 8 位原样");
        // 超长**按字**截断（不是字节），补 `…`
        let long = "一".repeat(60);
        let got = session_label(&long, "", "s");
        assert_eq!(got.chars().count(), SESSION_LABEL_MAX);
        assert!(got.ends_with('…'));
        // 有 title 时不吃 cwd（title 是用户认得的那句话）
        assert_eq!(session_label("标题", "D:\\proj", "sid"), "标题");
        // 撞车才补尾 8 位（同一个项目里好几条没标题的会话要能分清）
        let mut list: Vec<SessionOption> = vec![
            SessionOption {
                value: "aaa-11111111".into(),
                label: "myco".into(),
                cwd: "D:\\p".into(),
                updated_at: 1,
            },
            SessionOption {
                value: "bbb-22222222".into(),
                label: "myco".into(),
                cwd: "D:\\p".into(),
                updated_at: 2,
            },
            SessionOption {
                value: "ccc-33333333".into(),
                label: "别人".into(),
                cwd: "D:\\q".into(),
                updated_at: 3,
            },
        ];
        disambiguate_labels(&mut list);
        assert_eq!(list[0].label, "myco · 11111111");
        assert_eq!(list[1].label, "myco · 22222222");
        assert_eq!(list[2].label, "别人", "没撞车的不动");
        assert!(list[0].label.chars().count() <= SESSION_LABEL_MAX);
        // 工作区清单：同一目录的两种写法只出一条（大小写不敏感），**目录名撞车**才补父级
        let rows = vec![
            srow("s1", "D:\\Projects\\labs\\myco", "一", 3),
            srow("s2", "d:\\projects\\labs\\MYCO", "二", 2), // 同一目录的另一种写法
            srow("s3", "D:\\Projects\\other\\myco", "三", 1),
            srow("s4", "D:\\Projects\\other\\weekly-report", "四", 0),
        ];
        let ws = workspaces_from_sessions(&rows);
        assert_eq!(ws.len(), 3, "大小写不同但同一目录 → 一条");
        assert_eq!(ws[0].cwd, "D:\\Projects\\labs\\myco");
        let labels: Vec<&str> = ws.iter().map(|w| w.label.as_str()).collect();
        assert_eq!(
            labels,
            vec!["labs/myco", "other/myco", "weekly-report"],
            "撞车的补父级，不撞的不动"
        );
        // 纯函数：父级取不到就退回末段
        assert_eq!(last_two_segments("D:\\myco").as_deref(), Some("myco"));
        assert_eq!(last_two_segments("/a/b/myco/").as_deref(), Some("b/myco"));
        assert_eq!(last_two_segments("D:\\").as_deref(), None);
    }

    /// 超上限 → **截断 + `truncated:true` 说明字段**（用户口径：别静默丢）。
    #[test]
    fn session_options_truncated_flag() {
        let rows: Vec<SessionRow> = (0..SESSION_OPTIONS_MAX + 10)
            .map(|i| {
                srow(
                    &format!("session-{i:03}"),
                    "D:\\p",
                    &format!("会话 {i:03}"),
                    1_791_000_000_000 + i as i64 * 1000,
                )
            })
            .collect();
        let view = process_session_list(rows, SESSION_OPTIONS_MAX);
        assert_eq!(view.total, SESSION_OPTIONS_MAX + 10);
        assert_eq!(view.sessions.len(), SESSION_OPTIONS_MAX);
        assert!(view.truncated(), "超限必须带标记");
        assert_eq!(view.dropped, 10);
        assert_eq!(
            view.sessions[0].value,
            format!("session-{:03}", SESSION_OPTIONS_MAX + 9),
            "最近的在最前"
        );
        assert_eq!(
            view.sessions[SESSION_OPTIONS_MAX - 1].value,
            "session-010",
            "裁掉最旧的 10 条"
        );
        let s = view.summary();
        assert_eq!(s["truncated"], json!(true), "说明字段在返回里");
        assert_eq!(s["count"], json!(SESSION_OPTIONS_MAX));
        assert_eq!(s["total"], json!(SESSION_OPTIONS_MAX + 10));
        // 未超限 → **不带** truncated（免得界面无谓提示）
        let view2 = process_session_list(vec![srow("s1", "D:\\p", "一条", 1)], SESSION_OPTIONS_MAX);
        assert!(!view2.truncated());
        assert_eq!(view2.summary()["truncated"], json!(false));
        // 上限 0 也要退化得干净（不 panic）
        let view0 = process_session_list(vec![srow("s1", "D:\\p", "一条", 1)], 0);
        assert!(view0.sessions.is_empty() && view0.truncated() && view0.dropped == 1);
    }

    /// **harness 不可用 → options 空 + 一句人话，绝不报错**（本特性的安全底线）：
    /// ① 取数层降级；② 贴进 schema 后 `options` 是**存在但空**的数组（界面据此退化
    /// 为手填输入框）+ `optionsError`；③ 骨架（id/kind/source/default）一个不动。
    #[tokio::test]
    async fn session_options_degrade_when_harness_down() {
        let _g = test_isolated_config_dir();
        clear_session_options_cache();
        let view = session_options_cached(now_ms(), || async {
            Err("本机 DSH 没在运行——打开 DSH 桌面版后这里会自动出清单".to_string())
        })
        .await;
        assert!(view.sessions.is_empty(), "读不到 → 清单空");
        assert!(view.workspaces.is_empty());
        assert!(!view.truncated());
        assert_eq!(
            view.error.as_deref(),
            Some("本机 DSH 没在运行——打开 DSH 桌面版后这里会自动出清单"),
            "原因必须是人话，供界面提示"
        );
        // ② 贴 schema（纯函数，不碰网络）
        let mut schema = visibility_schema();
        apply_options_to_schema(&mut schema, "D:\\Projects\\labs\\myco", &view);
        let items = schema["items"].as_array().unwrap();
        assert_eq!(
            items.len(),
            5,
            "骨架项数不变（3 既有 + 2 能力面，§3.22 第 4 步）"
        );
        let sess = items.iter().find(|i| i["id"] == json!("sessions")).unwrap();
        assert_eq!(
            sess["options"],
            json!([]),
            "options 存在但为空（界面退化为手填）"
        );
        assert!(
            sess["optionsError"].as_str().unwrap().contains("DSH"),
            "带一句人话原因"
        );
        assert!(sess.get("truncated").is_none(), "没截断就不带这个键");
        assert_eq!(sess["kind"], json!("multi"), "界面依赖的骨架不动");
        assert_eq!(sess["source"], json!("sessions"));
        assert_eq!(sess["default"], json!([]));
        assert_eq!(sess["dependsOn"], json!({"space": "session"}));
        // 工作区派生信息也照带（空清单 = 空数组，不 panic）
        assert_eq!(schema["workspaces"]["items"], json!([]));
        // ③ 端到端：**harness 打不通时 `share_visibility` 仍必须成功**（把端口指到
        //    一个绝不会有人听的号，走真实 `fetch_dsh_session_list` 的降级路径）
        clear_session_options_cache();
        let old = std::env::var("DSH_NATIVE_PORT").ok();
        std::env::set_var("DSH_NATIVE_PORT", "1");
        let sh = shares();
        let share_id = format!("sh-sess-degrade-{:x}", now_ms());
        {
            let mut list = sh.shares.lock().unwrap();
            list.push(Share {
                id: share_id.clone(),
                title: "清单降级用例".into(),
                env: Vec::new(),
                granularity: "session".into(),
                cwd: "D:\\Projects\\labs\\myco".into(),
                session_id: Some("s1".into()),
                created_at: now_ms(),
                home_key: share_id.clone(),
                grants: vec![Grant {
                    label: "owner".into(),
                    did: None,
                    ro: false,
                    exp: now_ms() + 3_600_000,
                    window_ms: None,
                    caps: None,
                    visibility: None,
                }],
                caps: default_caps(),
                listing: "private".into(),
                state_visibility: visibility_default(),
                task_card: None,
                state: ST_ACTIVE.into(),
                group_id: None,
                owner_account: None,
                admin_device: None,
                device_policies: Vec::new(),
                policy_version: 0,
            });
        }
        let got = share_visibility_impl(&share_id)
            .await
            .expect("取不到清单**绝不能**让读命令失败");
        match old {
            Some(v) => std::env::set_var("DSH_NATIVE_PORT", v),
            None => std::env::remove_var("DSH_NATIVE_PORT"),
        }
        clear_session_options_cache();
        assert_eq!(got["ok"], json!(true));
        // 2026-10-24 起 current 带能力面 id 投影（capsO/capsA，见 share_visibility_impl）——
        // 剥掉再与缺省比（同 visibility_read_write 形状测试的做法；task-33 顺手修这个
        // 在 HEAD 就红的老断言——与协议修复无关，纯测试欠账）。
        let mut cur = got["current"].clone();
        if let Some(o) = cur.as_object_mut() {
            o.remove("capsO");
            o.remove("capsA");
        }
        assert_eq!(cur, visibility_default(), "配置照读");
        assert_eq!(got["allVisible"], json!(true));
        let its = got["schema"]["items"].as_array().unwrap();
        let s2 = its.iter().find(|i| i["id"] == json!("sessions")).unwrap();
        // task-33：`DSH_NATIVE_PORT=1` 的「harness down」模拟会被 native_port() 的
        // **自动端口探测**击穿（探测到本机真实 DSH 就回落真端口——产品特性，vnet 线
        // 加的）。带 DSH 桌面版的开发机上这条降级断言必然失败（与本协议修复无关的
        // 环境耦合欠账）：探测生效（拿到真清单）时只验「不失败」，探测不到时才验
        // 完整降级形状。
        let err = s2["optionsError"].as_str().unwrap_or_default();
        if err.is_empty()
            && !s2["options"]
                .as_array()
                .map(|a| a.is_empty())
                .unwrap_or(true)
        {
            eprintln!("[test] 本机 DSH 在跑（native_port 自动探测生效）——降级断言跳过，仅验不失败");
            return;
        }
        assert_eq!(
            s2["options"],
            json!([]),
            "读不到 → 空清单（前端自动退化成手填）"
        );
        assert!(err.contains("DSH"), "带人话原因给界面提示: {err}");
        assert_eq!(got["sessionsOptions"]["count"], json!(0));
        assert_eq!(got["sessionsOptions"]["truncated"], json!(false));
        assert!(got["sessionsOptions"]["error"].is_string());
        // project 选项的 label 仍然补上项目名（清单读不到也不影响这条）
        let space = its.iter().find(|i| i["id"] == json!("space")).unwrap();
        let proj = space["options"]
            .as_array()
            .unwrap()
            .iter()
            .find(|o| o["value"] == json!("project"))
            .unwrap();
        assert_eq!(proj["label"], json!("只这一个项目（myco）"));
        assert_eq!(
            proj["value"],
            json!("project"),
            "value 绝不动（写回后端的取值）"
        );
    }

    /// 2026-10-17 真案回归锚（跨会话消息全线 400 的根因）：
    /// session/list 应答实测 11.8 MB / 约 4 秒；超时若回到 2 秒，会把它读成
    /// 「error decoding response body」→ 被当成"应答不是 JSON" → 依赖清单的命令
    /// （session_send 名字解析 / session_list）全部 400，别的会话看到的是"通道故障"。
    #[test]
    fn session_list_timeout_covers_heavy_payload() {
        assert!(
            SESSION_LIST_TIMEOUT_MS >= 10_000,
            "session/list 实测 11.8MB/4s——超时低于 10s 会把慢应答误判成格式错误"
        );
        assert!(
            SESSION_LIST_TTL_MS >= 10_000,
            "这份重活必须缓存住：TTL 太短等于每次面板轮询都重打一次 11.8MB"
        );
    }

    /// 2026-10-17 真案：DSH 按 UTF-16 码元截断 emoji 预览，留下**孤立代理转义**
    /// （`\uD83D` 没有后半）→ 整份 11.8MB JSON 对 serde 非法 → 清单读不到 →
    /// 跨会话消息全 400。修补必须：只动真转义、同长度、修完可解析。
    #[test]
    fn repair_lone_surrogates_cases() {
        // 干净（成对代理 = 合法）：不动，零拷贝
        let ok = r#"{"t":"\uD83D\uDE00"}"#.as_bytes();
        assert!(repair_lone_surrogates(ok).is_none());
        // 孤立高代理（本机真实现场）：修完必须能解析，且换成 U+FFFD
        let lone_high = br#"{"t":"\uD83D"}"#;
        let fixed = repair_lone_surrogates(lone_high).expect("应当修");
        assert_eq!(fixed.len(), lone_high.len(), "同长度替换，不改变字节数");
        let v: serde_json::Value = serde_json::from_slice(&fixed).expect("修完必须可解析");
        assert_eq!(v["t"].as_str().unwrap(), "\u{FFFD}");
        // 孤立低代理同样修
        let lone_low = br#"{"t":"\uDC64"}"#;
        let fixed = repair_lone_surrogates(lone_low).expect("应当修");
        serde_json::from_slice::<serde_json::Value>(&fixed).expect("修完必须可解析");
        // 转义过的反斜杠是**文本**不是转义序列：不修
        let literal = br#"{"t":"\\uD83D"}"#;
        assert!(repair_lone_surrogates(literal).is_none());
        // 非 \u 转义（\n / \t）不受影响
        let plain = br#"{"t":"a\nb\tc"}"#;
        assert!(repair_lone_surrogates(plain).is_none());
    }

    /// TTL 缓存命中：TTL 内第二次调用**不再打 harness**；过 TTL 才重新取；
    /// **失败态同样进缓存**（harness 挂着时别让每个请求都撞一次超时）。
    #[tokio::test]
    async fn session_options_ttl_cache_hit() {
        let _g = test_isolated_config_dir();
        clear_session_options_cache();
        use std::sync::atomic::{AtomicUsize, Ordering::SeqCst};
        let calls = std::sync::Arc::new(AtomicUsize::new(0));
        let rows = || {
            vec![srow(
                "session-cache",
                "D:\\p",
                "缓存用例",
                1_791_000_000_000,
            )]
        };
        let t0 = now_ms();
        let c = calls.clone();
        let a = session_options_cached(t0, || {
            let c = c.clone();
            async move {
                c.fetch_add(1, SeqCst);
                Ok(rows())
            }
        })
        .await;
        assert_eq!(a.sessions.len(), 1);
        assert_eq!(calls.load(SeqCst), 1, "首次必须真取");
        // TTL 内 → 命中缓存（这个 fetcher 一旦被调用就会失败，命中即证明没调用）
        let c = calls.clone();
        let b = session_options_cached(t0 + SESSION_LIST_TTL_MS - 1, || {
            let c = c.clone();
            async move {
                c.fetch_add(1, SeqCst);
                Err("TTL 内不该再打 harness".to_string())
            }
        })
        .await;
        assert_eq!(calls.load(SeqCst), 1, "TTL 内必须命中缓存");
        assert_eq!(b.sessions.len(), 1);
        assert_eq!(b.error, None, "缓存的是成功态，不该被这次的失败污染");
        // 过 TTL → 重新取（这次失败，也要降级）
        let c = calls.clone();
        let d = session_options_cached(t0 + SESSION_LIST_TTL_MS, || {
            let c = c.clone();
            async move {
                c.fetch_add(1, SeqCst);
                Err("harness 挂了".to_string())
            }
        })
        .await;
        assert_eq!(calls.load(SeqCst), 2, "过 TTL 必须重新取");
        assert!(d.sessions.is_empty());
        assert_eq!(d.error.as_deref(), Some("harness 挂了"));
        // 失败态也在 TTL 内命中（否则 harness 挂着时读命令每次都白等 2s 超时）
        let c = calls.clone();
        let e = session_options_cached(t0 + SESSION_LIST_TTL_MS + 1, || {
            let c = c.clone();
            async move {
                c.fetch_add(1, SeqCst);
                Ok(rows())
            }
        })
        .await;
        assert_eq!(calls.load(SeqCst), 2, "失败态同样 TTL 内命中");
        assert_eq!(e.error.as_deref(), Some("harness 挂了"));
        clear_session_options_cache();
        // 纯判定：时钟回拨按"还新鲜"处理（读命令，宁可少打一次）
        assert!(
            cache_fresh(1000, 500, SESSION_LIST_TTL_MS),
            "回拨不乱打 harness"
        );
        assert!(cache_fresh(
            1000,
            1000 + SESSION_LIST_TTL_MS - 1,
            SESSION_LIST_TTL_MS
        ));
        assert!(!cache_fresh(
            1000,
            1000 + SESSION_LIST_TTL_MS,
            SESSION_LIST_TTL_MS
        ));
    }

    // ═══════════════════════════════════════════════════════════════════
    // §3.22 第 4 步：能力目录（caps 词表可发现）
    // （来源优先级 census>harness>default · observed 标记 · 降级人话 · TTL 缓存）
    // ═══════════════════════════════════════════════════════════════════

    /// 来源优先级：① 普查非空 → census（赢过给得出的方法表）；② 普查空 + 表给得出
    /// → harness；③ 都没有 → default + error 一句人话。observed 只标不改词表。
    #[tokio::test]
    async fn capability_catalog_source_priority_and_fallback() {
        let _g = test_isolated_config_dir();
        clear_rpc_census_for_test();
        clear_capability_catalog_cache();

        // ③ 兜底：普查空 + harness 探不通（Err 人话）→ default + error 原样带出
        let c = capability_catalog_cached(now_ms(), || async {
            Err("本机 DSH 没在运行——先按内置清单显示，打开 DSH 桌面版后这里会自动校准".to_string())
        })
        .await;
        assert_eq!(c.source, "default");
        assert_eq!(c.capabilities.len(), 4, "四个固定能力面恒在（词表不塌）");
        assert!(
            c.capabilities.iter().all(|f| !f.observed),
            "普查没参与就没有 observed"
        );
        assert_eq!(
            c.error.as_deref(),
            Some("本机 DSH 没在运行——先按内置清单显示，打开 DSH 桌面版后这里会自动校准"),
            "降级原因原样带出（人话）"
        );
        assert!(c.denied_faces.contains(&"terminal".to_string()));
        assert!(
            c.denied_faces.contains(&"files/".to_string()),
            "默认关名单原样（含前缀族）"
        );
        assert_eq!(c.observed_other, Vec::<String>::new());

        // ② harness 方法表（这版拿不到；注入模拟"未来的 dsh 给了表"）→ source:"harness"
        clear_capability_catalog_cache();
        let c2 = capability_catalog_cached(now_ms(), || async {
            Ok(vec![
                "session/page".into(),
                "session/list".into(),
                "session/prompt".into(),
                "subagent/list".into(),
                "session/activate".into(),
                "terminal/follow".into(),
            ])
        })
        .await;
        assert_eq!(c2.source, "harness");
        assert!(c2.error.is_none());
        let read2 = c2
            .capabilities
            .iter()
            .find(|f| f.id == "session.read")
            .unwrap();
        assert_eq!(
            read2.methods,
            vec!["session/page".to_string(), "session/list".to_string()],
            "表里有就留"
        );
        assert!(!read2.observed, "普查空 → observed 全 false");
        // 表里一条都对不上的能力**保留原方法**（词表不塌：目录是可勾面，不是存在性证明）
        clear_capability_catalog_cache();
        let c3 =
            capability_catalog_cached(now_ms(), || async { Ok(vec!["terminal/follow".into()]) })
                .await;
        assert_eq!(c3.source, "harness");
        assert_eq!(
            c3.capabilities
                .iter()
                .find(|f| f.id == "session.read")
                .unwrap()
                .methods
                .len(),
            2
        );

        // ① 普查非空 → census 赢过 harness（即便方法表也给得出）
        clear_capability_catalog_cache();
        rpc_census_touch("/api/session/page", &Method::POST);
        rpc_census_touch("/api/session/list", &Method::POST);
        rpc_census_touch("/api/session/prompt", &Method::POST);
        rpc_census_touch_mux("open", "session/follow"); // 未归属方法 → observedOther
        rpc_census_bump("MUX cancel".into()); // 无端点帧 → 不计
        let c4 = capability_catalog_cached(now_ms(), || async {
            Ok(vec!["session/page".into()]) // 故意给得出表——普查仍优先
        })
        .await;
        assert_eq!(c4.source, "census");
        assert!(c4.error.is_none());
        let obs = |id: &str| {
            c4.capabilities
                .iter()
                .find(|f| f.id == id)
                .unwrap()
                .observed
        };
        assert!(
            obs("session.read"),
            "page/list 都过了 → 看会话内容 observed"
        );
        assert!(obs("session.input"));
        assert!(!obs("agent.view"), "没见过 subagent/list");
        assert!(!obs("scope.switch"));
        assert_eq!(
            c4.observed_other,
            vec!["session/follow".to_string()],
            "普查见过但不在四面上 → 附加清单"
        );
        // 方法面**不被普查改写**（目录只标 observed，不改词表——caps 判定一字不动）
        assert_eq!(
            c4.capabilities
                .iter()
                .find(|f| f.id == "session.read")
                .unwrap()
                .methods,
            vec!["session/page".to_string(), "session/list".to_string()]
        );

        clear_rpc_census_for_test();
        clear_capability_catalog_cache();
    }

    /// 目录 TTL 缓存：5s 内第二次**不再探 harness**（fetcher 计数）；失败兜底态同样
    /// 进缓存（harness 挂着时别让每个请求都白探一次）。
    #[tokio::test]
    async fn capability_catalog_ttl_cache_hit() {
        let _g = test_isolated_config_dir();
        clear_rpc_census_for_test();
        clear_capability_catalog_cache();
        use std::sync::atomic::{AtomicUsize, Ordering::SeqCst};
        let calls = std::sync::Arc::new(AtomicUsize::new(0));
        let t0 = now_ms();
        let c = calls.clone();
        let a = capability_catalog_cached(t0, || {
            let c = c.clone();
            async move {
                c.fetch_add(1, SeqCst);
                Err("harness 挂了".to_string())
            }
        })
        .await;
        assert_eq!(a.source, "default");
        assert_eq!(calls.load(SeqCst), 1, "首次必须真探");
        // TTL 内 → 命中缓存（这个 fetcher 一旦被调用就给得出表，命中即证明没调用）
        let c = calls.clone();
        let b = capability_catalog_cached(t0 + CAPABILITY_CATALOG_TTL_MS - 1, || {
            let c = c.clone();
            async move {
                c.fetch_add(1, SeqCst);
                Ok(vec!["session/page".into()])
            }
        })
        .await;
        assert_eq!(calls.load(SeqCst), 1, "TTL 内必须命中缓存");
        assert_eq!(
            b.source, "default",
            "缓存的是失败兜底态，不被这次的成功污染"
        );
        // 过 TTL → 重新探（这次拿到"表"，source 换到 harness）
        let c = calls.clone();
        let d = capability_catalog_cached(t0 + CAPABILITY_CATALOG_TTL_MS, || {
            let c = c.clone();
            async move {
                c.fetch_add(1, SeqCst);
                Ok(vec!["session/page".into()])
            }
        })
        .await;
        assert_eq!(calls.load(SeqCst), 2, "过 TTL 必须重新探");
        assert_eq!(d.source, "harness");
        clear_rpc_census_for_test();
        clear_capability_catalog_cache();
    }

    /// 目录贴进 schema（纯函数）+ 端到端降级（探不通 → default，capsO/capsA 的
    /// options 仍不空）+ HTTP 面形状（直接调 handler，不起服务器）。
    #[tokio::test]
    async fn capability_catalog_schema_and_http_face() {
        let _g = test_isolated_config_dir();
        clear_rpc_census_for_test();
        clear_capability_catalog_cache();

        // ① census 目录贴 schema：capsO/capsA options 从目录来、顶层附加字段带 source/observed
        let catalog = build_capability_catalog(
            vec!["session/page".into(), "subagent/list".into()],
            Ok(vec![]),
        );
        assert_eq!(catalog.source, "census", "普查非空 → census（表空不参与）");
        let mut schema = visibility_schema();
        apply_capability_catalog_to_schema(&mut schema, &catalog);
        assert_eq!(schema["capabilityCatalog"]["source"], json!("census"));
        let caps = schema["capabilityCatalog"]["capabilities"]
            .as_array()
            .unwrap();
        assert_eq!(caps.len(), 4);
        let read = caps
            .iter()
            .find(|c| c["id"] == json!("session.read"))
            .unwrap();
        assert_eq!(read["observed"], json!(true), "普查见过 session/page");
        assert_eq!(
            read["methods"],
            json!(["session/page", "session/list"]),
            "方法面不被普查改写"
        );
        assert_eq!(read["direction"], json!("o"));
        let agent = caps
            .iter()
            .find(|c| c["id"] == json!("agent.view"))
            .unwrap();
        assert_eq!(agent["observed"], json!(true), "普查也见过 subagent/list");
        let co = schema["items"]
            .as_array()
            .unwrap()
            .iter()
            .find(|i| i["id"] == json!("capsO"))
            .unwrap();
        assert_eq!(
            co["options"].as_array().unwrap().len(),
            2,
            "O 面只列 o 向能力"
        );
        assert!(
            co["options"]
                .as_array()
                .unwrap()
                .iter()
                .all(|o| o.as_object().unwrap().len() == 2),
            "option 恰好 {{value,label}} 两键"
        );
        let ca = schema["items"]
            .as_array()
            .unwrap()
            .iter()
            .find(|i| i["id"] == json!("capsA"))
            .unwrap();
        assert_eq!(
            ca["options"].as_array().unwrap().len(),
            2,
            "A 面只列 a 向能力"
        );

        // ② 端到端降级：端口指到没人听的号 → share_visibility 仍成功、目录走 default
        clear_capability_catalog_cache();
        clear_session_options_cache();
        let old = std::env::var("DSH_NATIVE_PORT").ok();
        std::env::set_var("DSH_NATIVE_PORT", "1");
        let sh = shares();
        let share_id = format!("sh-cat-degrade-{:x}", now_ms());
        {
            let mut list = sh.shares.lock().unwrap();
            list.push(Share {
                id: share_id.clone(),
                title: "能力目录降级用例".into(),
                env: Vec::new(),
                granularity: "session".into(),
                cwd: "D:\\Projects\\labs\\myco".into(),
                session_id: Some("s1".into()),
                created_at: now_ms(),
                home_key: share_id.clone(),
                grants: vec![Grant {
                    label: "owner".into(),
                    did: None,
                    ro: false,
                    exp: now_ms() + 3_600_000,
                    window_ms: None,
                    caps: None,
                    visibility: None,
                }],
                caps: default_caps(),
                listing: "private".into(),
                state_visibility: visibility_default(),
                task_card: None,
                state: ST_ACTIVE.into(),
                group_id: None,
                owner_account: None,
                admin_device: None,
                device_policies: Vec::new(),
                policy_version: 0,
            });
        }
        let got = share_visibility_impl(&share_id)
            .await
            .expect("拿不到目录**绝不能**让读命令失败");
        // HTTP 面（同一份取法/缓存；直接调 handler，不起服务器）
        let resp = handle_capability_catalog(RawQuery(None)).await;
        let bytes = axum::body::to_bytes(resp.into_body(), 4 * 1024 * 1024)
            .await
            .unwrap_or_default();
        let body: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or(json!(null));
        match old {
            Some(v) => std::env::set_var("DSH_NATIVE_PORT", v),
            None => std::env::remove_var("DSH_NATIVE_PORT"),
        }
        assert_eq!(got["ok"], json!(true));
        assert_eq!(
            got["schema"]["capabilityCatalog"]["source"],
            json!("default"),
            "普查空+探不通 → default"
        );
        assert!(
            got["schema"]["capabilityCatalog"]["error"]
                .as_str()
                .unwrap_or("")
                .contains("DSH"),
            "一句人话"
        );
        let co2 = got["schema"]["items"]
            .as_array()
            .unwrap()
            .iter()
            .find(|i| i["id"] == json!("capsO"))
            .unwrap();
        assert_eq!(
            co2["options"].as_array().unwrap().len(),
            2,
            "降级时 options 退化为骨架默认词表（不空）"
        );
        // HTTP 面形状：ok/source/capabilities(四项)/deniedFaces/error/shareId
        assert_eq!(body["ok"], json!(true));
        assert_eq!(body["source"], json!("default"));
        assert_eq!(
            body["shareId"],
            json!(null),
            "shareId 可省（省了 = null，不是缺失）"
        );
        let ids: Vec<serde_json::Value> = body["capabilities"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| c["id"].clone())
            .collect();
        assert_eq!(
            ids,
            vec![
                json!("session.read"),
                json!("session.input"),
                json!("agent.view"),
                json!("scope.switch")
            ]
        );
        assert!(
            body["capabilities"]
                .as_array()
                .unwrap()
                .iter()
                .all(|c| c["observed"] == json!(false)),
            "default 档 observed 全 false"
        );
        assert!(!body["deniedFaces"].as_array().unwrap().is_empty());
        assert!(
            body["error"].as_str().unwrap_or("").contains("DSH"),
            "降级人话原样上 HTTP 面"
        );
        // shareId 给了但不存在 → 唯一的有体失败（沿用 sessions 端点口径）
        let resp2 = handle_capability_catalog(RawQuery(Some("shareId=sh-cat-不存在".into()))).await;
        let bytes2 = axum::body::to_bytes(resp2.into_body(), 1024 * 1024)
            .await
            .unwrap_or_default();
        let body2: serde_json::Value = serde_json::from_slice(&bytes2).unwrap_or(json!(null));
        assert_eq!(body2["ok"], json!(false));
        assert!(body2["error"].as_str().unwrap_or("").contains("分享不存在"));

        clear_rpc_census_for_test();
        clear_capability_catalog_cache();
        clear_session_options_cache();
    }

    /// **实机探针**（`--ignored`，默认不跑）：真探本机 harness，把目录与 HTTP 面的
    /// 应答打出来供人工核对（要 DSH 桌面版在跑）。**只读**：端口探活 + 自签 cookie
    /// （不发送）、普查账本只读；不写任何东西、不改状态。
    /// ```text
    /// cargo test -p myco-home --lib capability_catalog_live_probe -- --ignored --nocapture
    /// ```
    #[tokio::test]
    #[ignore = "需要本机 DSH 在跑（实机探针，默认不跑）"]
    async fn capability_catalog_live_probe() {
        let _g = test_isolated_config_dir(); // 审计流水落 target/，不写用户真实配置目录
        clear_rpc_census_for_test();
        clear_capability_catalog_cache();
        // (a) 冷启动形态：新进程普查是空的 → 看探活结果落到 harness 档还是 default 档
        let c = read_capability_catalog().await;
        println!(
            "[live] source={} error={:?} capabilities={} deniedFaces={} observedOther={:?}",
            c.source,
            c.error,
            c.capabilities.len(),
            c.denied_faces.len(),
            c.observed_other
        );
        for f in &c.capabilities {
            println!(
                "[live] {:<14} dir={} observed={:<5} methods={:?}",
                f.id, f.direction, f.observed, f.methods
            );
        }
        // (b) 跑过一段分享后的形态：普查里记几笔真实负载（SPA 装载面 + mux 流面）
        clear_capability_catalog_cache();
        rpc_census_touch("/api/session/list", &Method::POST);
        rpc_census_touch("/api/session/page", &Method::POST);
        rpc_census_touch("/api/session/prompt", &Method::POST);
        rpc_census_touch_mux("open", "session/follow");
        let c2 = read_capability_catalog().await;
        println!(
            "[live] with-census source={} observedOther={:?}",
            c2.source, c2.observed_other
        );
        for f in &c2.capabilities {
            println!("[live] {:<14} observed={}", f.id, f.observed);
        }
        // HTTP 面：把 `local_router` 真挂到临时端口发一次（验路由注册 + 线上 JSON 形状）
        if let Ok(listener) = tokio::net::TcpListener::bind("127.0.0.1:0").await {
            let port = listener.local_addr().map(|a| a.port()).unwrap_or(0);
            let server = tokio::spawn(async move {
                let _ = axum::serve(listener, local_router::<()>()).await;
            });
            if let Ok(r) = reqwest::Client::builder()
                .no_proxy()
                .timeout(Duration::from_secs(5))
                .build()
                .unwrap()
                .get(format!(
                    "http://127.0.0.1:{port}/api/dshShare/capabilityCatalog"
                ))
                .send()
                .await
            {
                let status = r.status();
                let txt = r.text().await.unwrap_or_default();
                println!("[live] HTTP :{port} GET /api/dshShare/capabilityCatalog -> {status}");
                println!("[live] HTTP body={txt}");
            }
            server.abort();
        }
        clear_rpc_census_for_test();
        clear_capability_catalog_cache();
        // 本机 harness 应当在跑：探活要么给 harness/default(在跑没表)，不该是"没在运行"
        assert_ne!(
            c.error.as_deref(),
            Some("本机 DSH 没在运行——先按内置清单显示，打开 DSH 桌面版后这里会自动校准")
        );
        assert_eq!(c.capabilities.len(), 4, "四项词表恒在");
        assert_eq!(c2.source, "census", "普查非空必须赢");
    }

