    /// 命令面端到端（读 → 写任务级 → 写逐人 → 生效取交）；**失败一律 Err**。
    /// 存储隔离：真建分享记录（走 `shares()` + `save_registry` 落盘），同既有用例纪律。
    #[tokio::test]
    async fn share_visibility_commands_roundtrip() {
        let _g = test_isolated_config_dir();
        let sh = shares();
        let share_id = format!("sh-vis-{:x}", now_ms());
        let friend = "did:youling:vis-friend";
        {
            let mut list = sh.shares.lock().unwrap();
            list.push(Share {
                id: share_id.clone(),
                title: "可见性用例".into(),
                env: Vec::new(),
                granularity: "session".into(),
                cwd: String::new(),
                session_id: Some("s1".into()),
                created_at: now_ms(),
                home_key: share_id.clone(),
                grants: vec![
                    Grant {
                        label: "owner".into(),
                        did: None,
                        ro: false,
                        exp: now_ms() + 3_600_000,
                        window_ms: None,
                        caps: None,
                        visibility: None,
                    },
                    Grant {
                        label: "小王".into(),
                        did: Some(friend.into()),
                        ro: true,
                        exp: now_ms() + 3_600_000,
                        window_ms: None,
                        caps: None,
                        visibility: None,
                    },
                ],
                caps: default_caps(),
                listing: "private".into(),
                state_visibility: visibility_default(),
                task_card: None,
                state: ST_ACTIVE.into(),
                group_id: None,
                owner_account: None,
                admin_device: None,
                device_policies: Vec::new(),
                policy_version: 0,
            });
        }
        // ① 读：默认全可见 + schema 三项 + 逐人列表（未配置 = null）
        let got = share_visibility_impl(&share_id).await.expect("读必须成功");
        assert_eq!(got["ok"], json!(true));
        // 2026-10-24：current 带能力面 id 投影（capsO/capsA）——剥掉再与缺省比
        {
            let mut cur = got["current"].clone();
            if let Some(o) = cur.as_object_mut() {
                o.remove("capsO");
                o.remove("capsA");
            }
            assert_eq!(cur, visibility_default(), "缺省 = 全可见");
        }
        assert_eq!(
            got["current"]["capsO"],
            json!(["session.read"]),
            "能力面回显（能看什么）"
        );
        assert_eq!(got["allVisible"], json!(true), "缺省 = 未收窄");
        assert_eq!(
            got["schema"]["items"].as_array().unwrap().len(),
            5,
            "3 既有 + 2 能力面（§3.22 第 4 步）"
        );
        let cols = got["grants"].as_array().unwrap();
        assert_eq!(cols.len(), 1, "只列协作者（owner 行不列）");
        assert_eq!(cols[0]["did"], json!(friend));
        assert_eq!(cols[0]["visibility"], json!(null));
        assert!(cols[0]["effective"]["sessions"]
            .as_array()
            .unwrap()
            .is_empty());
        // ② 写任务级：session + 白名单 + 6h
        let set = share_set_visibility_impl(
            &share_id,
            None,
            &json!({"space":"session","sessions":["s1"],"windowMs":21600000}),
        )
        .await
        .expect("写必须成功");
        // 2026-10-24：写返回体与读端同形（带 capsO/capsA 投影）——剥掉再比可见范围
        let mut set_cur = set["current"].clone();
        if let Some(o) = set_cur.as_object_mut() {
            o.remove("capsO");
            o.remove("capsA");
        }
        assert_eq!(
            set_cur,
            json!({"space":"session","sessions":["s1"],"windowMs":21600000})
        );
        // 能力面投影必须出现在返回体里（面板保存后重置草稿不回退）
        assert_eq!(set["current"]["capsO"], json!(["session.read"]));
        assert_eq!(
            share_visibility_impl(&share_id).await.unwrap()["current"],
            set["current"],
            "落盘读回"
        );
        assert_eq!(
            share_visibility_impl(&share_id).await.unwrap()["allVisible"],
            json!(false),
            "已收窄"
        );
        // ③ 写逐人：只能收紧（与任务级取交）
        let set2 = share_set_visibility_impl(
            &share_id,
            None,
            &json!({"space":"session","sessions":["s1","s2"],"did": friend}),
        )
        .await
        .expect("逐人写必须成功");
        assert_eq!(set2["did"], json!(friend));
        assert_eq!(
            set2["current"]["sessions"],
            json!(["s1", "s2"]),
            "current = 归一化后的逐人值"
        );
        assert_eq!(
            set2["effective"]["sessions"],
            json!(["s1"]),
            "生效 = 与任务级取交（收紧）"
        );
        assert_eq!(
            set2["effective"]["windowMs"],
            json!(21600000),
            "时间窗继承任务级"
        );
        // ④ 失败一律 Err（UI 只 catch reject）
        assert!(
            share_set_visibility_impl("sh-不存在", None, &visibility_default())
                .await
                .is_err()
        );
        assert!(
            share_set_visibility_impl(&share_id, None, &json!({"space": "all"}))
                .await
                .is_err()
        );
        assert!(share_set_visibility_impl(&share_id, None, &json!("全可见"))
            .await
            .is_err());
        assert!(
            share_set_visibility_impl(
                &share_id,
                None,
                &json!({"space":"session","did":"did:youling:nobody"}),
            )
            .await
            .is_err(),
            "did 不在授权列表 → Err"
        );
        assert!(
            share_visibility_impl("sh-不存在").await.is_err(),
            "分享不存在 → Err"
        );
        // ⑤ 写入后：该协作者的 session/page 白名单判定立刻生效（无缓存）
        let vis = {
            let list = sh.shares.lock().unwrap();
            let s = list.iter().find(|s| s.id == share_id).unwrap();
            effective_visibility(
                s,
                s.grants.iter().find(|g| g.did.as_deref() == Some(friend)),
            )
        };
        assert!(vis.allows_session("s1"));
        assert!(!vis.allows_session("s2"), "逐人收紧后 s2 不可见");
    }

    /// §3.20 命令②·「跟随整体」清除通道（2026-10-06 第四轮，与 UI 侧钉死的契约）：
    /// `{shareId, did, "visibility": null}` → 清除该人所有设备行的逐人覆盖，
    /// 返回 `{ok:true, current:null, did, effective:该人生效值(=任务级)}`。
    /// 幂等 / 缺键≠null / 无 did 的 null 报错 / owner 拒 / 回落任务级，逐条钉死。
    #[tokio::test]
    async fn share_set_visibility_null_clears_grant_override() {
        let _g = test_isolated_config_dir();
        let sh = shares();
        let share_id = format!("sh-vis-clear-{:x}", now_ms());
        let friend = "did:youling:vis-clear-friend";
        {
            let mut list = sh.shares.lock().unwrap();
            list.push(Share {
                id: share_id.clone(),
                title: "清除通道用例".into(),
                env: Vec::new(),
                granularity: "session".into(),
                cwd: String::new(),
                session_id: Some("s1".into()),
                created_at: now_ms(),
                home_key: share_id.clone(),
                grants: vec![
                    Grant {
                        label: "owner".into(),
                        did: None,
                        ro: false,
                        exp: now_ms() + 3_600_000,
                        window_ms: None,
                        caps: None,
                        visibility: None,
                    },
                    Grant {
                        label: "小王".into(),
                        did: Some(friend.into()),
                        ro: true,
                        exp: now_ms() + 3_600_000,
                        window_ms: None,
                        caps: None,
                        visibility: None,
                    },
                ],
                caps: default_caps(),
                listing: "private".into(),
                state_visibility: visibility_default(),
                task_card: None,
                state: ST_ACTIVE.into(),
                group_id: None,
                owner_account: None,
                admin_device: None,
                device_policies: Vec::new(),
                policy_version: 0,
            });
        }
        // 前置：任务级收窄 s1+6h；逐人覆盖写 s1+s2（effective=任务级∩逐人=s1）
        share_set_visibility_impl(
            &share_id,
            None,
            &json!({"space":"session","sessions":["s1"],"windowMs":21600000}),
        )
        .await
        .expect("写任务级必须成功");
        share_set_visibility_impl(
            &share_id,
            None,
            &json!({"space":"session","sessions":["s1","s2"],"did": friend}),
        )
        .await
        .expect("逐人写必须成功");
        // ① null + did → 清除：current:null，effective 回落任务级
        let cleared = share_set_visibility_impl(&share_id, Some(friend), &serde_json::Value::Null)
            .await
            .expect("清除必须成功");
        assert_eq!(cleared["ok"], json!(true));
        assert_eq!(
            cleared["current"],
            json!(null),
            "契约：清除后 current = null"
        );
        assert_eq!(cleared["did"], json!(friend));
        assert_eq!(cleared["effective"]["space"], json!("session"));
        assert_eq!(
            cleared["effective"]["sessions"],
            json!(["s1"]),
            "生效回落任务级"
        );
        assert_eq!(cleared["effective"]["windowMs"], json!(21600000));
        // 回读：存储值真是 None（不是"写最宽的一份"模拟）
        let stored_none = {
            let list = sh.shares.lock().unwrap();
            list.iter()
                .find(|s| s.id == share_id)
                .unwrap()
                .grants
                .iter()
                .filter(|g| g.did.as_deref() == Some(friend))
                .all(|g| g.visibility.is_none())
        };
        assert!(stored_none, "该人所有设备行的 visibility 必须真是 None");
        // ② 幂等：本来就 None → 照样 ok（current 仍 null）
        let again = share_set_visibility_impl(&share_id, Some(friend), &serde_json::Value::Null)
            .await
            .expect("幂等清除必须照样 ok");
        assert_eq!(again["current"], json!(null));
        // ③ 无 did 的 null → Err（任务级没有「跟随」概念）
        assert!(
            share_set_visibility_impl(&share_id, None, &serde_json::Value::Null)
                .await
                .is_err(),
            "不带 did 的 null 必须报错"
        );
        // ④ did 不在授权列表 → Err（同既有口径）
        assert!(
            share_set_visibility_impl(
                &share_id,
                Some("did:youling:nobody"),
                &serde_json::Value::Null
            )
            .await
            .is_err(),
            "陌生 did 清除 → Err"
        );
        // ⑤ owner 拒（注入式：my=该 did → 本人/自有设备行都拒；grant_is_owner_of 同款纪律）
        {
            let mut list = sh.shares.lock().unwrap();
            let s = list.iter_mut().find(|s| s.id == share_id).unwrap();
            assert!(
                clear_grant_visibility_of(s, friend, friend).is_err(),
                "对 owner（本人）清除 → Err（分享者本人不受可见范围限制）"
            );
        }
        // ⑥ 清除后整体收窄会自动跟上来（语义验证：任务级再收窄到 s0，该人生效值跟着变）
        share_set_visibility_impl(
            &share_id,
            None,
            &json!({"space":"session","sessions":["s0"],"windowMs":3600000}),
        )
        .await
        .expect("任务级再收窄");
        let eff = {
            let list = sh.shares.lock().unwrap();
            let s = list.iter().find(|s| s.id == share_id).unwrap();
            vis_json(&effective_visibility(
                s,
                s.grants.iter().find(|g| g.did.as_deref() == Some(friend)),
            ))
        };
        assert_eq!(
            eff["sessions"],
            json!(["s0"]),
            "清除后生效值跟随任务级（不再滞留旧覆盖）"
        );
        assert_eq!(eff["windowMs"], json!(3600000));
    }

