    /// A3（RED）：TRIM_MEMO 只按文本哈希、无 vis 维度——同一份 baseline 文本，后到的
    /// 查看者 B 会直接拿走先到者 A 的裁剪结果（看到 A 的会话、丢掉自己的）。修复后
    /// memo 键含 vis 指纹，各裁各的。
    #[test]
    fn a3_trim_memo_does_not_cross_vis() {
        let mut projs = serde_json::Map::new();
        for (k, tag) in [("session-aaa", "a"), ("session-bbb", "b")] {
            projs.insert(
                k.to_string(),
                json!({"asOfSeq":1, "values":{"title": tag, "blob": "x".repeat(150_000)}}),
            );
        }
        let big = json!({"type":"item","streamId":"c1","value":{"type":"baseline",
            "value":{"projections": serde_json::Value::Object(projs)}}})
        .to_string();
        assert!(
            big.len() > 256 * 1024,
            "必须走 memo 路径（≥256KB）: {}",
            big.len()
        );
        let vis_a = vis_of(&json!({"space":"session","sessions":["session-aaa"]}));
        let vis_b = vis_of(&json!({"space":"session","sessions":["session-bbb"]}));
        let (out_a, ka, da) = mux_trim_session_control(&big, &vis_a);
        assert_eq!((ka, da), (1, 1), "A：留 1 裁 1");
        let (out_b, kb, db) = mux_trim_session_control(&big, &vis_b);
        assert_eq!((kb, db), (1, 1), "B：留 1 裁 1");
        assert!(
            out_a.contains("session-aaa") && !out_a.contains("session-bbb"),
            "A 只见 A"
        );
        assert!(
            out_b.contains("session-bbb") && !out_b.contains("session-aaa"),
            "B 只见 B——不得命中 A 的 memo（串台）: {}",
            out_b.chars().take(200).collect::<String>()
        );
    }

