    /// A6（RED）：`$events` 的 `api-session/added` emit 帧 args 带全机会话元数据
    /// （标题/cwd/父子关系，真机帧 debug JSON t=8.542）——旧代码对 events 流只处理
    /// ready 帧的 host.home，emit 帧原样直达收窄档查看者。修复后 args 按白名单裁。
    #[test]
    fn a6_events_emit_args_filtered_by_whitelist() {
        // streamId 必须与 open 登记的一致（mux_open_frame 固定用这个 id）
        let sid = "11111111-2222-3333-4444-555555555555";
        let emit = json!({"type":"item","streamId":sid,"value":{"type":"emit","event":"api-session/added","args":[
            {"sessionId":"session-keep","cwd":"D:\\k","projections":{"values":{"title":"留下"}}},
            {"sessionId":"964239d4-fef0-49d8-9c21-4dc195491992","cwd":"D:\\b","projections":{"values":{"title":"裸id-也留"}}},
            {"sessionId":"session-other","cwd":"D:\\o","projections":{"values":{"title":"裁掉"}}}]}}).to_string();
        let gate = Mutex::new(MuxGate::default());
        let (tx, _rx) = tokio::sync::mpsc::channel::<WsMsg>(4);
        let authz = mux_authz(
            default_caps(),
            vis_of(
                &json!({"space":"session","sessions":["session-keep","session-964239d4-fef0-49d8-9c21-4dc195491992"]}),
            ),
        );
        let open = mux_open_frame("$events", json!({"args": {}}));
        assert!(matches!(
            mux_gate_client_text(
                &open,
                MuxMode::Filter,
                &gate,
                &authz,
                "sh-a6",
                "小李·a1b2",
                &tx
            ),
            MuxOutcome::Forward(_)
        ));
        let out = mux_gate_server_text(
            &emit,
            MuxMode::Filter,
            &gate,
            &authz,
            &[],
            "sh-a6",
            "小李·a1b2",
            &vis_all(),
        );
        assert!(
            out.contains("留下") && out.contains("裸id-也留"),
            "白名单内（含裸 id 形态）保留: {out}"
        );
        assert!(
            !out.contains("session-other") && !out.contains("裁掉"),
            "白名单外的会话行必须摘除: {out}"
        );
    }

    /// A6-钉子：非 `api-session/*` 的 emit 事件不受白名单裁剪（只裁会话行事件，
