        /// ④ 白屏自愈看门狗（2026-10-12；2026-10-24 Phase 2 收进 D 规则 6）：
        /// **壳到了、SPA 没起来**时走 decideAction → A.reload_page。心跳只探
        /// `/gw/<id>/ping`（网关自己的路由，永远秒回）→ 它看不出这个毛病。
        #[test]
        fn bootstrap_reloads_when_spa_never_renders() {
            let s = bootstrap_share(None, visibility_default());
            let js = entry_bootstrap_script(&s, &owner_authz(vis_all())).expect("仍应注入");
            // 判据：blank() 三重护栏（__ModuleLoader__ / 有字 / 全局元素总数）都在
            assert!(js.contains("function blank()"), "{js}");
            assert!(
                js.contains("document.readyState!=='complete'"),
                "还在加载就不许打扰: {js}"
            );
            assert!(js.contains("location.reload()"), "{js}");
            // 上限 3 次：不许"白屏↔重载"死循环（统一计数在 A.reload_page）
            assert!(js.contains("if(n>=3) return;"), "{js}");
            // 白屏一枪也走 D（规则 6），不再有私有入口
            assert!(
                js.contains("runD(decideAction({blank:true,pingOk:null}),'boot')"),
                "{js}"
            );
            // 正则必须是 /\s+/（不是字面量反斜杠+s）——raw string 里写成 \\s 会静默失去空白语义
            assert!(js.contains(r".replace(/\s+/g,'')"), "{js}");
            assert!(
                !js.contains(r"\\s"),
                "多了一层反斜杠，正则就不是空白了: {js}"
            );
            // 两枪：20s / 45s（SPA 首屏 + 隧道里资产走完再判）
            assert!(js.contains("setTimeout(bootCheck,20000)"), "{js}");
            assert!(js.contains("setTimeout(bootCheck,45000)"), "{js}");
        }

        /// ③ `main` 档（没有具体会话）：只做窄屏展开，不预置任何选中。
        #[test]
        #[ignore = "pre-existing/unstable in source baseline, tracked internally"]
        fn bootstrap_main_granularity_only_nudges_sidebar() {
            let s = bootstrap_share(None, visibility_default());
            let js = entry_bootstrap_script(&s, &owner_authz(vis_all())).expect("仍应注入");
            assert!(!js.contains("localStorage.setItem(K"), "{js}");
            assert!(js.contains("1024"), "{js}");
        }

        /// ④ 注入位置：经典脚本必须在 `</body>` 之前（即早于 `<head>` 里 deferred 的
        /// module 脚本执行）——否则 DSH 已经读过 `dsh.sessions.current` 了。
        #[test]
        fn bootstrap_snippet_goes_before_body_end() {
            let html = "<html><head><script type=\"module\" src=\"./a.js\"></script></head><body><div id=root></div></body></html>";
            let out = inject_into_html(html, "<script data-myco-share-bootstrap=\"1\">x</script>");
            let pos_snip = out.find("data-myco-share-bootstrap").unwrap();
            let pos_body_end = out.find("</body>").unwrap();
            let pos_module = out.find("type=\"module\"").unwrap();
            assert!(pos_snip < pos_body_end, "必须插在 </body> 前: {out}");
            assert!(
                pos_module < pos_snip,
                "且必须晚于（文本上）head 里的 module 标签: {out}"
            );
            // 无 </body> 的畸形文档也不能丢注入（放到最前）
            let out2 = inject_into_html("just text", "SNIP");
            assert!(out2.starts_with("SNIP"), "{out2}");
        }

        // ── 连接状态指示器（2026-10-11 定稿设计）──

        /// 状态条片段必须逐字对上用户验收的设计：容器 id、localStorage 键、
        /// 三态图标颜色、三句 tooltip、ping 路径与 fragment 写入/摘除。
        #[test]
        fn conn_status_snippet_matches_accepted_design() {
            let s = conn_status_snippet("sh-ind1");
            // 容器与幂等标记
            assert!(s.contains(r#"id="myco-conn-status""#), "{s}");
            assert!(s.contains(r#"data-myco-conn-status="1""#), "{s}");
            // localStorage 键（tunnel_acquire 的模式经 302 fragment 交到这里）
            assert!(s.contains("'myco.connMode'"), "{s}");
            assert!(s.contains("mycoConn=(direct|relay)"), "{s}");
            assert!(
                s.contains("history.replaceState"),
                "读走模式后必须摘掉 fragment: {s}"
            );
            // 三态颜色（⚡ 绿闪电 / ☁️ 白云灰描边 / ❋ 灰旋转）
            assert!(s.contains("#1f9d55"), "{s}");
            assert!(s.contains("#ffffff") && s.contains("#b0b8c8"), "{s}");
            assert!(s.contains("#94a3b8") && s.contains("mcs-spin"), "{s}");
            // 三句 tooltip 逐字（文字全在 tooltip，页面无文字标签）
            assert!(
                s.contains("端到端直连（局域网/IPv6）数据不过任何服务器·加密开销可忽略"),
                "{s}"
            );
            assert!(
                s.contains("云端中转·加密转发·服务器看不到内容·有额外流量成本"),
                "{s}"
            );
            assert!(s.contains("正在建立连接…优先直连，不通自动切换云端"), "{s}");
            // 延迟：ping 本分享的网关路由（既有心跳端点，cookie 鉴权，204）
            assert!(
                s.contains("'/gw/'+'sh-ind1'+'/ping'"),
                "ping 路径要指向本分享: {s}"
            );
            // 2026-10-11 ②「连接中先行」（用户报"直接显示白云，连接过程中不显示连接中"）：
            // 一律先亮旋转的连接中 → 第一条 ping 通了才切真实模式（最短 600ms 让过渡看得见）
            // → 连续 3 次不通老实退回连接中。
            assert!(
                s.contains("var shown='connecting'"),
                "初始态必须是连接中: {s}"
            );
            assert!(s.contains("paint('connecting')"), "{s}");
            assert!(
                s.contains("MIN=600"),
                "连接中要有最短可见时长，否则一闪而过等于没有: {s}"
            );
            assert!(
                s.contains("if(fails>=3&&shown!=='connecting')paint('connecting')"),
                "{s}"
            );
            assert!(
                s.contains("setInterval(ping,10000)"),
                "延迟要持续刷新，断了也要能退回连接中: {s}"
            );
            // 经典脚本语法外壳与 bootstrap 同款（解析期执行，早于 deferred module）
            assert!(s.contains("(function(){"), "{s}");
            assert!(s.ends_with("})();</script>"), "{s}");
        }

        /// 2026-10-23 用户"秒级反复断连"根因回归锁：注入脚本**绝不许**再出现
        /// 「页面文字命中重新连接 → 关闭全部 WS」的放大器（旧版：关 WS → DSH 显示
        /// 重新连接中 → 文字再命中 → 再关 = 死循环）。看门狗必须先判 mux 真实状态、
        /// 只在 mux 已死且数据面 ping 通时触发 DSH 原生重连；任何会话正文出现
        /// "重新连接"字样都不许直接动作。
        #[test]
        fn conn_status_watchdog_never_closes_websockets() {
            let s = bootstrap_script("sh-wd1", None);
            // 放大器绝迹：注入脚本不许主动关任何 WS
            assert!(
                !s.contains("ws.close()"),
                "不许主动关 WS（会制造关→重连→关死循环）: {s}"
            );
            assert!(
                !s.contains("act:'close_mux'"),
                "2026-10-28 04:56 真案：OPEN mux 不许因 >30s 无消息被代理主动关闭: {s}"
            );
            assert!(
                !s.contains("act:\"close_mux\""),
                "决策动作不得返回 close_mux: {s}"
            );
            assert!(
                !s.contains("__mux.close()"),
                "注入脚本绝不能关闭 DSH mux: {s}"
            );
            assert!(
                s.contains("if(muxOk()) return null"),
                "mux OPEN 是权威状态；会话正文命中“重新连接”不得触发动作: {s}"
            );
            assert!(!s.contains("__visWs.forEach(function(ws)"), "{s}");
            // mux 真实状态跟踪 + 前置判断（mux OPEN → 什么都不做）
            assert!(
                s.contains("remote.mux"),
                "必须跟踪 mux WS 才能判断真实连接态: {s}"
            );
            assert!(s.contains("__mux.readyState===1"), "{s}");
            // 限速 2s，轮询 1s（旧版 400ms 且不判 mux）
            assert!(s.contains("__wdLast<2000"), "{s}");
            assert!(s.contains("__wdTick();"), "{s}");
            // 2026-10-27 23:07 真案：mux 死 + ping 通时，点 DSH 原生重连按钮（不 reload、不关 WS）。
            assert!(
                s.contains("button[data-phase=\"connecting\"],button[data-phase=\"disconnected\"]"),
                "必须定位 DSH 原生重连 indicator: {s}"
            );
            assert!(
                s.contains("if(r.ok && !muxOk()) __clickReconnectIndicator"),
                "ping 通且 mux 死才许点击: {s}"
            );
            assert!(
                s.contains("__reconnectClickLast<30000"),
                "自动点击必须 30s 限速: {s}"
            );
            assert!(
                s.contains("__reconnectClicks>=2"),
                "一次掉线最多点 2 次，禁止 5s 点击风暴: {s}"
            );
            assert!(
                s.contains("phase==='connecting' && __reconnectClicks>=1"),
                "connecting 状态只许点 1 次，别和 DSH 重拨互相打断: {s}"
            );
            assert!(
                s.contains("window.__mycoMux=ws"),
                "测试钩子要暴露当前 mux（只关自己，不碰其它 WS）: {s}"
            );
            assert!(
                s.contains("wsClose:1") && s.contains("clean:!!(ev&&ev.wasClean)"),
                "mux close 必须上报 code/reason/wasClean/可见性: {s}"
            );
            assert!(
                s.contains("__reportPageState('visible')")
                    && s.contains("__reportPageState('freeze')")
                    && s.contains("__reportPageState('resume')"),
                "必须记录 visibility/freeze/resume 生命周期: {s}"
            );
            // 2026-10-27 用户可见文案取证：sight 上报必须先于 mux 健康短路，
            // 否则“重连字样一闪、mux 仍健康”的真实现场会被漏报。
            let sight = s.find("sight:snip").expect("必须上报用户可见重连文案");
            let healthy = s
                .find("if(muxOk()&&muxAge()<30000) return")
                .expect("必须有 mux 健康短路");
            assert!(sight < healthy, "sight 取证必须先于 mux 健康 return: {s}");
            assert!(
                s.contains("__sightLast>=2000"),
                "sight 上报需限流防刷屏: {s}"
            );
        }

