        #[test]
        fn client_assert_rejects_owner_name_spoof() {
            let seed = [13u8; 32];
            let sid = "sh-owner";
            let ts = now_ms();
            let (did, sig) = ca_sign(&seed, sid, ts);
            let hdr = ca_header("DESKTOP-PC", &did, ts, &sig);
            let other_tail = if did_tail4(&did) == "x7oj" {
                "zzzz"
            } else {
                "x7oj"
            };
            assert!(
                client_assert_label(Some(&hdr), sid, &format!("DESKTOP-PC·{other_tail}")).is_none(),
                "别的设备 did 不能顶着票上设备名署名（不可冒充 owner）"
            );
            // 同一个 did（尾相同）→ 那确实是这台设备，允许
            assert!(client_assert_label(
                Some(&hdr),
                sid,
                &format!("DESKTOP-PC·{}", did_tail4(&did))
            )
            .is_some());
            // 正常协作者设备名 → 允许（显示实际打字设备）
            let hdr2 = ca_header("LAPTOP-DACG4GGQ", &did, ts, &sig);
            assert!(client_assert_label(Some(&hdr2), sid, "DESKTOP-PC·x7oj").is_some());
        }

