        /// 2026-10-27 真案：旧 `myco_client_assert` Path=/ 不分端口、不分分享，
        /// sh-275 的断言被带到 sh-pc-env-dsh 后验签失败，署名回落源 PC。
        /// 专用 cookie 必须优先，且 legacy 候选要逐个验签，不能拿第一个当真。
        #[test]
        fn client_assert_cookie_is_scoped_per_share() {
            let _g = test_isolated_config_dir();
            let wrong_for_current =
                client_assert_cookie_value("sh-other").expect("本机设备断言必须可签");
            let right_for_current =
                client_assert_cookie_value("sh-current").expect("本机设备断言必须可签");
            let cookie_hdr = format!(
            "myco_gw_sh-current=TICKET; myco_client_assert={wrong_for_current}; myco_client_assert_sh-current={right_for_current}"
        );
            let local_did = myco_core::identity::device_identity()
                .map(|(d, _)| d)
                .expect("设备身份必须可用");
            let got = client_assert_from_cookie_hdr(&cookie_hdr, "sh-current")
                .expect("当前分享专用 cookie 必须盖过 legacy 全局 cookie");
            assert_eq!(got.did, local_did);
            assert_eq!(got.name, sanitize_client_name(&local_device_name()));

            // 真机 14:37/21:21 形状：旧页面发无效 x-myco-client，但请求里有当前分享
            // 专用 cookie。入口解析必须忽略坏 x，直接用已验签 scoped cookie。
            let mut hm = HeaderMap::new();
            hm.insert("x-myco-client", "invalid-assert".parse().unwrap());
            hm.insert(header::COOKIE, cookie_hdr.parse().unwrap());
            let via_request = client_assert_from_request(&hm, "sh-current")
                .expect("无效 x 头不得遮蔽当前分享专用 cookie");
            assert_eq!(via_request.did, local_did);
        }

        /// （`conn_fragment_appended_only_with_mode` 已随 `with_conn_fragment` 一起
        /// 删除——连接模式 fragment 是 legacy mt/隧道 302 路径的产物。）

        /// **不变量锁**（2026-10-12 拆 LAN 直连）：分享入口只有隧道一种形态，
        /// 不允许再出现"把源机内网地址给请求方"的路径。
        ///
        /// 为什么用源码扫描而不是行为断言：这条铁律的价值就在"谁都不许再加回来"，
        /// 而加回来的典型手法恰恰是悄悄塞回一个字段/一次探测。直接扫本文件——
        /// 出现任何一个被拆掉的符号名即失败（needle 用 concat! 拼，避免测试自己
        /// 命中自己）。
        #[test]
        fn no_lan_direct_path_remains() {
            let src = include_str!("dsh_share.rs");
            for needle in [
                concat!("gw", "Addr"),
                concat!("lan_", "ipv4"),
                concat!("gw_direct_", "reachable"),
                concat!("REMOTE_GW_", "ADDR"),
                concat!("LAN_PROBE_", "FAIL"),
            ] {
                assert!(
                    !src.contains(needle),
                    "LAN 直连路径必须保持拆除状态，但源码里又出现了 `{needle}`：\
                 入口只能给 http://127.0.0.1:<隧道口>/gw/<id>/（网关只绑 loopback，\
                 不把源机内网地址暴露给请求方）"
                );
            }
            // 正面锚点：隧道入口形态还在（拆过头的哨兵）。
            assert!(
                src.contains("http://127.0.0.1:{local_port}/gw/{share_id}/?mt={mt}"),
                "隧道入口必须保留"
            );
        }

        /// 静态资源缓存策略：js/字体/带 rev= 的 bundle → immutable 长缓存；
        /// HTML 与 API JSON 一律不动（页面/接口必须新鲜）。
        #[test]
        fn static_cache_policy_for_assets_and_pages() {
            let im = "public, max-age=86400, immutable";
            assert_eq!(
                static_cache_policy("assets/index-CaFe12.js", Some("application/javascript")),
                Some(im)
            );
            assert_eq!(
                static_cache_policy("assets/ui.9f3ab2c1.css", Some("text/css")),
                Some(im)
            );
            assert_eq!(
                static_cache_policy("fonts/inter.woff2", Some("font/woff2")),
                Some(im)
            );
            assert_eq!(
                static_cache_policy(
                    r"plugins??@deepseek/client.js,@deepseek/client.js&rev=42",
                    None
                ),
                Some(im),
                "dsh 插件 bundle 带 rev=：版本化 URL 长缓存安全"
            );
            assert_eq!(
                static_cache_policy("", Some("text/html; charset=utf-8")),
                None,
                "HTML 永不缓存"
            );
            assert_eq!(static_cache_policy("index.html", None), None);
            assert_eq!(
                static_cache_policy("api/session/list", Some("application/json")),
                None,
                "API 不动"
            );
            assert_eq!(static_cache_policy("api/remote.mux", None), None);
        }

        /// ⑤ 续签的**硬约束**：只许不变或变长。owner 的 365 天长票绝不能被"续"成 30 分钟；
        /// 窄票则滑到 `min(now+30min, grant.exp)`。
        #[test]
        fn renewal_never_shortens_and_slides_narrow_ticket() {
            let now = 1_000_000_000_000u64;
            let day = 24 * 3600 * 1000u64;
            let mut s = test_share(vec![Grant {
                label: "小王".into(),
                did: Some("did:youling:w".into()),
                ro: false,
                exp: now + 7 * day,
                window_ms: None,
                caps: None,
                visibility: None,
            }]);
            s.id = "sh-ren".into();

            // 长票（owner 365 天）→ 不续（否则等于把长票"续"短）
            let long = MtRoot {
                raw_label: "小王".into(),
                did: Some("did:youling:w".into()),
                ro: false,
                exp: now + 365 * day,
                display_did: None,
            };
            assert_eq!(
                long.renewed_exp(&s, now),
                Some(now + 365 * day),
                "长票保持原样"
            );
            // 窄票（180s 后到期）→ 滑到 now+30min
            let narrow = MtRoot {
                raw_label: "小王".into(),
                did: Some("did:youling:w".into()),
                ro: false,
                exp: now + 180_000,
                display_did: None,
            };
            assert_eq!(
                narrow.renewed_exp(&s, now),
                Some(now + MT_RENEW_TTL_MS),
                "窄票滑到 30 分钟"
            );
            // grant 只剩 5 分钟 → 续签**不得超过授权本身的寿命**（只许收紧不许放大）
            s.grants[0].exp = now + 5 * 60_000;
            assert_eq!(
                narrow.renewed_exp(&s, now),
                Some(now + 5 * 60_000),
                "上限是 grant 行"
            );
            // grant 行已过期/被删 → 不续（吊销秒生效，票自然到期）
            s.grants[0].exp = now - 1;
            assert_eq!(narrow.renewed_exp(&s, now), None, "grant 过期就不续");
            s.grants.clear();
            assert_eq!(narrow.renewed_exp(&s, now), None, "grant 被删就不续");
        }

        /// 2026-10-11 回归（目标链实测事故）：mt 续签重签必须保留 dd（请求方设备 DID）。
        /// 事故链：remoteOpen 现签窄票带 dd（笔记本署名应为 "laptop·XXXX："）→ 入口把
        /// 窄票续签成长票写 cookie 时用 sign_mt_exp（不带 dd）→ cookie 丢 dd → 发言
        /// 署名退化成 "owner："（实测 seq 17810 抓到）。修法=MtRoot 携带 display_did +
        /// sign_mt_disp_aware 两处续签点共用。
        #[test]
        fn mt_renew_preserves_display_did() {
            let now = now_ms();
            let mut s = test_share(vec![Grant {
                label: "owner".into(),
                did: None,
                ro: false,
                exp: now + 7 * 24 * 3600 * 1000,
                window_ms: None,
                caps: None,
                visibility: None,
            }]);
            s.id = "sh-dd".into();
            let laptop = "did:myco:laptopdev99";
            // ① remoteOpen 形态窄票（带 dd）→ 验签可读回 dd
            let narrow = sign_mt_exp_disp(&s.id, "owner", None, false, now + 180_000, Some(laptop));
            let c = verify_mt(&narrow, &s.id).expect("带 dd 窄票应可验签");
            assert_eq!(c.display_did.as_deref(), Some(laptop), "窄票应带 dd");
            // ② 票根带 dd → 重签后 dd 必须仍在（入口换票/心跳滑窗共用路径）
            let root = MtRoot {
                raw_label: "owner".into(),
                did: None,
                ro: false,
                exp: now + 180_000,
                display_did: Some(laptop.into()),
            };
            let renewed = sign_mt_disp_aware(&s.id, &root, now + MT_RENEW_TTL_MS);
            let c2 = verify_mt(&renewed, &s.id).expect("重签票应可验签");
            assert_eq!(
                c2.display_did.as_deref(),
                Some(laptop),
                "重签后 dd 必须保留（署名不退化）"
            );
            // ③ 展示名走 dd → 设备尾号形态（而非裸 label）
            let label = display_label(&c2.label, c2.display_did.as_deref().or(c2.did.as_deref()));
            assert!(label.ends_with("ev99"), "展示名应带设备尾号：{label}");
            // ④ 对照：无 dd 票根重签 → 仍无 dd（既有行为不变）
            let root2 = MtRoot {
                raw_label: "owner".into(),
                did: None,
                ro: false,
                exp: now + 180_000,
                display_did: None,
            };
            let renewed2 = sign_mt_disp_aware(&s.id, &root2, now + MT_RENEW_TTL_MS);
            let c3 = verify_mt(&renewed2, &s.id).expect("无 dd 重签票应可验签");
            assert!(c3.display_did.is_none(), "无 dd 票重签后仍无 dd");
        }

        // 2026-10-12：原先那两条 LAN 直连相关测试（地址合法性 / 探测快速失败）随该
        // 功能一起拆除；替代它们的是上面的 `no_lan_direct_path_remains` 不变量锁。

        /// ⑥ 什么时候才发 `Set-Cookie`：远离到期不折腾；票根不在（ticket 轨）不折腾。
        #[test]
        fn renewal_cookie_only_when_close_to_expiry() {
            let _g = test_isolated_config_dir();
            let now = now_ms();
            let mut s = test_share(vec![Grant {
                label: "小王".into(),
                did: Some("did:youling:w".into()),
                ro: false,
                exp: now + 7 * 24 * 3600 * 1000,
                window_ms: None,
                caps: None,
                visibility: None,
            }]);
            s.id = "sh-ren2".into();
            // 远离到期（180s > 60s 余量）→ 不发
            let far = owner_authz(vis_all());
            let far = Authz {
                mt: Some(MtRoot {
                    raw_label: "小王".into(),
                    did: Some("did:youling:w".into()),
                    ro: false,
                    exp: now + 180_000,
                    display_did: None,
                }),
                ..far
            };
            assert!(renewed_mt_cookie(&s, &far, now).is_none(), "还没到期不折腾");
            // 快到期（30s < 60s 余量）→ 发，且 cookie 名/属性正确
            let near = Authz {
                mt: Some(MtRoot {
                    raw_label: "小王".into(),
                    did: Some("did:youling:w".into()),
                    ro: false,
                    exp: now + 30_000,
                    display_did: None,
                }),
                ..owner_authz(vis_all())
            };
            let c = renewed_mt_cookie(&s, &near, now).expect("临近到期必须续");
            assert!(
                c.starts_with(&format!("{}=", share_cookie_name("sh-ren2"))),
                "{c}"
            );
            assert!(c.contains("HttpOnly"), "{c}");
            assert!(c.contains("Path=/"), "{c}");
            // 没有票根（ticket 轨）→ 不发
            assert!(
                renewed_mt_cookie(&s, &owner_authz(vis_all()), now).is_none(),
                "ticket 轨不参与 mt 续签"
            );
        }

