        /// 地址映射只在已知前缀且唯一时成立；同 /64 多设备必须拒绝猜测。
        #[cfg(feature = "gui")]
        #[test]
        fn inbound_address_mapping_requires_unique_device() {
            let unique = vec![("did:myco:a".to_string(), "192.168.1.5".to_string())];
            assert_eq!(
                inbound_device_for_entry("192.168.1.5:9100", &unique).as_deref(),
                Some("did:myco:a")
            );
            assert_eq!(inbound_device_for_entry("192.168.1.6:9100", &unique), None);
            assert_eq!(
                inbound_device_for_entry("192.168.1.50:9100", &unique),
                None,
                "IPv4 必须整段相等，.5 不得误吃 .50"
            );
            assert_eq!(
                inbound_device_for_entry("did:myco:direct", &[]).as_deref(),
                Some("did:myco:direct")
            );
            let same_subnet = vec![
                ("did:myco:a".to_string(), "3fff:390:a95:62c0".to_string()),
                ("did:myco:b".to_string(), "3fff:390:a95:62c0".to_string()),
            ];
            assert_eq!(
                inbound_device_for_entry("[3fff:390:a95:62c0::2]:9100", &same_subnet),
                None,
                "同 /64 的两台设备不得被同一条入站地址同时认领"
            );
        }

        /// kept ∪ 活跃 合并：kept 在前带 label 口、动态补后、同 (device,port) 去重。
        #[cfg(feature = "gui")]
        #[test]
        fn vnet_status_merge_forwards_dedup_and_order() {
            let kept = vec![
                json!({"device": "did:a", "port": 3389, "localPort": 23389, "label": "RDP"}),
                json!({"device": "did:b", "port": 22, "localPort": 22222, "label": ""}),
            ];
            let live = vec![
                ("did:a".to_string(), 3389u16, 23389u16), // 与 kept 重复 → 只留 kept 那条
                ("did:c".to_string(), 13911u16, 54321u16), // 动态隧道 → 补后
            ];
            let got = vnet_status_merge_forwards(&kept, &live);
            assert_eq!(got.len(), 3, "去重后 3 条");
            assert_eq!(got[0], ("did:a".into(), 3389, 23389, true), "kept 在前");
            assert_eq!(got[2], ("did:c".into(), 13911, 54321, false), "动态补后");
            // 坏行（缺 device/port）不进表
            let bad = vec![json!({"port": 22}), json!({"device": "did:x", "port": 0})];
            assert!(vnet_status_merge_forwards(&bad, &[]).is_empty());
        }

