        /// 闸门：端口只认 3389、固定口不许占保留口、device 必须是已知 DID。
        #[cfg(feature = "gui")]
        #[test]
        fn rdp_validate_gate_rejects_ssh_port_and_unknown_did() {
            let did = "did:myco:z6MkuyFrKzJAzUQSi4D8nfDr9EkkibvY3NdHL2oqyCJBx7oj";
            // ① 22（SSH）不做 RDP——先于身份判定，任何 device 都拒
            let e = rdp_validate(did, 22, RDP_DEFAULT_LOCAL).unwrap_err();
            assert!(e.contains("3389"), "错误要说清只支持 3389：{e}");
            // ② 固定口太小 / 占了 myco 自己的口
            assert!(rdp_validate(did, RDP_PORT, 80).is_err(), "<1024 拒绝");
            assert!(rdp_validate(did, RDP_PORT, 9100).is_err(), "p2p 保留口拒绝");
            assert!(
                rdp_validate(did, RDP_PORT, 13911).is_err(),
                "网关保留口拒绝"
            );
            // ③ device 未知/不成形 → 拒
            assert!(
                rdp_validate("", RDP_PORT, RDP_DEFAULT_LOCAL).is_err(),
                "空 device 拒绝"
            );
            assert!(
                rdp_validate("did:myco:nope", RDP_PORT, RDP_DEFAULT_LOCAL).is_err(),
                "未知 DID 拒绝"
            );
            assert!(
                rdp_validate("127.0.0.1:3102", RDP_PORT, RDP_DEFAULT_LOCAL).is_err(),
                "非 DID 拒绝"
            );
        }

