        /// `.rdp` 正文：三个必需键 + CRLF；用户名里的换行/控制字符必须被净化
        /// （否则能往文件里注入 `alternate shell:s:...` 这类键）。
        #[cfg(feature = "gui")]
        #[test]
        fn rdp_file_text_has_required_keys_and_sanitizes_user() {
            let text = rdp_file_text(
                &rdp_sanitize_user("jason\r\nalternate shell:s:cmd.exe"),
                "127.0.0.1:23389",
            );
            assert!(text.contains("full address:s:127.0.0.1:23389"), "{text}");
            assert!(text.contains("username:s:jason"), "{text}");
            assert!(text.contains("prompt for credentials:i:1"), "{text}");
            assert!(
                !text.contains("alternate shell"),
                "换行注入必须被吃掉：{text}"
            );
            assert!(
                text.ends_with("\r\n") && text.lines().count() == 3,
                "恰好三行：{text:?}"
            );
            // 中文用户名→UTF-16LE+BOM（mstsc 对无 BOM 的 UTF-8 中文会读乱）
            let ascii = rdp_file_text("jason", "127.0.0.1:23389");
            assert_eq!(
                rdp_file_bytes(&ascii),
                ascii.as_bytes().to_vec(),
                "纯 ASCII 原样写"
            );
            let cn = rdp_file_text("张伟", "127.0.0.1:23389");
            let bytes = rdp_file_bytes(&cn);
            assert_eq!(&bytes[..2], &[0xFF, 0xFE], "非 ASCII 必须 UTF-16LE BOM");
        }

