            assert!(client.contains("SELF=false"), "客户端页 SELF=false");
            assert!(!client.contains("手机上："), "PC 页不该出现手机提示");
            // 手机：主按钮隐藏 + 复制地址的降级提示
            let phone = rdp_open_page(did, RDP_PORT, RDP_DEFAULT_LOCAL, true, false, false);
