    #[test]
    fn filter_caps_by_flags_matrix() {
        let caps = json!({"o":[{"id":"session.read","label":"x","methods":["session/page"]}],
        "a":[{"id":"session.input","label":"x","methods":["session/prompt"]},
             {"id":"model.select","label":"x","methods":["model/"]}]});
        let f = filter_caps_by_flags(&caps, &json!({}), false);
        assert!(
            caps_declares(&f, "session/page") && caps_declares(&f, "model/"),
            "账号层缺项=继承"
        );
        let f_off = filter_caps_by_flags(&caps, &json!({}), true);
        assert!(!caps_declares(&f_off, "model/"), "设备/最终层缺项=默认关");
        let f2 = filter_caps_by_flags(
            &caps,
            &json!({"model.select": true, "session.input": false}),
            true,
        );
        assert!(caps_declares(&f2, "model/") && !caps_declares(&f2, "session/prompt"));
        let dyn_caps = json!({"o":[],"a":[{"id":"approval.decide","label":"x","methods":["approval/decide"]}]});
        assert!(caps_declares(
            &filter_caps_by_flags(&dyn_caps, &json!({}), true),
            "approval/decide"
        ));
    }

