    /// 真机 sh-pc-env-dsh 形状：authorized-dids 的 ownerRootDid 为空，但源 PC 本地
    /// 有账号签名且未过期的笔记本委任状。署名必须据此识别同账号设备，不能打成 MYCO。
    #[test]
    fn local_delegation_record_identifies_unresolved_roster_device() {
        fn pub_bytes(sk: &ed25519_dalek::SigningKey) -> [u8; 32] {
            sk.verifying_key().to_bytes()
        }
        let account_seed = [11u8; 32];
        let account_sk = ed25519_dalek::SigningKey::from_bytes(&account_seed);
        let account_did = myco_core::identity::did_from_public(&pub_bytes(&account_sk));
        let device_sk = ed25519_dalek::SigningKey::from_bytes(&[12u8; 32]);
        let device_did = myco_core::identity::did_from_public(&pub_bytes(&device_sk));
        let device_pub_b64 = {
            use base64::Engine as _;
            base64::engine::general_purpose::STANDARD.encode(pub_bytes(&device_sk))
        };
        let _g = test_isolated_config_dir();
        myco_core::delegation::Delegations::load()
            .issue_for(&account_seed, &account_did, &device_pub_b64, "笔记本", None)
            .expect("测试委任状必须能写入隔离配置");
        let delegation = myco_core::delegation::issue_with_ttl(
            &account_seed,
            &account_did,
            &device_pub_b64,
            "笔记本",
            None,
            3600_000,
            "d-test",
        );
        let records = vec![myco_core::delegation::DelegationRecord {
            delegation,
            revoked: false,
            last_renewed: now_ms(),
        }];
        assert!(device_delegated_to_account_records(
            &device_did,
            &account_did,
            &records
        ));
        // 端到端签名词形也必须走同账号设备前缀：孤立看 helper 通过还不够，
        // 真机回归点正是 signature_label_with_assert 在名册缺失时的出口。
        let mut s = policy_share();
        s.owner_account = Some(account_did.clone());
        s.device_policies.clear();
        let ca = ClientAssert {
            did: device_did.clone(),
            name: "笔记本".into(),
        };
        let label = signature_label_with_assert(
            &s,
            DevicePolicyMode::Legacy,
            Some(ADMIN_DEV),
            Some(&ca),
            "DESKTOP-KJS1H2L·x7oj",
        );
        assert_eq!(label, format!("设备·笔记本·{}", did_tail4(&device_did)));
    }

