    #[test]
    fn authorize_entry_device_level_vs_source_admin() {
        let mut s = test_share(vec![pol_grant("owner", Some(ADMIN_DEV))]);
        s.owner_account = Some(OWNER_ACCT.into());
        s.admin_device = Some(ADMIN_DEV.into());
        s.policy_version = 1;
        s.state_visibility = json!({"space":"session","sessions":["s1"],"windowMs":null});
        let exp = now_ms() + 3_600_000;
        let env_new = DevicePolicyMode::New;
        // 2026-10-27 hotfix P1-3：admin 票必须带 dd（entry_device 才能定位到 adminDevice
        // 设备——无 dd 的票按 claims.did 反推设备不再判 admin）
        let mt_admin =
            sign_mt_exp_disp(&s.id, "owner", Some(ADMIN_DEV), false, exp, Some(ADMIN_DEV));
        let a1 =
            authorize_entry_with(&mt_admin, &s, env_new, &fake_account).expect("admin 票必须能进");
        assert!(a1.admin);
        assert_eq!(a1.role, ROLE_SOURCE_ADMIN);
        assert!(caps_declares(&a1.caps, "terminal/exec"), "admin 例外");
        assert!(a1.vis.is_all_visible());
        let mt_lap = sign_mt_exp_disp(
            &s.id,
            "owner",
            Some(ADMIN_DEV),
            false,
            exp,
            Some(LAPTOP_DEV),
        );
        let a2 = authorize_entry_with(&mt_lap, &s, env_new, &fake_account).expect("同账号设备能进");
        assert!(!a2.admin);
        assert_eq!(a2.role, ROLE_OWNER_DEVICE);
        assert_eq!(a2.device.as_deref(), Some(LAPTOP_DEV));
        assert!(!caps_declares(&a2.caps, "terminal/exec"));
        assert!(caps_declares(&a2.caps, "session/page"));
        assert!(!a2.vis.is_all_visible());
        // v0 分享：旧语义（升级不改行为）
        let mut s0 = s.clone();
        s0.policy_version = 0;
        let a3 = authorize_entry_with(&mt_lap, &s0, env_new, &fake_account).expect("legacy 票能进");
        assert!(a3.admin);
        // 进程级回滚开关
        let a4 = authorize_entry_with(&mt_lap, &s, DevicePolicyMode::Legacy, &fake_account)
            .expect("回滚能进");
        assert!(a4.admin);
        // ⑤ 配置面：只有 source PC（adminDevice）能远程改权限（裁决 ②）
        let sid = format!("sh-admin-gate-{:x}", now_ms());
        {
            let mut sh = test_share(vec![pol_grant("owner", Some(ADMIN_DEV))]);
            sh.id = sid.clone();
            sh.owner_account = Some(OWNER_ACCT.into());
            sh.admin_device = Some(ADMIN_DEV.into());
            sh.policy_version = 1;
            shares().shares.lock().unwrap().push(sh);
        }
        assert!(
            share_admin_request_allowed(&sid, ADMIN_DEV),
            "source PC 可改配置"
        );
        assert!(
            !share_admin_request_allowed(&sid, LAPTOP_DEV),
            "同账号非源设备默认不可改配置"
        );
        assert!(
            !share_admin_request_allowed(&sid, ""),
            "缺设备身份不可改配置"
        );
        // v0 存量保持旧行为（同账号即可，避免升级锁死）
        {
            let mut sh = test_share(vec![pol_grant("owner", Some(ADMIN_DEV))]);
            sh.id = format!("{sid}-legacy");
            sh.owner_account = Some(OWNER_ACCT.into());
            sh.policy_version = 0;
            shares().shares.lock().unwrap().push(sh);
        }
        assert!(
            share_admin_request_allowed(&format!("{sid}-legacy"), LAPTOP_DEV),
            "v0 存量保持旧行为"
        );
    }

