    #[test]
    fn hotfix_device_ro_can_only_add_readonly() {
        let mut s = policy_share();
        s.grants.first_mut().unwrap().ro = true; // 继承层已只读
        s.device_policies
            .push(pol(LAPTOP_DEV, ROLE_OWNER_DEVICE, json!({}), None, |p| {
                p.ro = Some(false)
            }));
        let g = s.grants.first().unwrap().clone();
        let p = resolve_pol(
            &s,
            Some(LAPTOP_DEV),
            Some(LAPTOP_DEV),
            DevicePolicyMode::New,
        );
        let r = compose(&s, &p, Some(&g));
        assert!(
            r.ro,
            "devicePolicies.ro 只能加只读，不能把继承的只读改回读写"
        );
    }

