// ═══════════════════════════════════════════════════════════════════════════
// §3.23 转授闸（canReshare）·单测
//
// 三条边界各自一条"钉住"的用例（用户口径里的硬要求）：
//   ① 票不可传递          → `narrow_mt_bound_to_requester_is_not_transferable`
//   ② 非 owner 转发要过闸  → `reshare_default_denies_non_owner_forward`
//   ③ 转授不超期 + 链式吊销 → `delegated_grant_never_outlives_parent`
//                            `revoking_parent_grant_kills_delegation_live`
// 加：主人同意路径（待批准 → 批准 → 记录落地 + 源设备发卡）与数据面落盘形状。
// ═══════════════════════════════════════════════════════════════════════════
#[cfg(test)]
mod reshare_tests {
    use super::tests::isolated_cfg as test_isolated_config_dir;
    use super::*;

    const A_ACCT: &str = "did:youling:zReshareAlice";
    const B_ACCT: &str = "did:youling:zReshareBob";
    const B_DEV: &str = "did:youling:zReshareBobDev";
    const C_ACCT: &str = "did:youling:zReshareCarol";
    const MY_ACCT: &str = "did:youling:zReshareOwner";

    fn live(label: &str, did: Option<&str>) -> Grant {
        Grant {
            label: label.into(),
            did: did.map(String::from),
            ro: false,
            exp: now_ms() + 7 * 24 * 3600 * 1000,
            window_ms: None,
            caps: None,
            visibility: None,
        }
    }

    fn share_with(id: &str, grants: Vec<Grant>) -> Share {
        Share {
            id: id.into(),
            title: "转授用例".into(),
            env: Vec::new(),
            granularity: "session".into(),
            cwd: String::new(),
            session_id: Some("s-reshare".into()),
            created_at: now_ms(),
            home_key: id.into(),
            grants,
            caps: default_caps(),
            listing: "private".into(),
            state_visibility: visibility_default(),
            task_card: None,
            state: ST_ACTIVE.into(),
            group_id: None,
            owner_account: None,
            admin_device: None,
            device_policies: Vec::new(),
            policy_version: 0,
        }
    }

    fn rows(id: &str) -> Vec<Grant> {
        shares()
            .shares
            .lock()
            .unwrap()
            .iter()
            .find(|s| s.id == id)
            .map(|s| s.grants.clone())
            .unwrap_or_default()
    }

    // ── ① 票不可传递 ──

    /// **边界①钉住**：窄 mt 绑定请求方 DID —— 换人过不了入口、换分享过不了入口、
    /// 不在名单的第三人根本拿不到票，而且它只有三分钟寿命（拷走也不值钱）。
    #[test]
    fn narrow_mt_bound_to_requester_is_not_transferable() {
        let _g = test_isolated_config_dir();
        let sid = format!("sh-mtx-{:x}", now_ms());
        let now = now_ms();
        let s = share_with(&sid, vec![live("owner", None), live("小B", Some(B_ACCT))]);
        crate::share_auth::shared().upsert_device(
            B_ACCT,
            "小B",
            None,
            Some(true),
            Some(vec![format!("task:{sid}")]),
            None,
        );
        // A 侧现签：票只签给**请求方 B**
        let plan = decide_share_entry_grant(&s, MY_ACCT, B_ACCT, true, now).unwrap();
        let mt = plan.mt(&sid);
        let c = verify_mt(&mt, &sid).expect("票应可验签");
        assert_eq!(c.did.as_deref(), Some(B_ACCT), "票绑定请求方 DID");
        // 入口能过（票与 grant 行逐字对账）
        assert!(authorize_entry(&mt, &s).is_some(), "本人在册应放行");
        // ①-a **换人**：同一 label、不同 did 的 grant 行 → 票对不上（label+did+ro+exp 精确比对）
        let s_other = share_with(&sid, vec![live("owner", None), live("小B", Some(C_ACCT))]);
        crate::share_auth::shared().upsert_device(
            C_ACCT,
            "小B",
            None,
            Some(true),
            Some(vec![format!("task:{sid}")]),
            None,
        );
        assert!(
            authorize_entry(&mt, &s_other).is_none(),
            "同一 label 换个人：票必须过不了入口"
        );
        // ①-b **换分享**：票只对这一个 share 有效 + 换入口必须拒
        assert!(
            verify_mt(&mt, "sh-someone-else").is_none(),
            "票只对签它的那一个分享有效"
        );
        let mut s_share = s.clone();
        s_share.id = "sh-someone-else".into();
        assert!(
            authorize_entry(&mt, &s_share).is_none(),
            "换分享入口必须拒绝"
        );
        // ①-c 第三人（不在名单）根本拿不到票
        let deny = decide_share_entry_grant(&s, MY_ACCT, C_ACCT, true, now)
            .expect_err("不在名单的第三人不得拿到票");
        assert!(deny.contains("不在这个任务的授权名单"), "{deny}");
        // ①-d 短 TTL（不是 owner 那种一年票）
        assert!(
            c.exp <= now + REMOTE_MT_TTL_SEC * 1000 + 5_000,
            "窄票寿命必须短：{}",
            c.exp
        );
    }

    // ── ② 非 owner 转发要过闸 ──

    /// **边界②钉住**：`canReshare` 默认 false → 非 owner 转发**默认拒绝**，
    /// 人话里点明"要经主人同意"并告知申请已递出；主人开过转授权才放行，
    /// 且放行时给出的上限就是源设备签的那个 exp（继承的入口）。
    #[test]
    fn reshare_default_denies_non_owner_forward() {
        let now = now_ms();
        let card = CardReshare {
            can_reshare: false,
            exp: now + 86_400_000,
            via: "小B".into(),
            share_id: "sh-x".into(),
            source_account: A_ACCT.into(),
            source_device: "did:youling:zAliceDev".into(),
        };
        let why = reshare_forward_verdict(&card, now).expect_err("默认 false 必须拒绝转发");
        assert!(why.contains("需要主人同意"), "人话要点明主人同意：{why}");
        assert!(why.contains("转授申请"), "人话要说明已替他申请：{why}");
        assert!(
            why.contains(&did_tail4_of(A_ACCT)),
            "人话要点明是**谁**分享的：{why}"
        );
        // 主人开过转授 → 放行，上限 = 源设备给的 exp（≤ 原 grant exp）
        let allowed = CardReshare {
            can_reshare: true,
            ..card.clone()
        };
        assert_eq!(reshare_forward_verdict(&allowed, now).unwrap(), card.exp);
        // 转授权到期 → 拒（寿命就是寿命）
        let expired = CardReshare {
            can_reshare: true,
            exp: now - 1,
            ..card.clone()
        };
        let why2 = reshare_forward_verdict(&expired, now).expect_err("过期必须拒");
        assert!(why2.contains("已经到期"), "{why2}");
    }

    /// 转授 exp 的上限算式：**不得超过原 grant 的 exp**（要一年也只能到父行那天）。
    #[test]
    fn reshare_exp_cap_never_outlives_parent() {
        let now = 1_000_000u64;
        // 父行 1 小时后到期，想要 7 天 → 只能到父行 exp
        assert_eq!(
            reshare_exp_cap(now + 3_600_000, now, RESHARE_TTL_MS),
            now + 3_600_000
        );
        // 父行 30 天后到期，想要 7 天 → 7 天（不放大、也不缩短到无意义）
        assert_eq!(
            reshare_exp_cap(now + 30 * 86_400_000, now, RESHARE_TTL_MS),
            now + RESHARE_TTL_MS
        );
        // 父行已经过期 → 上限就是过去（判定层会直接拒，绝不会"续"出未来）
        assert!(reshare_exp_cap(now - 1, now, RESHARE_TTL_MS) < now);
    }

    // ── ③ 转授继承与链式吊销 ──

    /// **边界③上半**：转授记录 (a) 寿命不超过父行、(b) 不可再转授、(c) 收窄继承父行。
    #[test]
    fn delegated_grant_never_outlives_parent() {
        let _g = test_isolated_config_dir();
        let sid = format!("sh-del-{:x}", now_ms());
        let now = now_ms();
        let mut s = share_with(&sid, vec![live("owner", None), live("小B", Some(B_ACCT))]);
        // 主人给「小B」开转授权（有效到它自己的 grant exp）
        let (label, parent_exp) = set_grant_can_reshare(&mut s, B_ACCT, true, now).unwrap();
        assert_eq!(label, "小B");
        assert!(
            reshare_cap(&sid, "小B").can_reshare,
            "开过之后 canReshare=true"
        );
        // 转授给 C：**要一年**，但父行只有 7 天
        let plan = grant_apply_delegated(
            &mut s,
            "小B",
            C_ACCT,
            "小C",
            now,
            Some(365 * 24 * 3600 * 1000),
            false,
        )
        .expect("有转授权限应可转授");
        assert_eq!(
            plan.exp, parent_exp,
            "转授寿命必须被父行 exp 截断（不得超过原 grant）"
        );
        assert!(plan.exp <= parent_exp);
        // 转授行本身：不可再转授 + 血缘指向父行 + ro/caps 继承
        let g = s
            .grants
            .iter()
            .find(|g| g.label == plan.label)
            .cloned()
            .expect("转授行必须落进 grants");
        assert_eq!(g.did.as_deref(), Some(C_ACCT));
        assert_eq!(g.exp, parent_exp);
        assert!(!g.ro, "ro 继承父行（父行 rw → 转授 rw）");
        assert!(g.caps.is_none(), "caps 继承父行（父行 None=继承任务级）");
        let cap = reshare_cap(&sid, &plan.label);
        assert!(!cap.can_reshare, "转授不可再转授（要再转授，主人再批一次）");
        assert_eq!(cap.via.as_deref(), Some("小B"), "血缘指向父 grant label");
        assert_eq!(cap.exp, parent_exp);
        // 幂等：同一被转授者 + 同一父行 → 刷新，不新增第二行
        let before = s.grants.len();
        let again = grant_apply_delegated(&mut s, "小B", C_ACCT, "小C", now, None, false).unwrap();
        assert_eq!(again.label, plan.label, "重复转授必须刷新同一条记录");
        assert_eq!(s.grants.len(), before, "绝不出现第二条转授行");
        // 链上活着（父行还在、还开着）
        assert!(reshare_chain_ok(&s, &g, now).is_ok());
        // 闸门本身：**没有转授权限时，好友发起的转授必须被拒**；
        // 主人现场同意（owner_consent=true）则不受该闸限制——同意就是授权。
        let mut s_no = s.clone();
        s_no.id = format!("{sid}-no");
        set_grant_can_reshare(&mut s_no, B_ACCT, false, now).unwrap();
        assert!(
            grant_apply_delegated(&mut s_no, "小B", "did:youling:zX", "小X", now, None, false)
                .is_err(),
            "默认 false：好友发起的转授必须被拒"
        );
        assert!(
            grant_apply_delegated(&mut s_no, "小B", "did:youling:zX", "小X", now, None, true)
                .is_ok(),
            "主人现场同意时，父行不必先开着转授权限"
        );
    }

    /// **边界③下半（链式吊销，实时）**：主人删掉/收回父行 → 转授**当场**失效；
    /// 主人只是把父行的 canReshare 关掉 → 同样当场失效。判定**不靠缓存**：
    /// 每次 `reshare_chain_ok` / `authorize_entry` 都现查 `share.grants`。
    #[test]
    fn revoking_parent_grant_kills_delegation_live() {
        let _g = test_isolated_config_dir();
        let sid = format!("sh-rev-{:x}", now_ms());
        let now = now_ms();
        let mut s = share_with(&sid, vec![live("owner", None), live("小B", Some(B_ACCT))]);
        crate::share_auth::shared().upsert_device(
            C_ACCT,
            "小C",
            None,
            Some(true),
            Some(vec![format!("task:{sid}")]),
            None,
        );
        set_grant_can_reshare(&mut s, B_ACCT, true, now).unwrap();
        let plan = grant_apply_delegated(&mut s, "小B", C_ACCT, "小C", now, None, false).unwrap();
        // 基线：转授活着，且入口放行（这张窄票是 C 的）
        let g = s
            .grants
            .iter()
            .find(|g| g.label == plan.label)
            .cloned()
            .unwrap();
        assert!(reshare_chain_ok(&s, &g, now).is_ok(), "基线：转授应有效");
        let mt = sign_mt_exp(&sid, &plan.label, Some(C_ACCT), false, plan.exp);
        assert!(authorize_entry(&mt, &s).is_some(), "基线：转授票应过入口");
        // 吊销父行（主人的"停止分享给这个人"）
        let idx = s.grants.iter().position(|x| x.label == "小B").unwrap();
        s.grants.remove(idx);
        let g2 = s
            .grants
            .iter()
            .find(|x| x.label == plan.label)
            .cloned()
            .unwrap();
        let why = reshare_chain_ok(&s, &g2, now).expect_err("父行被删 → 转授必须失效");
        assert!(why.contains("原授权"), "人话要点明「原授权」：{why}");
        assert!(
            authorize_entry(&mt, &s).is_none(),
            "父行被删后，转授票必须过不了入口（实时）"
        );
        assert!(
            decide_share_entry_grant(&s, MY_ACCT, C_ACCT, true, now).is_err(),
            "代打开也必须拒"
        );
        // 父行回来但这回**关掉 canReshare** → 转授同样当场失效（链式吊销的第二种形态）
        s.grants.push(live("小B", Some(B_ACCT)));
        set_grant_can_reshare(&mut s, B_ACCT, false, now).unwrap();
        let g3 = s
            .grants
            .iter()
            .find(|x| x.label == plan.label)
            .cloned()
            .unwrap();
        assert!(
            reshare_chain_ok(&s, &g3, now).is_err(),
            "关掉转授权 = 挂在它下面的转授立刻失效"
        );
        assert!(
            authorize_entry(&mt, &s).is_none(),
            "关掉转授权后票也必须过不了"
        );
        // 父行过期（exp 拉到过去）→ 同样失效
        set_grant_can_reshare(&mut s, B_ACCT, true, now).unwrap();
        if let Some(p) = s.grants.iter_mut().find(|x| x.label == "小B") {
            p.exp = now - 1;
        }
        let g4 = s
            .grants
            .iter()
            .find(|x| x.label == plan.label)
            .cloned()
            .unwrap();
        assert!(
            reshare_chain_ok(&s, &g4, now).is_err(),
            "父行过期 → 转授失效"
        );
    }

    // ── 主人同意路径（待批准 → 批准） ──

    static RESHARE_SENT: std::sync::Mutex<Vec<(String, String, Value)>> =
        std::sync::Mutex::new(Vec::new());
    static RESHARE_CARDS: std::sync::Mutex<Vec<(String, Value)>> =
        std::sync::Mutex::new(Vec::new());

    fn capture_sender(
        to: String,
        kind: String,
        payload: Value,
    ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<(), String>> + Send>> {
        Box::pin(async move {
            RESHARE_SENT.lock().unwrap().push((to, kind, payload));
            Ok(())
        })
    }

    fn capture_card(
        to: String,
        card: Value,
    ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<(), String>> + Send>> {
        Box::pin(async move {
            RESHARE_CARDS.lock().unwrap().push((to, card));
            Ok(())
        })
    }

    /// 主人同意路径（最小可用）：B 递申请 → **主人侧落待批准**（任务卡上可见）→
    /// 主人批准 → (a) 生成受限转授记录、(b) 由**源设备**把卡送给第三人、
    /// (c) 回包告诉 B 结果。拒绝路径不生成记录。
    #[tokio::test]
    async fn reshare_request_pending_then_owner_approves() {
        let _g = test_isolated_config_dir();
        let sid = format!("sh-req-{:x}", now_ms());
        let now = now_ms();
        crate::chat_service::install_share_entry_sender(capture_sender);
        crate::chat_service::install_reshare_card_sender(capture_card);
        shares().shares.lock().unwrap().push(share_with(
            &sid,
            vec![live("owner", None), live("小B", Some(B_ACCT))],
        ));
        RESHARE_SENT.lock().unwrap().clear();
        RESHARE_CARDS.lock().unwrap().clear();
        // B 递转授申请（归属闸注入 true——单测不打云名册）
        let env = json!({
            "kind": "reshare-request", "from": B_ACCT, "fromDevice": B_DEV,
            "payload": reshare_request_payload(&sid, "rr-1", "小B", C_ACCT, "小C", None),
        });
        assert!(
            reshare_request_ingest_inner(&env, true).await,
            "A 侧必须处置申请"
        );
        // ① 没开 canReshare → 落**待批准**，主人侧看得见；且此刻还没有转授行
        let v = reshare_requests_view(Some(&sid));
        let reqs = v["requests"].as_array().cloned().unwrap_or_default();
        assert_eq!(reqs.len(), 1, "待批准申请应可见：{v}");
        assert_eq!(reqs[0]["targetDid"], json!(C_ACCT));
        assert_eq!(reqs[0]["requesterDid"], json!(B_ACCT));
        assert!(
            rows(&sid).iter().all(|g| g.did.as_deref() != Some(C_ACCT)),
            "没批准前不得有转授行"
        );
        // B 侧收到"待批准"回包（人话）
        {
            let sent = RESHARE_SENT.lock().unwrap();
            let last = sent
                .iter()
                .rev()
                .find(|(_, k, _)| k == "reshare-grant")
                .expect("应回包");
            assert_eq!(last.0, B_ACCT);
            assert_eq!(last.2["ok"], json!(false));
            assert!(
                last.2["error"].as_str().unwrap().contains("待批准"),
                "{}",
                last.2["error"]
            );
        }
        // ② 主人批准（remember=false：只批这一次）
        let rid = reqs[0]["requestId"].as_str().unwrap().to_string();
        let out = reshare_decide_impl(&sid, &rid, true, false)
            .await
            .expect("批准应成功");
        assert_eq!(out["approved"], json!(true));
        assert_eq!(out["targetDid"], json!(C_ACCT));
        // ③ 转授记录落地：血缘=B、寿命≤B 的 grant、不可再转授
        let gs = rows(&sid);
        let dg = gs
            .iter()
            .find(|g| g.did.as_deref() == Some(C_ACCT))
            .expect("转授行必须落地");
        let cap = reshare_cap(&sid, &dg.label);
        assert_eq!(cap.via.as_deref(), Some("小B"), "血缘指向请求方那条 grant");
        assert!(!cap.can_reshare, "转授不可再转授");
        let parent_exp = gs.iter().find(|g| g.label == "小B").unwrap().exp;
        assert!(
            dg.exp <= parent_exp,
            "转授 exp 不得超过原 grant：{} vs {}",
            dg.exp,
            parent_exp
        );
        // ④ 由**源设备**把卡送给第三人（不由好友转发——卡上的来源坐标必须是源设备）
        {
            let cards = RESHARE_CARDS.lock().unwrap();
            let (to, card) = cards
                .iter()
                .rev()
                .find(|(t, _)| t == C_ACCT)
                .expect("必须给第三人发卡");
            assert_eq!(
                card["taskId"],
                json!(share_task_id(&sid)),
                "卡用同一个 taskId（只出现一张）"
            );
            assert_eq!(card["shareId"], json!(sid));
            assert_eq!(card["canReshare"], json!(false), "被转授者不可再转授");
        }
        // ⑤ 待批准队列已清空 + 请求方收到"批准"回包
        assert!(reshare_requests_view(Some(&sid))["requests"]
            .as_array()
            .unwrap()
            .is_empty());
        {
            let sent = RESHARE_SENT.lock().unwrap();
            let last = sent
                .iter()
                .rev()
                .find(|(_, k, _)| k == "reshare-grant")
                .expect("应有回包");
            assert_eq!(last.2["ok"], json!(true));
            assert_eq!(last.2["targetDid"], json!(C_ACCT));
        }
        let _ = now;
    }

    /// `remember=true`（"以后这人转授不用再问"）：同意一次 → 请求方 `canReshare` 转正，
    /// 之后它的转授申请**自动批**（第二程无需人工），而链式吊销照样管着它。
    #[tokio::test]
    async fn remembering_approval_makes_later_reshare_automatic() {
        let _g = test_isolated_config_dir();
        let sid = format!("sh-auto-{:x}", now_ms());
        crate::chat_service::install_share_entry_sender(capture_sender);
        crate::chat_service::install_reshare_card_sender(capture_card);
        shares().shares.lock().unwrap().push(share_with(
            &sid,
            vec![live("owner", None), live("小B", Some(B_ACCT))],
        ));
        // 一次申请 + 主人带 remember 批准
        let env = json!({
            "kind": "reshare-request", "from": B_ACCT, "fromDevice": B_DEV,
            "payload": reshare_request_payload(&sid, "rr-a", "小B", C_ACCT, "小C", None),
        });
        assert!(reshare_request_ingest_inner(&env, true).await);
        let rid = reshare_requests_view(Some(&sid))["requests"][0]["requestId"]
            .as_str()
            .unwrap()
            .to_string();
        reshare_decide_impl(&sid, &rid, true, true)
            .await
            .expect("批准应成功");
        assert!(
            reshare_cap(&sid, "小B").can_reshare,
            "remember=true → 请求方 canReshare 转正"
        );
        // 第二次转授给另一个人：**自动批**（不再落待批准）
        let d = "did:youling:zReshareDave";
        let env2 = json!({
            "kind": "reshare-request", "from": B_ACCT, "fromDevice": B_DEV,
            "payload": reshare_request_payload(&sid, "rr-b", "小B", d, "小D", None),
        });
        assert!(reshare_request_ingest_inner(&env2, true).await);
        assert!(
            reshare_requests_view(Some(&sid))["requests"]
                .as_array()
                .unwrap()
                .is_empty(),
            "有转授权限时不得再落待批准"
        );
        assert!(
            rows(&sid).iter().any(|g| g.did.as_deref() == Some(d)),
            "自动批必须落地转授行"
        );
        // 归属闸不过 → 拒（不落申请、不签任何东西）
        let bad = json!({
            "kind": "reshare-request", "from": "did:youling:zStranger", "fromDevice": "did:youling:zStrangerDev",
            "payload": reshare_request_payload(&sid, "rr-c", "路人", "did:youling:zEve", "Eve", None),
        });
        assert!(reshare_request_ingest_inner(&bad, false).await);
        assert!(rows(&sid)
            .iter()
            .all(|g| g.did.as_deref() != Some("did:youling:zEve")));
    }

    // ── 数据面（落盘形状）与赠卡投影 ──

    /// 数据面：`share.grants[]` 每行带 `canReshare`（**默认 false**）与 `via`；
    /// 旁表 `dsh-share-reshare.json` 才是权威副本。
    #[test]
    fn save_registry_mirrors_can_reshare_into_grants() {
        let _g = test_isolated_config_dir();
        let sid = format!("sh-mirror-{:x}", now_ms());
        let now = now_ms();
        let sh = shares();
        sh.shares.lock().unwrap().push(share_with(
            &sid,
            vec![live("owner", None), live("小B", Some(B_ACCT))],
        ));
        {
            let mut list = sh.shares.lock().unwrap();
            let s = list.iter_mut().find(|s| s.id == sid).unwrap();
            set_grant_can_reshare(s, B_ACCT, true, now).unwrap();
            let plan = grant_apply_delegated(s, "小B", C_ACCT, "小C", now, None, false).unwrap();
            assert!(!plan.label.is_empty());
        }
        save_registry(&sh);
        save_reshare_caps();
        let txt = std::fs::read_to_string(data_dir().join(REGISTRY_FILE)).expect("注册表应落盘");
        let v: Value = serde_json::from_str(&txt).unwrap();
        let share = v["shares"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["id"] == json!(sid))
            .expect("分享应在注册表里");
        let gs = share["grants"].as_array().unwrap();
        let gb = gs
            .iter()
            .find(|g| g["label"] == json!("小B"))
            .expect("B 的行");
        assert_eq!(gb["canReshare"], json!(true), "主人开过的转授权限要落盘");
        assert_eq!(gb["via"], json!(null), "非转授行 via=null");
        let gc = gs
            .iter()
            .find(|g| g["did"] == json!(C_ACCT))
            .expect("转授行");
        assert_eq!(
            gc["canReshare"],
            json!(false),
            "转授行默认 false（不可再转授）"
        );
        assert_eq!(gc["via"], json!("小B"), "转授行带血缘");
        let owner = gs.iter().find(|g| g["label"] == json!("owner")).unwrap();
        assert_eq!(
            owner["canReshare"],
            json!(false),
            "没配过的行一律显式 false"
        );
        assert!(reshare_registry_path().exists(), "旁表应落盘");
    }

    /// 赠卡投影（随卡下发的"我的角色 / 我的权限"）：角色、只读位、生效 caps、
    /// 可见范围、可不可转授——UI 展示与转发闸都读它；owner 自己不带赠卡。
    #[test]
    fn card_grant_view_carries_role_perms_and_reshare_flag() {
        let _g = test_isolated_config_dir();
        let sid = format!("sh-card-{:x}", now_ms());
        let now = now_ms();
        let mut s = share_with(&sid, vec![live("owner", None), live("小B", Some(B_ACCT))]);
        set_grant_can_reshare(&mut s, B_ACCT, true, now).unwrap();
        let g = card_grant_view(&s, B_ACCT).expect("协作者应有赠卡信息");
        assert_eq!(g["role"], json!("collaborator"));
        assert_eq!(g["canReshare"], json!(true));
        assert_eq!(g["ro"], json!(false));
        assert!(g["caps"].is_object(), "生效能力集应在赠卡里：{g}");
        assert!(g["visibility"].is_object(), "生效可见范围应在赠卡里：{g}");
        assert_eq!(g["reshareVia"], json!(null), "主人直接开的转授权限没有血缘");
        // 不认识的 did / owner 自己 → 不给假权限
        assert!(card_grant_view(&s, "did:youling:zNobody").is_none());
        assert!(
            card_grant_view(&s, MY_ACCT).is_none(),
            "owner 不受限，不该被当协作者标注"
        );
    }
    // ═══ 2026-10-19「回信通道超时」根因回归（预算化重试）═══
    /// ① 第一次就成功 → 不睡、立即返回（正常路径零开销）。
    #[tokio::test]
    async fn dsh_retry_budget_returns_first_success_without_wait() {
        let t0 = std::time::Instant::now();
        let v: Result<u32, String> =
            dsh_ready_retry_budget(|| async { Ok(7) }, CLI_RETRY_BUDGET_MS).await;
        assert_eq!(v.unwrap(), 7);
        assert!(
            t0.elapsed() < std::time::Duration::from_millis(500),
            "首试成功不该等待"
        );
    }

    /// ② 非「未就绪」的真错误 → 立即冒泡（不被重试掩盖）。
    #[tokio::test]
    async fn dsh_retry_budget_does_not_retry_real_errors() {
        let t0 = std::time::Instant::now();
        let v: Result<u32, String> = dsh_ready_retry_budget(
            || async { Err("DSH 拒绝了这次调用（群不存在）".to_string()) },
            CLI_RETRY_BUDGET_MS,
        )
        .await;
        assert!(v.unwrap_err().contains("群不存在"));
        assert!(t0.elapsed() < std::time::Duration::from_millis(500));
    }

    /// ③ 忙窗第 2 次成功 → 重试并带出结果。
    #[tokio::test]
    async fn dsh_retry_budget_recovers_when_window_clears() {
        use std::sync::atomic::{AtomicU32, Ordering};
        let n = AtomicU32::new(0);
        let v: Result<u32, String> = dsh_ready_retry_budget(
            || {
                let k = n.fetch_add(1, Ordering::SeqCst);
                async move {
                    if k == 0 {
                        Err("DSH 未就绪（忙窗，401）".to_string())
                    } else {
                        Ok(42)
                    }
                }
            },
            CLI_RETRY_BUDGET_MS,
        )
        .await;
        assert_eq!(v.unwrap(), 42);
        assert_eq!(n.load(Ordering::SeqCst), 2);
    }

    /// ④ **主回归**：一直 401 时总耗时必须受预算约束（原排期最坏 39s，而调用方
    /// Invoke-RestMethod -TimeoutSec 15 早已放弃 → 实测问题形态是"通道超时"）。
    /// 预算 1200ms；同时要求失败文案自带重试节奏（≥5s、最多 3 次）且判定可重试。
    #[tokio::test]
    async fn dsh_retry_budget_fails_fast_with_retry_hint() {
        let t0 = std::time::Instant::now();
        let v: Result<u32, String> = dsh_ready_retry_budget(
            || async { Err::<u32, String>("DSH 未就绪（忙窗，401）".to_string()) },
            1_200,
        )
        .await;
        let err = v.unwrap_err();
        let took = t0.elapsed();
        assert!(
            took <= std::time::Duration::from_millis(4_000),
            "预算 1200ms 必须快速失败，实耗 {took:?}"
        );
        assert!(err.contains("≥5s"), "失败文案必须给出重试节奏：{err}");
        assert!(
            err.contains("超出本次预算"),
            "要点明是预算耗尽而不是通道坏了：{err}"
        );
        assert!(
            dsh_not_ready_err(&err),
            "仍须判定为可重试 → HTTP 503 + retryable"
        );
    }
    /// 2026-10-20：分享视图插件瘦身（纯函数）：按 env 名单摘包；摘空则整段 <script> 不输出；
    /// 名单为空 = 一个字节都不改（回归红线）。
    #[test]
    fn trim_share_plugins_keeps_core_and_drops_by_name() {
        let html = r#"<html><head><script type="module" src="plugins/??@deepseek-ai/dsh-api-gateway/client.js,@deepseek-ai/dsh-client-ui-settings-general/client.js,@deepseek-ai/dsh-client-ui-locale/client.js&rev=abc"></script><script src="plugins/??@deepseek-ai/dsh-api-terminal-controller/client.js,@deepseek-ai/dsh-api-workspace-files/client.js"></script><script src="./assets/index-x.js"></script></head><body>hi</body></html>"#;
        // 名单为空 → 逐字节原样
        assert_eq!(trim_share_plugins(html, &[]), html);
        let drop = vec![
            "client-ui-settings".to_string(),
            "terminal".to_string(),
            "workspace-files".to_string(),
        ];
        let out = trim_share_plugins(html, &drop);
        assert!(
            out.contains("@deepseek-ai/dsh-api-gateway/client.js"),
            "核心插件要保留：{out}"
        );
        assert!(
            out.contains("@deepseek-ai/dsh-client-ui-locale/client.js"),
            "locale 要保留：{out}"
        );
        assert!(out.contains("&rev=abc"), "rev 后缀要保留：{out}");
        assert!(
            !out.contains("dsh-client-ui-settings-general"),
            "命中名单要摘掉：{out}"
        );
        assert!(
            !out.contains("dsh-api-terminal-controller"),
            "terminal 要摘掉：{out}"
        );
        // 第二个复合包被摘空 → src 换成空模块（data:text/javascript,）
        assert!(
            !out.contains("dsh-api-workspace-files"),
            "workspace-files 要摘掉：{out}"
        );
        assert!(
            out.contains("data:text/javascript,"),
            "摘空后的 script 要变成空模块：{out}"
        );
        assert!(
            out.contains("./assets/index-x.js"),
            "普通资产引用不受影响：{out}"
        );
        assert_eq!(
            out.matches("plugins/??").count(),
            1,
            "只剩一个复合引用：{out}"
        );
    }

    /// 2026-10-20：帧里有**孤立代理转义**（V8 能 parse、serde 不能）时也要能裁。
    #[test]
    fn mux_session_control_trim_survives_lone_surrogate() {
        // 先用结构化 JSON 造一条合法帧，再把其中一个值替换成**孤立代理转义**
        let mut good: serde_json::Value = json!({
            "type":"item","streamId":"st-x",
            "value":{"type":"baseline","value":{"projections":{
                "session-keep":{"asOfSeq":1,"values":{"title":"ok"}},
                "session-other":{"asOfSeq":2,"values":{"title":"BADMARK"}}
            }}}
        });
        let text0 = serde_json::to_string(&good).unwrap();
        let bad = "bad".to_string() + "\\" + "uD800char"; // `bad\uD800char`（JSON 里是孤立代理转义）
        let frame = text0.replace("BADMARK", &bad);
        assert!(
            serde_json::from_str::<serde_json::Value>(&frame).is_err(),
            "夹具必须含非法转义"
        );
        // 清洗版必须能被 serde 解析
        let clean = sanitize_json_surrogates(&frame);
        if let Err(e) = serde_json::from_str::<serde_json::Value>(&clean) {
            panic!("清洗后仍解析失败：{e}；clean={clean}");
        }
        let vis = vis_of(&json!({"space":"session","sessions":["session-keep"],"windowMs":null}));
        let (out, kept, dropped) = mux_trim_session_control(&frame, &vis);
        assert_eq!((kept, dropped), (1, 1), "孤立代理转义也要能裁：{out}");
        assert!(out.contains("session-keep"));
        assert!(!out.contains("session-other"));
        // 合法代理对不受影响（清洗器不该动它）
        let ok = "{\"a\":\"".to_string() + "\\" + "uD83D" + "\\" + "uDE00" + "\"}";
        assert_eq!(sanitize_json_surrogates(&ok), ok);
        let _ = good.as_object_mut();
    }

    /// 2026-10-20：`session/control` 全量清单/投影的会话级裁剪（隐私 + 首屏）。
    /// 夹具按实测帧形状：`{"value":{"type":"baseline","value":{"projections":{sid:{asOfSeq,values}}}}}`。
    #[test]
    fn mux_session_control_trim_uses_whitelist() {
        let frame = json!({
            "type":"item","streamId":"st-ctl",
            "value":{"type":"baseline","value":{"projections":{
                "session-keep":{"asOfSeq":11,"values":{"title":"授权会话","tokenUsage":{"outputTokens":1}}},
                "session-other":{"asOfSeq":22,"values":{"title":"别人的会话"}},
                "session-third":{"asOfSeq":33,"values":{"title":"第三个"}}
            }}}
        }).to_string();
        let vis = vis_of(&json!({"space":"session","sessions":["session-keep"],"windowMs":null}));
        let (out, kept, dropped) = mux_trim_session_control(&frame, &vis);
        assert_eq!((kept, dropped), (1, 2), "只留白名单内的会话");
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        let p = v
            .pointer("/value/value/projections")
            .unwrap()
            .as_object()
            .unwrap();
        assert!(p.contains_key("session-keep"), "白名单会话要保留：{out}");
        assert!(!p.contains_key("session-other"), "别的会话必须裁掉：{out}");
        assert!(!p.contains_key("session-third"), "别的会话必须裁掉：{out}");
        assert_eq!(v["streamId"], json!("st-ctl"), "外壳字段不动");
        // 增量投影帧：白名单外 → 丢帧（空串）
        let inc_other = json!({"type":"item","streamId":"st-ctl","value":{"type":"projection","sessionId":"session-other","key":"tokenUsage","value":{}}}).to_string();
        assert_eq!(
            mux_trim_session_control(&inc_other, &vis).0,
            "",
            "白名单外的增量投影帧必须丢"
        );
        // 增量投影帧：白名单内 → 原样
        let inc_keep = json!({"type":"item","streamId":"st-ctl","value":{"type":"projection","sessionId":"session-keep","key":"tokenUsage","value":{}}}).to_string();
        assert_eq!(mux_trim_session_control(&inc_keep, &vis).0, inc_keep);
        // 认不出的形状 → 原样 + 零计数（调用方不写审计）
        let odd =
            json!({"type":"item","streamId":"st-ctl","value":{"type":"baseline","owner":true}})
                .to_string();
        let (out2, k2, d2) = mux_trim_session_control(&odd, &vis);
        assert_eq!((k2, d2), (0, 0));
        assert_eq!(out2, odd);
    }

    /// 2026-10-20：入口 HTML 资源引用与 share 解耦（跨分享浏览器缓存）。
    /// 只改资源类相对引用；导航链接/绝对 URL/API 路径一个字节不动。
    #[test]
    fn decouple_asset_urls_rewrites_only_asset_refs() {
        let html = r#"<html><base href="./"><link rel="stylesheet" href="./assets/index-BxpfOGf3.css"><script type="module" src="./assets/index-CN7NIWNw.js"></script><script src="./plugins/??@a/client.js,@b/client.js&rev=b307"></script><link rel="manifest" href="./manifest.webmanifest"><link rel="icon" href="./favicon.svg"><a href="./">home</a><a href="https://example.com/x.js">ext</a></html>"#;
        let out = decouple_asset_urls(html);
        assert!(
            out.contains(r#"src="/myco-assets/assets/index-CN7NIWNw.js""#),
            "主 bundle 要改写：{out}"
        );
        assert!(
            out.contains(r#"href="/myco-assets/assets/index-BxpfOGf3.css""#),
            "样式要改写：{out}"
        );
        // 2026-10-20（第二次）：插件复合 URL 也改写（稳定前缀 → 跨分享浏览器缓存）
        assert!(
            out.contains(r#"src="/myco-assets/plugins/??@a/client.js,@b/client.js&rev=b307""#),
            "插件路径要改写：{out}"
        );
        assert!(
            out.contains(r#"href="/myco-assets/manifest.webmanifest""#),
            "manifest 要改写：{out}"
        );
        assert!(
            out.contains(r#"href="/myco-assets/favicon.svg""#),
            "favicon 要改写：{out}"
        );
        // 非资源引用：一个字节不动
        assert!(out.contains(r#"<base href="./">"#), "base 不动：{out}");
        assert!(
            out.contains(r#"<a href="./">home</a>"#),
            "导航链接不动：{out}"
        );
        assert!(
            out.contains(r#"https://example.com/x.js"#),
            "绝对 URL 不动：{out}"
        );
        // 不含资源引用时逐字节原样
        let plain = "<html><body>hi</body></html>";
        assert_eq!(decouple_asset_urls(plain), plain);
    }
}

/// ═══ 2026-10-22 O14：分享指向的 DSH 会话是否还在 ═══
/// 只对页面首加载调用（不是每个 API 请求都查）——一次 HTTP GET /app/api/session/list
/// 检查 sessionId 是否在返回的清单里。上游不可达 = 会话不在 = 返回 false。
async fn dsh_session_alive(dsh_port: u16, session_id: &str) -> bool {
    // DSH 一元 RPC：POST /api/session/list（2026-10-22 首版写成 GET /app/api/… 全 404
    // → 所有分享被误判"不可用"，此修）。3s 超时；上游不可达/cookie 无效 = 保守放行
    // （返回 true，让代理路径的既有 503/重试逻辑兜底——不能因为探活失败把好分享也拒了）。
    let url = format!("http://127.0.0.1:{dsh_port}/api/session/list");
    let cookie = merged_cookie_header(None, mint_dsh_cookie().as_deref());
    let client = match reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(3))
        .build()
    {
        Ok(c) => c,
        Err(_) => return true, // 客户端都建不起来 → 放行（不阻塞正常分享）
    };
    let mut req = client.post(&url);
    if let Some(c) = &cookie {
        req = req.header("cookie", c);
    }
    req = req.header("origin", format!("http://127.0.0.1:{dsh_port}"));
    req = req.header("content-type", "application/json");
    req = req.body("{}");
    match req.send().await {
        Ok(resp) if resp.status().is_success() => {
            match resp.text().await {
                Ok(body) => body.contains(session_id),
                Err(_) => true, // 读不到 body → 保守放行
            }
        }
        // 上游 401/403/5xx/超时 → **放行**（可能是 cookie 窗口/DSH 忙，不能误杀好分享；
        // 代理路径的既有重试/503 逻辑会兜底给用户正确的反馈）
        _ => true,
    }
}

